window.__BOOK__ = {"meta": {"title_es": "El Principito", "title_zh": "小王子", "author_es": "Antoine de Saint-Exupéry", "author_zh": "安托万·德·圣埃克苏佩里", "voice": "es-ES-ElviraNeural (edge-tts)", "ipa_note": "音标为宽式音位转写（西班牙本土发音，ce/ci/z 发 θ），仅供参考；重音未标注。", "n_chapters": 28, "n_paras": 570, "n_sents": 1422, "audio_paras": 570}, "chapters": [{"id": "ch00", "title_es": "A Léon Werth", "title_zh": "献词", "paras": [{"id": "ch00p00", "audio": true, "sents": [{"es": "A Léon Werth.", "zh": "献给列翁·维尔特", "t": [100, 1762]}, {"es": "Pido perdón a los niños por haber dedicado este libro a una persona mayor.", "zh": "请孩子们原谅我把这本书献给了这位长者。", "t": [1762, 6400]}, {"es": "Tengo una excusa seria: esa persona mayor es el mejor amigo que tengo en el mundo.", "zh": "这位长者是我世间最挚的朋友。", "t": [6400, 11862]}, {"es": "Tengo otra excusa: esa persona mayor puede comprenderlo todo, hasta los libros para niños.", "zh": "这位长者能通晓一切，即便是对孩子的书籍。", "t": [11862, 18138]}, {"es": "Tengo una tercera excusa: esa persona mayor vive en Francia, donde tiene hambre y frío.", "zh": "这位长者住在法国，忍饥受寒。", "t": [18138, 24150]}, {"es": "Necesita ser consolada.", "zh": "需要安慰。", "t": [24150, 26588]}, {"es": "Si todas estas excusas no bastan, quiero dedicar este libro al niño que esa persona mayor fue antiguamente.", "zh": "若这些借口仍不足够，我想将此书献予那位长者曾身为孩童的往昔。", "t": [26588, 33475]}, {"es": "Todas las personas grandes han sido niños primero.", "zh": "所有的大人曾经都是孩子。", "t": [33475, 37075]}, {"es": "(Pero pocas lo recuerdan).", "zh": "但很少人记得。", "t": [37075, 39350]}, {"es": "Corrijo, pues, mi dedicatoria: A LEÓN WERTH, CUANDO ERA UN PEQUEÑO NIÑO.", "zh": "我修正我的献词：献予列翁·维尔特，他曾是孩童。", "t": [39350, 43437]}]}]}, {"id": "ch01", "title_es": "Capítulo 1", "title_zh": "第 1 章", "paras": [{"id": "ch01p00", "audio": true, "sents": [{"es": "Cuando yo tenía seis años vi en un libro sobre la selva virgen que se titulaba \"Historias vividas\", una magnífica lámina.", "zh": "六岁时，我在一本名为《历险故事》的原始森林书籍中，看到了一幅精美的插图。", "t": [100, 7538]}, {"es": "Representaba una serpiente boa que se tragaba a una fiera.", "zh": "一条蟒蛇正在吞噬一只野兽。", "t": [7538, 11612]}, {"es": "Esta es la copia del dibujo.", "zh": "这是这幅画的复制品。", "t": [11612, 13200]}]}, {"id": "ch01p01", "audio": true, "sents": [{"es": "En el libro se afirmaba: \"La serpiente boa se traga su presa entera, sin masticarla.", "zh": "书中写道：“蟒蛇将猎物整个吞下，未经咀嚼。”", "t": [100, 5725]}, {"es": "Luego ya no puede moverse y duerme durante los seis meses que dura su digestión\".", "zh": "蟒蛇消化期间，便无法动弹，沉睡六个月。", "t": [5725, 9776]}]}, {"id": "ch01p02", "audio": true, "sents": [{"es": "Reflexioné mucho en ese momento sobre las aventuras de la jungla y a mi vez logré trazar con un lápiz de colores mi primer dibujo.", "zh": "那一刻，我沉思于丛林冒险，同时用彩色铅笔勾勒出了我的第一幅画。", "t": [100, 7538]}, {"es": "Mi dibujo número 1 era de esta manera:", "zh": "我的第一幅画是这样的：", "t": [7538, 9737]}]}, {"id": "ch01p03", "audio": true, "sents": [{"es": "Enseñé mi obra de arte a las personas mayores y les pregunté si mi dibujo les daba miedo.", "zh": "我把我的画作展示给大人看，问他们我的画是否吓到了他们。", "t": [100, 5550]}, {"es": "-¿por qué habría de asustar un sombrero?", "zh": "一顶帽子有什么好怕的？", "t": [5550, 8475]}, {"es": "- me respondieron.", "zh": "他们回答我。", "t": [8475, 9438]}]}, {"id": "ch01p04", "audio": true, "sents": [{"es": "Mi dibujo no representaba un sombrero.", "zh": "我的画并不是一顶帽子。", "t": [100, 3188]}, {"es": "Representaba una serpiente boa que digiere un elefante.", "zh": "蟒蛇正在消化一头大象。", "t": [3188, 7125]}, {"es": "Dibujé entonces el interior de la serpiente boa a fin de que las personas mayores pudieran comprender.", "zh": "于是，我画出了蟒蛇的内部，以便大人们能够理解。", "t": [7125, 13112]}, {"es": "Siempre estas personas tienen necesidad de explicaciones.", "zh": "这些人总是需要解释。", "t": [13112, 17250]}, {"es": "Mi dibujo número 2 era así:", "zh": "我的第二号画是这样的：", "t": [17250, 19038]}]}, {"id": "ch01p05", "audio": true, "sents": [{"es": "Las personas mayores me aconsejaron abandonar el dibujo de serpientes boas, ya fueran abiertas o cerradas, y poner más interés en la geografía, la historia, el cálculo y la gramática.", "zh": "大人们劝我别再画那些张开或闭合的蟒蛇，而应更多关注地理、历史、算术和语法。", "t": [100, 11325]}, {"es": "De esta manera a la edad de seis años abandoné una magnífica carrera de pintor.", "zh": "就这样，六岁时我放弃了成为画家的辉煌生涯。", "t": [11325, 16412]}, {"es": "Había quedado desilusionado por el fracaso de mis dibujos número 1 y número 2.", "zh": "我的第一号和第二号画作均以失败告终，让我深感失望。", "t": [16412, 20350]}, {"es": "Las personas mayores nunca pueden comprender algo por sí solas y es muy aburrido para los niños tener que darles una y otra vez explicaciones.", "zh": "大人们永远无法独自理解，而孩子们一遍又一遍地解释实在令人厌倦。", "t": [20350, 29126]}]}, {"id": "ch01p06", "audio": true, "sents": [{"es": "Tuve, pues, que elegir otro oficio y aprendía pilotear aviones.", "zh": "于是，我不得不选择另一门职业，并开始学习驾驶飞机。", "t": [100, 4538]}, {"es": "He volado un poco por todo el mundo y la geografía, en efecto, me ha servido de mucho; al primer vistazo podía distinguir perfectamente la China de Arizona.", "zh": "我驾驶飞机游历了世界各地，地理学实际上帮了我大忙；一眼就能分辨出中国和亚利桑那。", "t": [4538, 13800]}, {"es": "Esto es muy útil, sobre todo si se pierde uno durante la noche.A lo largo de mi vida he tenido multitud de contactos con multitud de gente seria.", "zh": "这非常实用，尤其是在夜间迷路时。在我的生涯中，我与众多严肃的人有过广泛的接触。", "t": [13800, 22300]}, {"es": "Viví mucho con personas mayores y las he conocido muy de cerca; pero esto no ha mejorado demasiado mi opinión sobre ellas.", "zh": "与许多大人近距离相处，但我对他们的看法并未有多大改观。", "t": [22300, 28713]}]}, {"id": "ch01p07", "audio": true, "sents": [{"es": "Cuando me he encontrado con alguien que me parecía un poco lúcido, lo he sometido a la experiencia de mi dibujo número 1 que he conservado siempre.", "zh": "当我遇到一个我觉得稍微有点明白的人时，我便让他经历我始终保留着的第一号画的考验。", "t": [100, 8275]}, {"es": "Quería saber si verdaderamente era un ser comprensivo.", "zh": "他想知道这人是否真的善解人意。", "t": [8275, 12038]}, {"es": "E invariablemente me contestaban siempre: \"Es un sombrero\".", "zh": "他们总是回答我说：“这是一顶帽子。”", "t": [12038, 16175]}, {"es": "Me abstenía de hablarles de la serpiente boa, de la selva virgen y de las estrellas.", "zh": "我避免向他们提及蟒蛇、原始森林和星星。", "t": [16175, 21438]}, {"es": "Poniéndome a su altura, les hablaba del bridge, del golf, de política y de corbatas.", "zh": "蹲下身来，我同他们谈论桥牌、高尔夫、政治和领带。", "t": [21438, 25837]}]}, {"id": "ch01p08", "audio": true, "sents": [{"es": "Y mi interlocutor se quedaba muy contento de conocer a un hombre tan razonable.", "zh": "他很高兴认识了一个如此通情达理的人。", "t": [100, 4038]}]}]}, {"id": "ch02", "title_es": "Capítulo 2", "title_zh": "第 2 章", "paras": [{"id": "ch02p00", "audio": true, "sents": [{"es": "Viví así, solo, nadie con quien poder hablar verdaderamente, hasta cuando hace seis años tuve una avería en el desierto de Sahara.", "zh": "就这样，我独自一人生活，直到六年前在撒哈拉沙漠遭遇故障。", "t": [100, 7888]}, {"es": "Algo se había estropeado en el motor.", "zh": "发动机出了故障。", "t": [7888, 10788]}, {"es": "Como no llevaba conmigo ni mecánico ni pasajero alguno, me dispuse a realizar, yo solo, una reparación difícil.", "zh": "于是，我孤身一人，决心独自完成这场艰难的修理。", "t": [10788, 18062]}, {"es": "Era para mí una cuestión de vida o muerte, pues apenas tenía agua de beber para ocho días.", "zh": "这是关乎生死的问题，我仅剩八天的饮用水。", "t": [18062, 22687]}]}, {"id": "ch02p01", "audio": true, "sents": [{"es": "La primera noche me dormí sobre la arena, a unas mil millas de distancia del lugar habitado más próximo.", "zh": "那第一夜，我睡在沙地上，远离最近有人居住的地方已有千里之遥。", "t": [100, 6625]}, {"es": "Estaba más aislado que un náufrago en una balsa en medio del océano.", "zh": "比漂泊在汪洋中的孤舟失事者更孤独。", "t": [6625, 11075]}, {"es": "Imagínense, pues, mi sorpresa cuando al amanecer me despertó una extraña vocecita que decía: - ¡Por favor…", "zh": "想象吧，清晨时分，我被一个奇怪的小声音唤醒，它轻声说：“请……”", "t": [11075, 16725]}, {"es": "píntame un cordero!", "zh": "画一只绵羊吧！", "t": [16725, 18662]}, {"es": "-¿Eh?", "zh": "哎？", "t": [18662, 19838]}, {"es": "-¡Píntame un cordero!", "zh": "画一只羊吧！", "t": [19838, 20874]}]}, {"id": "ch02p02", "audio": true, "sents": [{"es": "Me puse en pie de un salto como herido por el rayo.", "zh": "我猛地跳起，仿佛被雷电击中。", "t": [100, 2762]}]}, {"id": "ch02p03", "audio": true, "sents": [{"es": "Me froté los ojos.", "zh": "揉了揉眼睛。", "t": [100, 2262]}, {"es": "Miré a mi alrededor.", "zh": "环顾四周。", "t": [2262, 4462]}, {"es": "Vi a un extraordinario muchachito que me miraba gravemente.", "zh": "我瞧见一个奇特的小家伙，正严肃地望着我。", "t": [4462, 7587]}]}, {"id": "ch02p04", "audio": true, "sents": [{"es": "Ahí tienen el mejor retrato que más tarde logré hacer de él, aunque mi dibujo, ciertamente es menos encantador que el modelo.", "zh": "这里便是后来我成功为他画出的肖像，尽管我的画显然不如模特儿本人那般迷人。", "t": [100, 7388]}, {"es": "Pero no es mía la culpa.", "zh": "但这并非我的过错。", "t": [7388, 8637]}]}, {"id": "ch02p05", "audio": true, "sents": [{"es": "Las personas mayores me desanimaron de mi carrera de pintor a la edad de seis años y no había aprendido a dibujar otra cosa que boas cerradas y boas abiertas.", "zh": "大人让我在六岁时放弃了画家生涯，此后我只学会了画闭嘴的蛇和开口的蛇。", "t": [100, 8062]}]}, {"id": "ch02p06", "audio": true, "sents": [{"es": "Miré, pues, aquella aparición con los ojos redondos de admiración.", "zh": "我凝视着，眼中满是钦佩之色。", "t": [100, 4550]}, {"es": "No hay que olvidar que me encontraba a unas mil millas de distancia del lugar habitado más próximo.", "zh": "别忘了，我离最近有人居住的地方已有千里之遥。", "t": [4550, 10225]}, {"es": "Y ahora bien, el muchachito no me parecía ni perdido, ni muerto de cansancio, de hambre, de sed o de miedo.", "zh": "那孩子既不像是迷路的，也不像是因疲惫、饥饿、口渴或恐惧而死去。", "t": [10225, 17038]}, {"es": "No tenía en absoluto la apariencia de un niño perdido en el desierto, a mil millas de distancia del lugar habitado más próximo.", "zh": "他看上去绝非是在沙漠中迷失的孩子，离最近有人居住的地方已有千里之遥。", "t": [17038, 24612]}, {"es": "Cuando logré, por fin, articular palabra, le dije:", "zh": "当我终于能够开口说话时，我对他说：", "t": [24612, 27687]}]}, {"id": "ch02p07", "audio": true, "sents": [{"es": "-Pero…", "zh": "然而…", "t": [100, 425]}, {"es": "¿qué haces tú por aquí?", "zh": "你在此处做什么？", "t": [425, 1575]}]}, {"id": "ch02p08", "audio": true, "sents": [{"es": "Y él respondió entonces, suavemente, como algo muy importante: -¡Por favor…", "zh": "他随后温和地回答，仿佛在说一件非常重要的事：“请……”", "t": [100, 4138]}, {"es": "píntame un cordero!", "zh": "画一只羊吧！", "t": [4138, 5138]}]}, {"id": "ch02p09", "audio": true, "sents": [{"es": "Cuando el misterio es demasiado impresionante, es imposible desobedecer.", "zh": "神秘太过震撼，难以违抗。", "t": [100, 4800]}, {"es": "Por absurdo que aquello me pareciera, a mil millas de distancia de todo lugar habitado y en peligro de muerte, saqué de mi bolsillo una hoja de papel y una pluma fuente.", "zh": "尽管这在我看来荒谬至极，身处千里荒漠，命悬一线，我还是从口袋里掏出一张纸和一支钢笔。", "t": [4800, 14125]}, {"es": "Recordé que yo había estudiado especialmente geografía, historia, cálculo y gramática y le dije al muchachito (ya un poco malhumorado), que no sabía dibujar.", "zh": "我记起自己曾专门学习过地理、历史、算术和语法，便对那小家伙（已有些不高兴）说，我不会画画。", "t": [14125, 22750]}]}, {"id": "ch02p10", "audio": true, "sents": [{"es": "-No importa - me respondió-, píntame un cordero!", "zh": "他答道：“画一只羊吧！”", "t": [100, 2675]}]}, {"id": "ch02p11", "audio": true, "sents": [{"es": "Como nunca había dibujado un cordero, rehíce para él uno de los dos únicos dibujos que yo era capaz de realizar: el de la serpiente boa cerrada.", "zh": "我犹豫着，为他画出了我唯一能画的其中一幅：那闭嘴的蟒蛇。", "t": [100, 8650]}, {"es": "Y quedé estupefacto cuando oí decir al hombrecito: - ¡No, no!", "zh": "我惊愕地听到小家伙说：“不，不！”", "t": [8650, 12762]}, {"es": "Yo no quiero un elefante en una serpiente.", "zh": "我不想在蛇里画一头大象。", "t": [12762, 15888]}, {"es": "La serpiente es muy peligrosa y el elefante ocupa mucho sitio.", "zh": "蛇太危险，象又占地方。", "t": [15888, 20138]}, {"es": "En mi tierra es todo muy pequeño.", "zh": "在我的星球上，一切都很小。", "t": [20138, 22838]}, {"es": "Necesito un cordero.", "zh": "我需要一只羊。", "t": [22838, 25038]}, {"es": "Píntame un cordero.", "zh": "画一只羊吧。", "t": [25038, 26075]}]}, {"id": "ch02p12", "audio": true, "sents": [{"es": "Dibujé un cordero.", "zh": "我画了一只羊。", "t": [100, 1138]}]}, {"id": "ch02p13", "audio": true, "sents": [{"es": "Lo miró atentamente y dijo: ¡No!", "zh": "不！", "t": [100, 2862]}, {"es": "Este está ya muy enfermo.", "zh": "这羊病得已经很重了。", "t": [2862, 5312]}, {"es": "Haz otro.", "zh": "再画一个。", "t": [5312, 5888]}]}, {"id": "ch02p14", "audio": true, "sents": [{"es": "Volví a dibujar.", "zh": "我又画了一张。", "t": [100, 1038]}]}, {"id": "ch02p15", "audio": true, "sents": [{"es": "Mi amigo sonrió dulcemente, con indulgencia.", "zh": "我的朋友微笑着，带着宽容。", "t": [100, 3538]}, {"es": "-¿Ves?", "zh": "您看。", "t": [3538, 4875]}, {"es": "Esto no es un cordero, es un carnero.", "zh": "这不是羊，是公羊。", "t": [4875, 8038]}, {"es": "Tiene Cuernos…", "zh": "它长着角……", "t": [8038, 8876]}]}, {"id": "ch02p16", "audio": true, "sents": [{"es": "Rehice nuevamente mi dibujo: fue rechazado igual que los anteriores.", "zh": "我又画了一张，依旧被拒绝了。", "t": [100, 3963]}]}, {"id": "ch02p17", "audio": true, "sents": [{"es": "-Este es demasiado viejo.", "zh": "这羊太老了。", "t": [100, 2550]}, {"es": "Quiero un cordero que viva mucho tiempo.", "zh": "我要一只能活很久的绵羊。", "t": [2550, 4550]}]}, {"id": "ch02p18", "audio": true, "sents": [{"es": "Falto ya de paciencia y deseoso de comenzar a desmontar el motor, garrapateé rápidamente este dibujo, se lo enseñé, y le agregué:", "zh": "我已失去耐心，急于开始拆卸发动机，便草草地画了这张画，递给他，接着说：", "t": [100, 7487]}]}, {"id": "ch02p19", "audio": true, "sents": [{"es": "-Esta es la caja.", "zh": "这是一只箱子。", "t": [100, 2100]}, {"es": "El cordero que quieres está adentro.", "zh": "那你要的绵羊在里面。", "t": [2100, 4938]}, {"es": "Con gran sorpresa mía el rostro de mi joven juez se iluminó: -¡Así es como yo lo quería!", "zh": "我的年轻法官的面容因惊喜而发光：这正是我想要的！", "t": [4938, 10562]}, {"es": "¿Crees que sea necesario mucha hierba para este cordero?", "zh": "这绵羊需要很多草吗？", "t": [10562, 14425]}, {"es": "-¿Por qué?", "zh": "为什么？", "t": [14425, 14812]}]}, {"id": "ch02p20", "audio": true, "sents": [{"es": "-Porque en mi tierra es todo tan pequeño…", "zh": "因为在我的星球上，一切都很小。", "t": [100, 2088]}]}, {"id": "ch02p21", "audio": true, "sents": [{"es": "Se inclinó hacia el dibujo y exclamó: -¡Bueno, no tan pequeño…!", "zh": "他俯身看画，惊呼：“嗯，不过也不算太小……”", "t": [100, 4450]}, {"es": "Está dormido…", "zh": "它睡着了…", "t": [4450, 5250]}]}, {"id": "ch02p22", "audio": true, "sents": [{"es": "Y así fue como conocí al principito.", "zh": "就这样，我遇见了小王子。", "t": [100, 2075]}]}]}, {"id": "ch03", "title_es": "Capítulo 3", "title_zh": "第 3 章", "paras": [{"id": "ch03p00", "audio": true, "sents": [{"es": "Me costó mucho tiempo comprender de dónde venía.", "zh": "费了我好长时间才弄懂他来自何方。", "t": [100, 3575]}, {"es": "El principito, que me hacía muchas preguntas, jamás parecía oír las mías.", "zh": "小王子向我问了许多问题，却似乎从未真正聆听我的回答。", "t": [3575, 8712]}, {"es": "Fueron palabras pronunciadas al azar, las que poco a poco me revelaron todo.", "zh": "偶然间吐露的只言片语，渐渐向我揭示了全部真相。", "t": [8712, 13675]}, {"es": "Así, cuando distinguió por vez primera mi avión (no dibujaré mi avión, por tratarse de un dibujo demasiado complicado para mí) me preguntó: -¿Qué cosa es esa?", "zh": "于是，他首次辨认出我的飞机（我不愿画我的飞机，那是我觉得太复杂的画）便问：“这是什么玩意儿？”", "t": [13675, 23188]}, {"es": "-Eso no es una cosa.", "zh": "这不是东西。", "t": [23188, 25412]}, {"es": "Eso vuela.", "zh": "这会飞。", "t": [25412, 27038]}, {"es": "Es un avión, mi avión.", "zh": "这是飞机，我的飞机。", "t": [27038, 28488]}]}, {"id": "ch03p01", "audio": true, "sents": [{"es": "Me sentía orgulloso al decirle que volaba.", "zh": "我自豪地告诉他我会飞。", "t": [100, 3338]}, {"es": "El entonces gritó: -¡Cómo!", "zh": "他惊呼道：“怎么！”", "t": [3338, 5775]}, {"es": "¿Has caído del cielo?", "zh": "你是从天上掉下来的吗？", "t": [5775, 7912]}, {"es": "-Sí -le dije modestamente.", "zh": "我谦逊地回答道。", "t": [7912, 10462]}, {"es": "-¡Ah, que curioso!", "zh": "啊，真奇怪！", "t": [10462, 11450]}]}, {"id": "ch03p02", "audio": true, "sents": [{"es": "Y el principito lanzó una graciosa carcajada que me irritó mucho.", "zh": "小王子发出一阵欢快的笑声，那笑声却让我颇为不快。", "t": [100, 4400]}, {"es": "Me gusta que mis desgracias se tomen en serio.", "zh": "我的不幸能得到认真对待。", "t": [4400, 7762]}, {"es": "Y añadió:", "zh": "他又补充道：", "t": [7762, 8337]}]}, {"id": "ch03p03", "audio": true, "sents": [{"es": "-Entonces ¿tú también vienes del cielo?", "zh": "那么，你也是从天上来的吗？", "t": [100, 3288]}, {"es": "¿De qué planeta eres tú?", "zh": "你是从哪个星球来的？", "t": [3288, 4537]}]}, {"id": "ch03p04", "audio": true, "sents": [{"es": "Divisé una luz en el misterio de su presencia y le pregunté bruscamente: -¿Tu vienes, pues, de otro planeta?", "zh": "他的出现如同闪电，瞬间揭开他神秘身份，我猛然问道：“那么，你莫非来自另一个星球？”", "t": [100, 5613]}]}, {"id": "ch03p05", "audio": true, "sents": [{"es": "Pero no me respondió; movía lentamente la cabeza mirando detenidamente mi avión.", "zh": "但他没有回答；他缓缓地摇着头，专注地打量着我的飞机。", "t": [100, 4463]}]}, {"id": "ch03p06", "audio": true, "sents": [{"es": "-Es cierto, que, encima de eso, no puedes venir de muy lejos…", "zh": "那还用说，你不可能来自太远的地方。", "t": [100, 3462]}]}, {"id": "ch03p07", "audio": true, "sents": [{"es": "Y se hundió en un ensueño durante largo tiempo.", "zh": "他沉醉于梦境之中，久久不愿醒来。", "t": [100, 3575]}, {"es": "Luego sacando de su bolsillo mi cordero se abismó en la contemplación de su tesoro.", "zh": "从口袋里掏出我画的绵羊，他陷入了对心爱宝物的沉思。", "t": [3575, 7787]}]}, {"id": "ch03p08", "audio": true, "sents": [{"es": "Imagínense cómo me intrigó esta semiconfidencia sobre los otros planetas.", "zh": "想象我有多么好奇，他对那些其他星球只字未提。", "t": [100, 4950]}, {"es": "Me esforcé, pues, en saber algo más: -¿De dónde vienes, muchachito?", "zh": "我尽力想了解更多：“小家伙，你从哪里来？”", "t": [4950, 9525]}, {"es": "¿Dónde está \"tu casa\"?", "zh": "你的家在何方？", "t": [9525, 11712]}, {"es": "¿Dónde quieres llevarte mi cordero?", "zh": "你打算把我的绵羊带到哪里去？", "t": [11712, 13425]}]}, {"id": "ch03p09", "audio": true, "sents": [{"es": "Después de meditar silenciosamente me respondió:", "zh": "静默片刻后，他回答道：", "t": [100, 2700]}]}, {"id": "ch03p10", "audio": true, "sents": [{"es": "-Lo bueno de la caja que me has dado es que por la noche le servirá de casa.", "zh": "你给我的箱子好，夜里绵羊就有了家。", "t": [100, 4538]}, {"es": "-Sin duda.", "zh": "毫无疑问。", "t": [4538, 6150]}, {"es": "Y si eres bueno te daré también una cuerda y una estaca para atarlo durante el día.", "zh": "若你乖巧，我还将赠你一根绳索与桩柱，白日里为你系牢它。", "t": [6150, 10287]}]}, {"id": "ch03p11", "audio": true, "sents": [{"es": "Esta proposición pareció chocar al principito.", "zh": "这提议似乎让小王子感到不悦。", "t": [100, 3488]}, {"es": "-¿Atarlo?", "zh": "把他拴住？", "t": [3488, 4975]}, {"es": "¡Qué idea más rara!", "zh": "多么奇怪的念头！", "t": [4975, 7025]}, {"es": "-Si no lo atas, se irá quién sabe dónde y se perderá…", "zh": "若不将他拴住，他便会不知去向，或许会迷失。", "t": [7025, 9676]}]}, {"id": "ch03p12", "audio": true, "sents": [{"es": "Mi amigo soltó una nueva carcajada.", "zh": "我的朋友又大笑起来。", "t": [100, 3112]}, {"es": "-¿Y dónde quieres que vaya?", "zh": "你想让它去哪里？", "t": [3112, 5388]}, {"es": "-No sé, a cualquier parte.", "zh": "不知，随便哪里。", "t": [5388, 7775]}, {"es": "Derecho camino adelante…", "zh": "径直向前…", "t": [7775, 9175]}]}, {"id": "ch03p13", "audio": true, "sents": [{"es": "Entonces el principito señaló con gravedad: -¡No importa, es tan pequeña mi tierra!", "zh": "那么，小王子严肃地说：“我的星球再小，也足够了。”", "t": [100, 4474]}]}, {"id": "ch03p14", "audio": true, "sents": [{"es": "Y agregó, quizás, con un poco de melancolía:", "zh": "他或许带着一丝忧郁地补充道：", "t": [100, 2462]}]}, {"id": "ch03p15", "audio": true, "sents": [{"es": "-Derecho, camino adelante…", "zh": "直路，向前行…", "t": [100, 1612]}, {"es": "no se puede ir muy lejos.", "zh": "再往前走，也走不远。", "t": [1612, 3050]}]}]}, {"id": "ch04", "title_es": "Capítulo 4", "title_zh": "第 4 章", "paras": [{"id": "ch04p00", "audio": true, "sents": [{"es": "De esta manera supe una segunda cosa muy importante: su planeta de origen era apenas más grande que una casa.", "zh": "他这才明白第二件重要的事：他来自的星球，不过比一座房子大些而已。", "t": [100, 5976]}]}, {"id": "ch04p01", "audio": true, "sents": [{"es": "Esto no podía asombrarme mucho.", "zh": "这并不让我感到特别惊讶。", "t": [100, 2988]}, {"es": "Sabía muy bien que aparte de los grandes planetas como la Tierra, Júpiter, Marte, Venus, a los cuales se les ha dado nombre, existen otros centenares de ellos tan pequeños a veces, que es difícil distinguirlos aun con la ayuda del telescopio.", "zh": "除了那些被命名的巨大行星，如地球、木星、火星、金星，还有成千上万的星球，它们如此之小，即便借助望远镜也难以辨认。", "t": [2988, 16462]}, {"es": "Cuando un astrónomo descubre uno de estos planetas, le da por nombre un número.", "zh": "天文学家发现这类星球时，便以数字为其命名。", "t": [16462, 21600]}, {"es": "Le llama, por ejemplo, \"el asteroide 3251\".", "zh": "它被称作“小行星3251号”。", "t": [21600, 25200]}]}, {"id": "ch04p02", "audio": true, "sents": [{"es": "Tengo poderosas razones para creer que el planeta del cual venía el principito era el asteroide B 612.", "zh": "我有充分的理由相信，小王子来自的星球是B612号小行星。", "t": [100, 4800]}, {"es": "Este asteroide ha sido visto sólo una vez con el telescopio en 1909, por un astrónomo turco.", "zh": "这颗小行星仅在一九〇九年被一位土耳其天文学家用望远镜观测到一次。", "t": [4800, 12324]}]}, {"id": "ch04p03", "audio": true, "sents": [{"es": "Este astrónomo hizo una gran demostración de su descubrimiento en un congreso Internacional de Astronomía.", "zh": "这位天文学家在国际天文会议上对发现做了精彩的展示。", "t": [100, 6450]}, {"es": "Pero nadie le creyó a causa de su manera de vestir.", "zh": "但他的着装方式让人难以置信。", "t": [6450, 9000]}]}, {"id": "ch04p04", "audio": true, "sents": [{"es": "Las personas mayores son así.", "zh": "大人们就是这样。", "t": [100, 2875]}, {"es": "Felizmente para la reputación del asteroide B 612, un dictador turco impuso a su pueblo, bajo pena de muerte, el vestido a la europea.", "zh": "幸而为了B612小行星的声誉，土耳其独裁者强制其国民改穿欧洲式服装，违者处以死刑。", "t": [2875, 10875]}]}, {"id": "ch04p05", "audio": true, "sents": [{"es": "Entonces el astrónomo volvió a dar cuenta de su descubrimiento en 1920 y como lucía un traje muy elegante, todo el mundo aceptó su demostración.", "zh": "于是，那位天文学家在1920年再次报告了他的发现，他身着一套非常考究的西装，所有人都接受了他的展示。", "t": [100, 8163]}]}, {"id": "ch04p06", "audio": true, "sents": [{"es": "Si les he contado de todos estos detalles sobre el asteroide B 612 y hasta les he confiado su número, es por consideración a las personas mayores.", "zh": "若非考虑到这些大人们的情面，我本不必详述B612小行星的种种细节，甚至无需透露它的编号。", "t": [100, 9312]}, {"es": "A los mayores les gustan las cifras.", "zh": "大人们偏爱数字。", "t": [9312, 12262]}, {"es": "Cuando se les habla de un nuevo amigo, jamás preguntan sobre lo esencial del mismo.", "zh": "谈到新朋友，他们从不询问其本质。", "t": [12262, 17575]}, {"es": "Nunca se les ocurre preguntar: \"¿Qué tono tiene su voz?", "zh": "他们从不会问：“他的嗓音如何？", "t": [17575, 21512]}, {"es": "¿Qué juegos prefiere?", "zh": "他喜欢玩什么游戏？", "t": [21512, 23600]}, {"es": "¿Le gusta coleccionar mariposas?\" Pero en cambio preguntan: \"¿Qué edad tiene?", "zh": "他喜欢收集蝴蝶吗？但他们却问：“他多大年纪？”", "t": [23600, 29488]}, {"es": "¿Cuántos hermanos?", "zh": "他有多少个兄弟？", "t": [29488, 31450]}, {"es": "¿Cuánto pesa?", "zh": "他多重？", "t": [31450, 33162]}, {"es": "¿Cuánto gana su padre?\" Solamente con estos detalles creen conocerle.", "zh": "他们想知道：“他父亲挣多少钱？” 只凭这些细节，他们便自以为已了解一个人。", "t": [33162, 38738]}, {"es": "Si les decimos a las personas mayores: \"He visto una casa preciosa de ladrillo rosa, con geranios en las ventanas y palomas en el tejado\", jamás llegarán a imaginarse cómo es esa casa.", "zh": "若对大人说：“我看见一幢粉红砖砌的漂亮房子，窗台上摆满了天竺葵，屋顶栖息着鸽子……”他们便无法想象这房子的模样。", "t": [38738, 48876]}]}, {"id": "ch04p07", "audio": true, "sents": [{"es": "Es preciso decirles: \"He visto una casa que vale cien mil pesos\".", "zh": "我必须告诉你们：“我看见了一座价值十万法郎的房子。”", "t": [100, 4762]}, {"es": "Entonces exclaman entusiasmados: \"¡Oh, qué preciosa es!\"", "zh": "哦，多么美丽啊！", "t": [4762, 8037]}]}, {"id": "ch04p08", "audio": true, "sents": [{"es": "De tal manera, si les decimos: \"La prueba de que el principito ha existido está en que era un muchachito encantador, que reía y quería un cordero.", "zh": "如此一来，若我们告诉他们：“小王子曾存在过的证据，在于他曾是位迷人孩童，笑容满面，渴望拥有一只羊。”", "t": [100, 8462]}, {"es": "Querer un cordero es prueba de que se existe\", las personas mayores se encogerán de hombros y nos dirán que somos unos niños.", "zh": "渴望一只羊，便是存在的证明，大人们会耸耸肩，说我们只是不懂事的孩子。", "t": [8462, 15825]}, {"es": "Pero si les decimos: \"el planeta de donde venía el principito era el asteroide B 612\", quedarán convencidas y no se preocuparán de hacer más preguntas.", "zh": "若我们告诉他们：“小王子来自的星球是B612号小行星”，她们便会信服，不会再有更多的疑问。", "t": [15825, 25312]}, {"es": "Son así.", "zh": "如此而已。", "t": [25312, 25900]}]}, {"id": "ch04p09", "audio": true, "sents": [{"es": "No hay por qué guardarles rencor.", "zh": "无需怀恨在心。", "t": [100, 2825]}, {"es": "Los niños deben ser muy indulgentes con las personas mayores.", "zh": "孩子们应当对大人宽容。", "t": [2825, 6137]}]}, {"id": "ch04p10", "audio": true, "sents": [{"es": "Pero nosotros, que sabemos comprender la vida, nos burlamos tranquilamente de los números.", "zh": "然而，我们这些懂得理解生活的人，却对数字之以鼻。", "t": [100, 5850]}, {"es": "A mí me habría gustado más comenzar esta historia a la manera de los cuentos de hadas.", "zh": "我更愿意以童话的方式开启这个故事。", "t": [5850, 10988]}, {"es": "Me habría gustado decir:", "zh": "我本想说的是：", "t": [10988, 12375]}]}, {"id": "ch04p11", "audio": true, "sents": [{"es": "\"Era una vez un principito que habitaba un planeta apenas más grande que él y que tenía necesidad de un amigo…\" Para aquellos que comprenden la vida, esto hubiera parecido más real.", "zh": "从前有个小王子，他住在一颗比他自己大不了多少的星球上，他需要一个朋友……对于理解生活的人来说，这样讲述似乎更真实。", "t": [100, 10087]}]}, {"id": "ch04p12", "audio": true, "sents": [{"es": "Porque no me gusta que mi libro sea tomado a la ligera.", "zh": "因为我不喜欢我的书被轻率对待。", "t": [100, 3712]}, {"es": "Siento tanta pena al contar estos recuerdos.", "zh": "讲述这些往事，我感到十分惋惜。", "t": [3712, 6163]}]}, {"id": "ch04p13", "audio": true, "sents": [{"es": "Hace ya seis años que mi amigo se fue con su cordero.", "zh": "六年前，我的朋友带着他的羊离开了。", "t": [100, 3750]}, {"es": "Y si intento describirlo aquí es sólo con el fin de no olvidarlo.", "zh": "若我在此尽力描绘，也只是为了不忘却他。", "t": [3750, 8162]}, {"es": "Es muy triste olvidar a un amigo.", "zh": "遗忘朋友实在令人悲伤。", "t": [8162, 10900]}, {"es": "No todos han tenido un amigo.", "zh": "并非人人都有过朋友。", "t": [10900, 13525]}, {"es": "Y yo puedo llegar a ser como las personas mayores, que sólo se interesan por las cifras.", "zh": "我或许会变成像大人们一样，只对数字感兴趣。", "t": [13525, 19125]}, {"es": "Para evitar esto he comprado una caja de lápices de colores.", "zh": "为了防止这种情况，我买了一盒彩色铅笔。", "t": [19125, 23088]}, {"es": "¡Es muy duro, a mi edad, ponerse a aprender a dibujar, cuando en toda la vida no se ha hecho otra tentativa que la de una boa abierta y una boa cerrada a la edad de seis años!", "zh": "在我这个年纪，重新学习画画，而一生中唯一的尝试不过是六岁时画过的张开肚子的蟒蛇和闭合肚子的蟒蛇，实在太过艰难！", "t": [23088, 32775]}, {"es": "Ciertamente que yo trataré de hacer retratos lo más parecido posibles, pero no estoy muy seguro de lograrlo.", "zh": "我定会尽力绘出尽可能逼真的肖像，但能否成功，我心中并无把握。", "t": [32775, 39525]}, {"es": "Uno saldrá bien y otro no tiene parecido alguno.", "zh": "一幅画得可以，另一幅却毫无相似之处。", "t": [39525, 43025]}, {"es": "En las proporciones me equivoco también un poco.", "zh": "我在比例上也有些误差。", "t": [43025, 46412]}, {"es": "Aquí el principito es demasiado grande y allá es demasiado pequeño.", "zh": "这里小王子太大，那里太小。", "t": [46412, 50888]}, {"es": "Dudo también sobre el color de su traje.", "zh": "我也怀疑他衣服的颜色。", "t": [50888, 53925]}, {"es": "Titubeo sobre esto y lo otro y unas veces sale bien y otras mal.", "zh": "时而画得不错，时而又画得糟糕。", "t": [53925, 58250]}, {"es": "Es posible, en fin, que me equivoque sobre ciertos detalles muy importantes.", "zh": "也许，归根结底，我在某些至关重要的细节上可能犯了错。", "t": [58250, 63350]}, {"es": "Pero habrá que perdonármelo ya que mi amigo no me daba nunca muchas explicaciones.", "zh": "但我得原谅他，因为我的朋友从不给我太多解释。", "t": [63350, 68350]}, {"es": "Me creía semejante a sí mismo y yo, desgraciadamente, no sé ver un cordero a través de una caja.", "zh": "我原以为我和他相似，不幸的是，我看不见箱子里的绵羊。", "t": [68350, 74512]}, {"es": "Es posible que yo sea un poco como las personas mayores.", "zh": "或许我也有点像大人们了。", "t": [74512, 78512]}, {"es": "He debido envejecer.", "zh": "他已日渐老去。", "t": [78512, 79550]}]}]}, {"id": "ch05", "title_es": "Capítulo 5", "title_zh": "第 5 章", "paras": [{"id": "ch05p00", "audio": true, "sents": [{"es": "Cada día yo aprendía algo nuevo sobre el planeta, sobre la partida y sobre el viaje.", "zh": "每日，我在这颗星球、启程与旅途中获得新知。", "t": [100, 5388]}, {"es": "Esto venía suavemente al azar de las reflexiones.", "zh": "这便是在闲聊中不经意间获得的领悟。", "t": [5388, 9150]}, {"es": "De esta manera tuve conocimiento al tercer día, del drama de los baobabs.", "zh": "第三天，我方才得知猴面包树的悲剧。", "t": [9150, 13112]}]}, {"id": "ch05p01", "audio": true, "sents": [{"es": "Fue también gracias al cordero y como preocupado por una profunda duda, cuando el principito me preguntó: -¿Es verdad que los corderos se comen los arbustos?", "zh": "也是多亏了那只绵羊，小王子因心中充满疑惑，便问我：“羊儿真的会吃灌木吗？”", "t": [100, 8288]}]}, {"id": "ch05p02", "audio": true, "sents": [{"es": "-Sí, es cierto.", "zh": "是的，是真的。", "t": [100, 2150]}, {"es": "-¡Ah, qué contesto estoy!", "zh": "啊，回答得真妙！", "t": [2150, 3426]}]}, {"id": "ch05p03", "audio": true, "sents": [{"es": "No comprendí por qué era tan importante para él que los corderos se comieran los arbustos.", "zh": "他不懂为何羊儿吃灌木对他来说如此重要。", "t": [100, 5438]}, {"es": "Pero el principito añadió:", "zh": "小王子接着说：", "t": [5438, 6738]}]}, {"id": "ch05p04", "audio": true, "sents": [{"es": "-Entonces se comen también los Baobabs.", "zh": "那么，它们也会吃猴面包树。", "t": [100, 2137]}]}, {"id": "ch05p05", "audio": true, "sents": [{"es": "Le hice comprender al principito que los baobabs no son arbustos, sino árboles tan grandes como iglesias y que incluso si llevase consigo todo un rebaño de elefantes, el rebaño no lograría acabar con un solo baobab.", "zh": "小王子这才明白，猴面包树并非灌木，而是如同教堂一般高大，即便他带着整群大象，也无法将一棵猴面包树连根拔起。", "t": [100, 11450]}]}, {"id": "ch05p06", "audio": true, "sents": [{"es": "Esta idea del rebaño de elefantes hizo reír al principito.", "zh": "这头群象的念头逗得小王子笑了。", "t": [100, 3250]}]}, {"id": "ch05p07", "audio": true, "sents": [{"es": "-Habría que poner los elefantes unos sobre otros…", "zh": "大象得一个叠一个地站上去……", "t": [100, 2688]}]}, {"id": "ch05p08", "audio": true, "sents": [{"es": "Y luego añadió juiciosamente:", "zh": "然后他机智地补充道：", "t": [100, 1825]}]}, {"id": "ch05p09", "audio": true, "sents": [{"es": "-Los baobabs, antes de crecer, son muy pequeñitos.", "zh": "猴面包树，在长成之前，都是极小的。", "t": [100, 2913]}]}, {"id": "ch05p10", "audio": true, "sents": [{"es": "-Es cierto.", "zh": "是的。", "t": [100, 1738]}, {"es": "Pero ¿por qué quieres que tus corderos coman los baobabs?", "zh": "可你为何要让你的绵羊吃猴面包树呢？", "t": [1738, 4475]}]}, {"id": "ch05p11", "audio": true, "sents": [{"es": "Me contestó: \"¡Bueno!", "zh": "他答道：“好吧！”", "t": [100, 2262]}, {"es": "¡Vamos!\" como si hablara de una evidencia.", "zh": "咱们走吧，就像在谈论一件显而易见的事。", "t": [2262, 5425]}, {"es": "Me fue necesario un gran esfuerzo de inteligencia para comprender por mí mismo este problema.", "zh": "我费尽心思才领悟了这个问题的真相。", "t": [5425, 10012]}]}, {"id": "ch05p12", "audio": true, "sents": [{"es": "En efecto, en el planeta del principito había, como en todos los planetas, hierbas buenas y hierbas malas.", "zh": "在这颗小王子的星球上，正如所有星球一样，既有良草也有毒草。", "t": [100, 6350]}, {"es": "Por consiguiente, de buenas semillas salían buenas hierbas y de las semillas malas, hierbas malas.", "zh": "于是，良种生良草，恶种生恶草。", "t": [6350, 11187]}]}, {"id": "ch05p13", "audio": true, "sents": [{"es": "Pero las semillas son invisibles; duermen en el secreto de la tierra, hasta que un buen día una de ellas tiene la fantasía de despertarse.", "zh": "但种子隐于土壤深处，沉睡，直至某日，一颗种子幻想醒来。", "t": [100, 8225]}, {"es": "Entonces se alarga extendiendo hacia el sol, primero tímidamente, una encantadora ramita inofensiva.", "zh": "它伸展着，首先胆怯地向着太阳，露出一枝迷人的嫩枝。", "t": [8225, 14775]}, {"es": "Si se trata de una ramita de rábano o de rosal, se la puede dejar que crezca como quiera.", "zh": "若是一株萝卜或玫瑰的嫩芽，便可任其自由生长。", "t": [14775, 19624]}]}, {"id": "ch05p14", "audio": true, "sents": [{"es": "Pero si se trata de una mala hierba, es preciso arrancarla inmediatamente en cuanto uno ha sabido reconocerla.", "zh": "若是一株毒草，一经辨认，便须立刻拔除。", "t": [100, 5888]}]}, {"id": "ch05p15", "audio": true, "sents": [{"es": "En el planeta del principito había semillas terribles…", "zh": "在这颗小王子的星球上，埋藏着可怕的种子……", "t": [100, 3025]}, {"es": "como las semillas del baobab.", "zh": "如同猴面包树的种子。", "t": [3025, 5225]}, {"es": "El suelo del planeta está infestado de ellas.", "zh": "这颗星球的土壤里满是它们。", "t": [5225, 8600]}, {"es": "Si un baobab no se arranca a tiempo, no hay manera de desembarazarse de él más tarde; cubre todo el planeta y lo perfora con sus raíces.", "zh": "若不及时拔除猴面包树，日后便无法根除；它将整个星球覆盖，根系将其穿透。", "t": [8600, 16900]}, {"es": "Y si el planeta es demasiado pequeño y los baobabs son numerosos, lo hacen estallar.", "zh": "若星球太小，而猴面包树又太多，便会将其撑爆。", "t": [16900, 21350]}]}, {"id": "ch05p16", "audio": true, "sents": [{"es": "\"Es una cuestión de disciplina, me decía más tarde el principito.", "zh": "这是纪律的问题，小王子后来对我说。", "t": [100, 4562]}, {"es": "Cuando por la mañana uno termina de arreglarse, hay que hacer cuidadosamente la limpieza del planeta.", "zh": "清晨梳洗毕，须细心打扫星球。", "t": [4562, 10575]}, {"es": "Hay que dedicarse regularmente a arrancar los baobabs, cuando se les distingue de los rosales, a los cuales se parecen mucho cuando son pequeñitos.", "zh": "须定期将猴面包树与玫瑰区分开来，及时拔除，因为它们在小的时候极为相似。", "t": [10575, 19138]}, {"es": "Es un trabajo muy fastidioso pero muy fácil\".", "zh": "这是一件很烦琐但很容易的事。", "t": [19138, 21562]}]}, {"id": "ch05p17", "audio": true, "sents": [{"es": "Y un día me aconsejó que me dedicara a realizar un hermoso dibujo, que hiciera comprender a los niños de la tierra estas ideas.", "zh": "他建议我画一幅美丽的画，让孩子们理解这些想法。", "t": [100, 7688]}, {"es": "\"Si alguna vez viajan, me decía, esto podrá servirles mucho.", "zh": "若你们有朝一日旅行，我会说，这或许能帮上大忙。", "t": [7688, 12275]}, {"es": "A veces no hay inconveniente en dejar para más tarde el trabajo que se ha de hacer; pero tratándose de baobabs, el retraso es siempre una catástrofe.", "zh": "有时推迟应做的工作并无大碍；但若是猴面包树，拖延便总是灾难。", "t": [12275, 20738]}, {"es": "Yo he conocido un planeta, habitado por un perezoso que descuidó tres arbustos…\"", "zh": "我遇见了一颗星球，上面住着一个懒惰的人，他疏忽了三棵灌木……", "t": [20738, 25175]}]}, {"id": "ch05p18", "audio": true, "sents": [{"es": "Siguiendo las indicaciones del principito, dibujé dicho planeta.", "zh": "遵照小王子的指示，我画下了那颗星球。", "t": [100, 4538]}, {"es": "Aunque no me gusta el papel de moralista, el peligro de los baobabs es tan desconocido y los peligros que puede correr quien llegue a perderse en un asteroide son tan grandes, que no vacilo en hacer una excepción y exclamar: \"¡Niños, atención a los baobabs!\" Y sólo con el fin de advertir a mis amigos de estos peligros a que se exponen desde hace ya tiempo sin saberlo, es por lo que trabajé y puse tanto empeño en realizar este dibujo.", "zh": "尽管我不喜扮演道德家的角色，但猴面包树的危险鲜为人知，而误入小行星的人所面临的危险又是如此之大，我不得不破例大声疾呼：“孩子们，当心猴面包树！”而且，正是为了向我的朋友们发出警告，让他们意识到他们早已身处其中的危险——而他们和我一样，对此一无所知——我才如此用心地完成了这幅画。", "t": [4538, 28175]}, {"es": "La lección que con él podía dar, valía la pena.", "zh": "这教训，值得。", "t": [28175, 31638]}, {"es": "Es muy posible que alguien me pregunte por qué no hay en este libro otros dibujos tan grandiosos como el dibujo de los baobabs.", "zh": "或许有人会问我，为何这本书里没有其他图画像猴面包树的画那样壮观。", "t": [31638, 38525]}, {"es": "La respuesta es muy sencilla: he tratado de hacerlos, pero no lo he logrado.", "zh": "答案很简单：我尽力了，但未能做到。", "t": [38525, 43650]}, {"es": "Cuando dibujé los baobabs estaba animado por un sentimiento de urgencia.", "zh": "画猴面包树时，我内心充满紧迫感。", "t": [43650, 47300]}]}]}, {"id": "ch06", "title_es": "Capítulo 6", "title_zh": "第 6 章", "paras": [{"id": "ch06p00", "audio": true, "sents": [{"es": "¡Ah, principito, cómo he ido comprendiendo lentamente tu vida melancólica!", "zh": "啊，小王子，我如何慢慢地领悟到你那忧郁的生活！", "t": [100, 4762]}, {"es": "Durante mucho tiempo tu única distracción fue la suavidad de las puestas de sol.", "zh": "长久以来，你唯一的慰藉便是那夕阳的温柔。", "t": [4762, 9625]}, {"es": "Este nuevo detalle lo supe al cuarto día, cuando me dijiste:", "zh": "第四天，你告诉我这个新细节：", "t": [9625, 12837]}]}, {"id": "ch06p01", "audio": true, "sents": [{"es": "-Me gustan mucho las puestas de sol; vamos a ver una puesta de sol…", "zh": "我喜欢看日落；我们去看看日落吧……", "t": [100, 3676]}]}, {"id": "ch06p02", "audio": true, "sents": [{"es": "-Tendremos que esperar…", "zh": "我们得等待……", "t": [100, 1438]}, {"es": "-¿Esperar qué?", "zh": "等待什么？", "t": [1438, 2138]}]}, {"id": "ch06p03", "audio": true, "sents": [{"es": "-Que el sol se ponga.", "zh": "夕阳西下。", "t": [100, 1175]}]}, {"id": "ch06p04", "audio": true, "sents": [{"es": "Pareciste muy sorprendido primero, y después te reíste de ti mismo.", "zh": "你先是一脸惊讶，随后又对自己笑了。", "t": [100, 4662]}, {"es": "Y me dijiste:", "zh": "你曾对我说：", "t": [4662, 5438]}]}, {"id": "ch06p05", "audio": true, "sents": [{"es": "-Siempre me creo que estoy en mi tierra.", "zh": "我总以为我回到了自己的星球。", "t": [100, 2100]}]}, {"id": "ch06p06", "audio": true, "sents": [{"es": "En efecto, como todo el mundo sabe, cuando es mediodía en Estados Unidos, en Francia se está poniendo el sol.", "zh": "果然，正如世人所知，当美国正值正午时分，法国已是夕阳西下。", "t": [100, 6550]}, {"es": "Sería suficiente poder trasladarse a Francia en un minuto para asistir a la puesta del sol, pero desgraciadamente Francia está demasiado lejos.", "zh": "若能瞬间抵达法国，便足以目睹落日的美景，然而遗憾的是法国太过遥远。", "t": [6550, 15125]}, {"es": "En cambio, sobre tu pequeño planeta te bastaba arrastrar la silla algunos pasos para presenciar el crepúsculo cada vez que lo deseabas…", "zh": "然而，在你的小星球上，你只需将椅子挪动几步，便能随时目睹黄昏降临。", "t": [15125, 22212]}, {"es": "-¡Un día vi ponerse el sol cuarenta y tres veces!", "zh": "那天，我目睹了四十三次夕阳西下。", "t": [22212, 24526]}]}, {"id": "ch06p07", "audio": true, "sents": [{"es": "Y un poco más tarde añadiste: -¿Sabes?", "zh": "你知道……", "t": [100, 3262]}, {"es": "Cuando uno está verdaderamente triste le gusta ver las puestas de sol.", "zh": "当一个人真正伤心时，喜欢看日落。", "t": [3262, 6750]}]}, {"id": "ch06p08", "audio": true, "sents": [{"es": "-El día que la viste cuarenta y tres veces estabas muy triste ¿verdad?", "zh": "那天，你看了四十三次日落，心情格外沉重，不是吗？", "t": [100, 3537]}]}, {"id": "ch06p09", "audio": true, "sents": [{"es": "Pero el principito no respondió.", "zh": "小王子没有回答。", "t": [100, 1725]}]}]}, {"id": "ch07", "title_es": "Capítulo 7", "title_zh": "第 7 章", "paras": [{"id": "ch07p00", "audio": true, "sents": [{"es": "Al quinto día y también en relación con el cordero, me fue revelado este otro secreto de la vida del principito.", "zh": "第五天，与那只绵羊有关，小王子的另一个生活秘密也被揭晓了。", "t": [100, 6925]}, {"es": "Me preguntó bruscamente y sin preámbulo, como resultado de un problema largamente meditado en silencio:", "zh": "他突然且未加任何开场白地问我，那是一个他长久以来在沉默中深思熟虑的问题：", "t": [6925, 12312]}]}, {"id": "ch07p01", "audio": true, "sents": [{"es": "-Si un cordero se come los arbustos, se comerá también las flores ¿no?", "zh": "如果绵羊吃灌木，难道它也会吃花吗？", "t": [100, 3912]}]}, {"id": "ch07p02", "audio": true, "sents": [{"es": "-Un cordero se come todo lo que encuentra.", "zh": "绵羊见什么吃什么。", "t": [100, 3175]}, {"es": "-¿Y también las flores que tienen espinas?", "zh": "带刺的花也会吃吗？", "t": [3175, 5337]}]}, {"id": "ch07p03", "audio": true, "sents": [{"es": "-Sí; también las flores que tienen espinas.", "zh": "是的，连带刺的花也会吃。", "t": [100, 2525]}]}, {"id": "ch07p04", "audio": true, "sents": [{"es": "-Entonces, ¿para qué le sirven las espinas?", "zh": "那刺还有什么用呢？", "t": [100, 2425]}]}, {"id": "ch07p05", "audio": true, "sents": [{"es": "Confieso que no lo sabía.", "zh": "我承认，我不知道。", "t": [100, 2488]}, {"es": "Estaba yo muy ocupado tratando de destornillar un perno demasiado apretado del motor; la avería comenzaba a parecerme cosa grave y la circunstancia de que se estuviera agotando mi provisión de agua, me hacía temer lo peor.", "zh": "我正忙于拧下发动机上那个过紧的螺栓，故障似乎愈发严重，而饮用水也在一点点减少，这让我愈发担忧。", "t": [2488, 15012]}, {"es": "-¿Para qué sirven las espinas?", "zh": "刺，究竟有何用？", "t": [15012, 16513]}]}, {"id": "ch07p06", "audio": true, "sents": [{"es": "El principito no permitía nunca que se dejara sin respuesta una pregunta formulada por él.", "zh": "小王子从不允许他提出的任何问题悬而未决。", "t": [100, 5512]}, {"es": "Irritado por la resistencia que me oponía el perno, le respondí lo primero que se me ocurrió:", "zh": "被那螺栓的顽强抵抗激怒，我随口答道：随口而出。", "t": [5512, 10275]}]}, {"id": "ch07p07", "audio": true, "sents": [{"es": "-Las espinas no sirven para nada; son pura maldad de las flores.", "zh": "刺毫无用处；那是花儿们的恶作剧。", "t": [100, 4700]}, {"es": "-¡Oh!", "zh": "哦！", "t": [4700, 4838]}]}, {"id": "ch07p08", "audio": true, "sents": [{"es": "Y después de un silencio, me dijo con una especie de rencor: -¡No te creo!", "zh": "然后，他带着一丝怨恨地说：“我不信你！”", "t": [100, 4850]}, {"es": "Las flores son débiles.", "zh": "花儿柔弱无力。", "t": [4850, 7225]}, {"es": "Son ingenuas.", "zh": "她们天真无邪。", "t": [7225, 9162]}, {"es": "Se defienden como pueden.", "zh": "它们尽力自卫。", "t": [9162, 11500]}, {"es": "Se creen terribles con sus espinas…", "zh": "她们以为自己的刺很可怕…", "t": [11500, 13538]}]}, {"id": "ch07p09", "audio": true, "sents": [{"es": "No le respondí nada; en aquel momento me estaba diciendo a mí mismo: \"Si este perno me resiste un poco más, lo haré saltar de un martillazo\".", "zh": "若这颗螺栓再顽抗片刻，我便用锤子将它砸飞。", "t": [100, 8700]}, {"es": "El principito me interrumpió de nuevo mis pensamientos: -¿Tú crees que las flores…?", "zh": "小王子再次打断我的思绪：“你相信，你，相信花儿……？”", "t": [8700, 12763]}]}, {"id": "ch07p10", "audio": true, "sents": [{"es": "No, no creo nada!", "zh": "我不信任何事！", "t": [100, 2500]}, {"es": "Te he respondido cualquier cosa para que te calles.", "zh": "我随你胡说八道，只为让你闭嘴。", "t": [2500, 5975]}, {"es": "Tengo que ocuparme de cosas serias.", "zh": "我得忙些正经事。", "t": [5975, 7875]}]}, {"id": "ch07p11", "audio": true, "sents": [{"es": "Me miró estupefacto.", "zh": "他惊愕地望着我。", "t": [100, 2262]}, {"es": "-¡De cosas serias!", "zh": "正经事体", "t": [2262, 3287]}]}, {"id": "ch07p12", "audio": true, "sents": [{"es": "Me miraba con mi martillo en la mano, los dedos llenos de grasa e inclinado sobre algo que le parecía muy feo.", "zh": "他手握锤子，指间沾满油脂，俯身对着他看来极丑陋的物件。", "t": [100, 6575]}, {"es": "-¡Hablas como las personas mayores!", "zh": "你说话就像大人一样！", "t": [6575, 8400]}]}, {"id": "ch07p13", "audio": true, "sents": [{"es": "Me avergonzó un poco.", "zh": "让我有些难为情。", "t": [100, 2312]}, {"es": "Pero él, implacable, añadió: -¡Lo confundes todo…todo lo mezclas…!", "zh": "但他，毫不妥协地补充道：“你把一切都搞混了……都混在一起了……！”", "t": [2312, 6287]}]}, {"id": "ch07p14", "audio": true, "sents": [{"es": "Estaba verdaderamente irritado; sacudía la cabeza, agitando al viento sus cabellos dorados.", "zh": "他真的生气了，摇头晃脑，金黄色的头发随风飘扬。", "t": [100, 5374]}]}, {"id": "ch07p15", "audio": true, "sents": [{"es": "-Conozco un planeta donde vive un señor muy colorado, que nunca ha olido una flor, ni ha mirado una estrella y que jamás ha querido a nadie.", "zh": "我知道一个星球上住着一个红脸先生，他从未闻过一朵花，从未看过一颗星星，也从未爱过任何人。", "t": [100, 8175]}, {"es": "En toda su vida no ha hecho más que sumas.", "zh": "他一生所做的只是加法。", "t": [8175, 11438]}, {"es": "Y todo el día se lo pasa repitiendo como tú: \"¡Yo soy un hombre serio, yo soy un hombre serio!\"…", "zh": "他整天就像你一样，反复地唠叨：“我是严肃的人，我是严肃的人！”", "t": [11438, 17638]}, {"es": "Al parecer esto le llema de orgullo.", "zh": "这让他颇为自豪。", "t": [17638, 20450]}, {"es": "Pero eso no es un hombre, ¡es un hongo!", "zh": "但这不是人，是蘑菇！", "t": [20450, 23412]}, {"es": "-¿Un qué?", "zh": "这是什么？", "t": [23412, 23800]}]}, {"id": "ch07p16", "audio": true, "sents": [{"es": "-Un hongo.", "zh": "这是蘑菇。", "t": [100, 650]}]}, {"id": "ch07p17", "audio": true, "sents": [{"es": "El principito estaba pálido de cólera.", "zh": "小王子气得脸色苍白。", "t": [100, 2087]}]}, {"id": "ch07p18", "audio": true, "sents": [{"es": "-Hace millones de años que las flores tiene espinas y hace también millones de años que los corderos, a pesar de las espinas, se comen las flores.", "zh": "数百万年来，花儿长着刺，羊儿尽管有刺，仍吃花不止。", "t": [100, 8562]}, {"es": "¿Es que no es cosa seria averiguar por qué las flores pierden el tiempo fabricando unas espinas que no les sirven para nada?", "zh": "探究为何花儿浪费时间去制造毫无用处的刺，难道不是一件正经事吗？", "t": [8562, 15638]}, {"es": "¿Es que no es importante la guerra de los corderos y las flores?", "zh": "羊与花的战争，难道这就不重要吗？", "t": [15638, 19800]}, {"es": "¿No es esto más serio e importante que las sumas de un señor gordo y colorado?", "zh": "这难道不比那位红脸胖子的加减法更严肃、更重要吗？", "t": [19800, 24612]}, {"es": "Y si yo sé de una flor única en el mundo y que no existe en ninguna parte más que en mi planeta; si yo sé que un buen día un corderillo puede aniquilarla sin darse cuenta de ello, ¿es que esto no es importante?", "zh": "若我知晓这世界上仅有一朵花，它只存在于我的星球上，而有一天，一只小绵羊可能无意中将其摧毁，这难道不重要吗？", "t": [24612, 35213]}]}, {"id": "ch07p19", "audio": true, "sents": [{"es": "El principito enrojeció y después continuó:", "zh": "小王子脸涨得通红，然后继续说道：", "t": [100, 2424]}]}, {"id": "ch07p20", "audio": true, "sents": [{"es": "-Si alguien ama a una flor de la que sólo existe un ejemplar en millones y millones de estrellas, basta que las mire para ser dichoso.", "zh": "若有人爱上一朵花，那朵花便在亿万星辰中绽放幸福。", "t": [100, 7538]}, {"es": "Puede decir satisfecho: \"Mi flor está allí, en alguna parte…\" ¡Pero si el cordero se la come, para él es como si de pronto todas las estrellas se apagaran!", "zh": "他可以满足地说：“我的花儿在那里，在某个地方……”但若绵羊吃了它，对他而言，就如同突然间所有的星星都熄灭了！", "t": [7538, 17575]}, {"es": "¡Y esto no es importante!", "zh": "这并不重要。", "t": [17575, 19013]}]}, {"id": "ch07p21", "audio": true, "sents": [{"es": "No pudo decir más y estalló bruscamente en sollozos.", "zh": "无法再说下去，他突然放声大哭。", "t": [100, 3050]}]}, {"id": "ch07p22", "audio": true, "sents": [{"es": "La noche había caído.", "zh": "夜幕降临。", "t": [100, 2275]}, {"es": "Yo había soltado las herramientas y ya no importaban nada el martillo, el perno, la sed y la muerte.", "zh": "我放下工具，一切——锤子、螺栓、干渴、死亡——都已不再重要。", "t": [2275, 8525]}, {"es": "¡Había en una estrella, en un planeta, el mío, la Tierra, un principito a quien consolar!", "zh": "在那颗星星上，在我的星球——地球——上，有一个小王子需要安慰！", "t": [8525, 14100]}, {"es": "Lo tomé en mis brazos y lo mecí diciéndole: \"la flor que tú quieres no corre peligro…", "zh": "我把他搂进怀里，轻柔地摇晃着，对他说：“你爱的那朵花不会有危险的……”", "t": [14100, 18775]}, {"es": "te dibujaré un bozal para tu cordero y una armadura para la flor…te…\".", "zh": "我给你小羊画个口罩，给你的花儿画身盔甲……", "t": [18775, 23075]}, {"es": "No sabía qué decirle, cómo consolarle y hacer que tuviera nuevamente confianza en mí; me sentía torpe.", "zh": "我不知如何向他倾诉，如何安慰他，让他重新对我充满信任；我感到笨拙。", "t": [23075, 29550]}, {"es": "¡Es tan misterioso el país de las lágrimas!", "zh": "泪水的王国如此神秘。", "t": [29550, 31750]}]}]}, {"id": "ch08", "title_es": "Capítulo 8", "title_zh": "第 8 章", "paras": [{"id": "ch08p00", "audio": true, "sents": [{"es": "Aprendí bien pronto a conocer mejor esta flor.", "zh": "我很快便学会了更深入地了解这朵花。", "t": [100, 3438]}, {"es": "Siempre había habido en el planeta del principito flores muy simples adornadas con una sola fila de pétalos que apenas ocupaban sitio y a nadie molestaban.", "zh": "小王子的星球上，一直生长着朴素的花朵，花瓣单行，占地不多，也不扰人。", "t": [3438, 12338]}, {"es": "Aparecían entre la hierba una mañana y por la tarde se extinguían.", "zh": "清晨绽放于草间，黄昏便悄然凋零。", "t": [12338, 16600]}, {"es": "Pero aquella había germinado un día de una semilla llegada de quién sabe dónde, y el principito había vigilado cuidadosamente desde el primer día aquella ramita tan diferente de las que él conocía.", "zh": "但那朵花却是在某天从不知名之处的一粒种子中萌发，小王子从第一天起就细心地观察着那根与他所知的花朵迥异的嫩枝。", "t": [16600, 27212]}, {"es": "Podía ser una nueva especie de Baobab.", "zh": "或许是一种新的猴面包树。", "t": [27212, 30200]}, {"es": "Pero el arbusto cesó pronto de crecer y comenzó a echar su flor.", "zh": "灌木很快停止了生长，开始绽放花朵。", "t": [30200, 34400]}, {"es": "El principito observó el crecimiento de un enorme capullo y tenía le convencimiento de que habría de salir de allí una aparición milagrosa; pero la flor no acababa de preparar su belleza al abrigo de su envoltura verde.", "zh": "小王子注视着那硕大的花蕾生长，坚信那里将绽放出奇迹般的花朵；然而，那朵花却还未在绿意盎然的庇护下完全准备她的美丽。", "t": [34400, 45100]}]}, {"id": "ch08p01", "audio": true, "sents": [{"es": "Elegía con cuidado sus colores, se vestía lentamente y se ajustaba uno a uno sus pétalos.", "zh": "她小心翼翼地挑选着色彩，缓缓地穿上衣裳，一片片地搭配她的花瓣。", "t": [100, 6100]}, {"es": "No quería salir ya ajada como las amapolas; quería aparecer en todo el esplendor de su belleza.", "zh": "不愿像虞美人般蓬头垢面地出场；她要展现出自己全部的美丽光彩。", "t": [6100, 12275]}, {"es": "¡Ah, era muy coqueta aquella flor!", "zh": "唉，她那花儿真是爱美得很。", "t": [12275, 15225]}, {"es": "Su misteriosa preparación duraba días y días.", "zh": "她神秘的准备持续了好多天。", "t": [15225, 18825]}, {"es": "Hasta que una mañana, precisamente al salir el sol se mostró espléndida.", "zh": "直到一天清晨，太阳初升时，她光彩夺目地露面。", "t": [18825, 22526]}]}, {"id": "ch08p02", "audio": true, "sents": [{"es": "La flor, que había trabajado con tanta precisión, dijo bostezando: -¡Ah, perdóname…", "zh": "那朵花，她精心打扮过后，打着哈欠说：“唉，请原谅……”", "t": [100, 4838]}, {"es": "apenas acabo de despertarme…", "zh": "我刚醒来…", "t": [4838, 6600]}, {"es": "estoy toda despeinada…!", "zh": "我乱糟糟的，头发都没梳好……", "t": [6600, 7900]}]}, {"id": "ch08p03", "audio": true, "sents": [{"es": "El principito no pudo contener su admiración: -¡Qué hermosa eres!", "zh": "小王子忍不住赞叹：你真美啊！", "t": [100, 4575]}, {"es": "-¿Verdad?", "zh": "是吗？", "t": [4575, 5962]}, {"es": "-respondió dulcemente la flor-.", "zh": "她柔声回应。", "t": [5962, 8600]}, {"es": "He nacido al mismo tiempo que el sol.", "zh": "我与太阳同日而生。", "t": [8600, 11450]}, {"es": "El principito adivinó exactamente que ella no era muy modesta ciertamente, pero ¡era tan conmovedora!", "zh": "小王子确切地感觉到她并不十分谦逊，然而她却如此动人！", "t": [11450, 16874]}]}, {"id": "ch08p04", "audio": true, "sents": [{"es": "-Me parece que ya es hora de desayunar - añadió la flor -; si tuvieras la bondad de pensar un poco en mí…", "zh": "您若能多为我着想片刻，早餐时间就到了——花儿补充道。", "t": [100, 5488]}]}, {"id": "ch08p05", "audio": true, "sents": [{"es": "Y el principito, muy confuso, habiendo ido a buscar una regadera la roció abundantemente con agua fresca.", "zh": "小王子困惑不已，去找水壶时，不慎将那朵花浇了个透心凉。", "t": [100, 5500]}]}, {"id": "ch08p06", "audio": true, "sents": [{"es": "Y así, ella lo había atormentado con su vanidad un poco sombría.", "zh": "她便用那点微不足道的虚荣心，一点点地折磨着他。", "t": [100, 4650]}, {"es": "Un día, por ejemplo, hablando de sus cuatro espinas, dijo al principito: -¡Ya pueden venir los tigres, con sus garras!", "zh": "有一天，她向小王子提起她身上那四根刺，说道：“老虎，带着它们的爪子来吧！”", "t": [4650, 11074]}]}, {"id": "ch08p07", "audio": true, "sents": [{"es": "-No hay tigres en mi planeta -observó el principito- y, además, los tigres no comen hierba.", "zh": "我的星球上没有老虎，而且老虎不吃草。", "t": [100, 5112]}]}, {"id": "ch08p08", "audio": true, "sents": [{"es": "-Yo no soy una hierba -respondió dulcemente la flor.", "zh": "我可不是草——花儿柔声回应。", "t": [100, 3050]}]}, {"id": "ch08p09", "audio": true, "sents": [{"es": "-Perdóname…", "zh": "请原谅……", "t": [100, 688]}]}, {"id": "ch08p10", "audio": true, "sents": [{"es": "-No temo a los tigres, pero tengo miedo a las corrientes de aire.", "zh": "我不怕老虎，却怕风。", "t": [100, 4438]}, {"es": "¿No tendrás un biombo?", "zh": "您没有屏风吗？", "t": [4438, 5625]}]}, {"id": "ch08p11", "audio": true, "sents": [{"es": "\"Miedo a las corrientes de aire no es una suerte para una planta -pensó el principito-.", "zh": "害怕风对一株植物来说可不是什么好事——小王子心想。", "t": [100, 5325]}, {"es": "Esta flor es demasiado complicada…\" -Por la noche me cubrirás con un fanal…", "zh": "这朵花太复杂了……——夜里你得用灯笼罩着我……", "t": [5325, 9525]}, {"es": "hace mucho frío en tu tierra.", "zh": "你的星球上寒冷得很。", "t": [9525, 11850]}, {"es": "No se está muy a gusto; allá de donde yo vengo…", "zh": "它并不太舒服；我从来的地方…", "t": [11850, 14574]}]}, {"id": "ch08p12", "audio": true, "sents": [{"es": "La flor se interrumpió; había llegado allí en forma de semilla y no era posible que conociera otros mundos.", "zh": "那朵花中断了；它是以种子的形式到来的，不可能了解其他世界。", "t": [100, 6076]}]}, {"id": "ch08p13", "audio": true, "sents": [{"es": "Humillada por haberse dejado sorprender inventando un mentira tan ingenua, tosió dos o tres veces para atraerse la simpatía del principito.", "zh": "羞愧于被小王子识破那幼稚的谎言，她咳嗽了两三声，试图赢得他的同情。", "t": [100, 8350]}, {"es": "-¿Y el biombo?", "zh": "您需要屏风吗？", "t": [8350, 8987]}]}, {"id": "ch08p14", "audio": true, "sents": [{"es": "-Iba a buscarlo, pero como no dejabas de hablarme…", "zh": "我正要去寻找，可你一直不停地和我说话……", "t": [100, 2638]}]}, {"id": "ch08p15", "audio": true, "sents": [{"es": "Insistió en su tos para darle al menos remordimientos.", "zh": "她故意咳嗽，让他心生愧疚。", "t": [100, 3163]}]}, {"id": "ch08p16", "audio": true, "sents": [{"es": "De esta manera el principito, a pesar de la buena voluntad de su amor, había llegado a dudar de ella.", "zh": "小王子尽管深爱，却开始怀疑她了。", "t": [100, 6275]}, {"es": "Había tomado en serio palabras sin importancia y se sentía desgraciado.", "zh": "他认真对待了无关紧要的话语，感到非常不幸。", "t": [6275, 10000]}]}, {"id": "ch08p17", "audio": true, "sents": [{"es": "\"Yo no debía hacerle caso -me confesó un día el principito- nunca hay que hacer caso a las flores, basta con mirarlas y olerlas.", "zh": "我本不该听信——小王子有一天对我说——永远也别信花儿的话，只需观赏她们，嗅闻她们。", "t": [100, 8050]}, {"es": "Mi flor embalsamaba el planeta, pero yo no sabía gozar con eso…", "zh": "我的玫瑰为星球熏香，我却不知珍惜。", "t": [8050, 12500]}, {"es": "Aquella historia de garra y tigres que tanto me molestó, hubiera debido enternecerme\".", "zh": "那关于爪子和老虎的故事，本该让我感动。", "t": [12500, 17113]}]}, {"id": "ch08p18", "audio": true, "sents": [{"es": "Y me contó todavía:", "zh": "她还对我说：", "t": [100, 1224]}]}, {"id": "ch08p19", "audio": true, "sents": [{"es": "\"¡No supe comprender nada entonces!", "zh": "那时我真是愚不可及！", "t": [100, 3125]}, {"es": "Debí juzgarla por sus actos y no por sus palabras.", "zh": "我应凭她的行为而非言语来评判她。", "t": [3125, 6875]}, {"es": "¡La flor perfumaba e iluminaba mi vida y jamás debí huir de allí!", "zh": "那朵花为我的生命增添了芬芳与光明，我本不该逃离那里。", "t": [6875, 11200]}, {"es": "¡No supe adivinar la ternura que ocultaban sus pobres astucias!", "zh": "她的笨拙中藏着一份温柔，我未曾猜透。", "t": [11200, 15575]}, {"es": "¡Son tan contradictorias las flores!", "zh": "花儿真是矛盾得很。", "t": [15575, 18662]}, {"es": "Pero yo era demasiado joven para saber amarla\".", "zh": "那时我太年轻，不懂如何去爱她。", "t": [18662, 21125]}]}]}, {"id": "ch09", "title_es": "Capítulo 9", "title_zh": "第 9 章", "paras": [{"id": "ch09p00", "audio": true, "sents": [{"es": "Creo que el principito aprovechó la migración de una bandada de pájaros silvestres para su evasión.", "zh": "小王子或许是在一群野鸟迁徙之际趁机逃离的。", "t": [100, 5875]}, {"es": "La mañana de la partida, puso en orden el planeta.", "zh": "启程那天清晨，他将星球整理得井井有条。", "t": [5875, 9625]}, {"es": "Deshollinó cuidadosamente sus volcanes en actividad, de los cuales poseía dos, que le eran muy útiles para calentar el desayuno todas las mañanas.", "zh": "他细心地清理了那两座活火山，它们每天早晨都为他提供了煮早餐的便利。", "t": [9625, 18538]}, {"es": "Tenía, además, un volcán extinguido.", "zh": "他还拥有一座熄灭的火山。", "t": [18538, 21625]}, {"es": "Deshollinó también el volcán extinguido, pues, como él decía, nunca se sabe lo que puede ocurrir.", "zh": "他也清理了那座熄灭的火山，因为正如他所说：“世事难料，谁知道会发生什么呢？”", "t": [21625, 27662]}, {"es": "Si los volcanes están bien deshollinados, arden sus erupciones, lenta y regularmente.", "zh": "若火山清理得当，其喷发便会缓慢而规律地燃烧。", "t": [27662, 33450]}, {"es": "Las erupciones volcánicas son como el fuego de nuestras chimeneas.", "zh": "火山爆发如同我们烟囱里的火焰。", "t": [33450, 37900]}, {"es": "Es evidente que en nuestra Tierra no hay posibilidad de deshollinar los volcanes; los hombres somos demasiado pequeños.", "zh": "显而易见，在我们地球上，我们无法清理火山；人类太过渺小。", "t": [37900, 44875]}, {"es": "Por eso nos dan tantos disgustos.", "zh": "因此，它们给我们带来了许多烦恼。", "t": [44875, 46837]}]}, {"id": "ch09p01", "audio": true, "sents": [{"es": "El principito arrancó también con un poco de melancolía los últimos brotes de baobabs.", "zh": "小王子带着一丝忧郁，拔除了最后几株猴面包树苗。", "t": [100, 5338]}, {"es": "Creía que no iba a volver nunca.", "zh": "他相信他永远不会再回来。", "t": [5338, 8112]}, {"es": "Pero todos aquellos trabajos le parecieron aquella mañana extremadamente dulces.", "zh": "但那天早晨，那些工作在他看来分外甜蜜。", "t": [8112, 13300]}, {"es": "Y cuando regó por última vez la flor y se dispuso a ponerla al abrigo del fanal, sintió ganas de llorar.", "zh": "最后一次给花儿浇水，准备为她遮挡风灯，他竟忍不住想流泪。", "t": [13300, 18788]}]}, {"id": "ch09p02", "audio": true, "sents": [{"es": "-Adiós -le dijo a la flor.", "zh": "他向花儿道别。", "t": [100, 2612]}, {"es": "Esta no respondió.", "zh": "她没有回答。", "t": [2612, 3724]}]}, {"id": "ch09p03", "audio": true, "sents": [{"es": "-Adiós -repitió el principito.", "zh": "小王子又说：“再见。”", "t": [100, 1913]}]}, {"id": "ch09p04", "audio": true, "sents": [{"es": "La flor tosió, pero no porque estuviera resfriada.", "zh": "花儿咳嗽，却非因感冒。", "t": [100, 2724]}]}, {"id": "ch09p05", "audio": true, "sents": [{"es": "-He sido una tonta -le dijo al fin la flor-.", "zh": "她终于说道：“我真是傻。”", "t": [100, 3438]}, {"es": "Perdóname.", "zh": "请原谅我。", "t": [3438, 5050]}, {"es": "Procura ser feliz.", "zh": "努力寻找幸福。", "t": [5050, 6100]}]}, {"id": "ch09p06", "audio": true, "sents": [{"es": "Se sorprendió por la ausencia de reproches y quedó desconcertado, con el fanal en el aire, no comprendiendo esta tranquila mansedumbre.", "zh": "他惊讶于没有责备，手持灯笼，困惑不已，不解这份平静的温顺。", "t": [100, 7000]}]}, {"id": "ch09p07", "audio": true, "sents": [{"es": "-Sí, yo te quiero -le dijo la flor-, ha sido culpa mía que tú no lo sepas; pero eso no tiene importancia.", "zh": "是的，我爱你——花儿说——“是我错了，你从未察觉到我对你的爱；但这并无大碍。”", "t": [100, 5750]}]}, {"id": "ch09p08", "audio": true, "sents": [{"es": "Y tú has sido tan tonto como yo.", "zh": "你和我一样傻。", "t": [100, 2850]}, {"es": "Trata de ser feliz…", "zh": "试着快乐吧……", "t": [2850, 4862]}, {"es": "Y suelta de una vez ese fanal; ya no lo quiero.", "zh": "她终于放下那盏灯笼；她不再需要它了。", "t": [4862, 7562]}]}, {"id": "ch09p09", "audio": true, "sents": [{"es": "-Pero el viento…", "zh": "但风……", "t": [100, 800]}]}, {"id": "ch09p10", "audio": true, "sents": [{"es": "-No estoy tan resfriada como para…", "zh": "我并未如此感冒，以至于…", "t": [100, 2938]}, {"es": "El aire fresco de la noche me hará bien.", "zh": "夜间的清风吹拂对我大有裨益。", "t": [2938, 5912]}, {"es": "Soy una flor.", "zh": "我是一朵花。", "t": [5912, 6763]}]}, {"id": "ch09p11", "audio": true, "sents": [{"es": "-Y los animales…", "zh": "动物们……", "t": [100, 1000]}]}, {"id": "ch09p12", "audio": true, "sents": [{"es": "-Será necesario que soporte dos o tres orugas, si quiero conocer las mariposas; creo que son muy hermosas.", "zh": "若想认识蝴蝶，就必须忍受两三条毛虫，我想它们一定很美。", "t": [100, 7100]}, {"es": "Si no ¿quién vendrá a visitarme?", "zh": "若无人来访，谁来探望我？", "t": [7100, 9938]}, {"es": "Tú estarás muy lejos.", "zh": "你将离得很远。", "t": [9938, 12162]}, {"es": "En cuanto a las fieras, no las temo: yo tengo mis garras.", "zh": "至于野兽，我不怕：我有我的爪子。", "t": [12162, 15537]}]}, {"id": "ch09p13", "audio": true, "sents": [{"es": "Y le mostraba ingenuamente sus cuatro espinas.", "zh": "她天真地展示着她那四根刺。", "t": [100, 3600]}, {"es": "Luego añadió:", "zh": "他接着补充道：", "t": [3600, 4450]}]}, {"id": "ch09p14", "audio": true, "sents": [{"es": "-Y no prolongues más tu despedida.", "zh": "别再拖延你的告别了。", "t": [100, 2912]}, {"es": "Puesto que has decidido partir, vete de una vez.", "zh": "既然你已决定离去，就立刻动身吧。", "t": [2912, 5450]}]}, {"id": "ch09p15", "audio": true, "sents": [{"es": "La flor no quería que la viese llorar: era tan orgullosa..", "zh": "这朵花儿不愿让他看到自己哭泣：她如此骄傲。", "t": [100, 3238]}]}]}, {"id": "ch10", "title_es": "Capítulo 10", "title_zh": "第 10 章", "paras": [{"id": "ch10p00", "audio": true, "sents": [{"es": "Se encontraba en la región de los asteroides 325, 326, 327, 328, 329 y 330.", "zh": "他居住的星球位于小行星325号、326号、327号、328号、329号、330号所在的地区。", "t": [100, 8712]}, {"es": "Para ocuparse en algo e instruirse al mismo tiempo decidió visitarlos.", "zh": "为了有所事事并增长见识，他决定去拜访它们。", "t": [8712, 14426]}]}, {"id": "ch10p01", "audio": true, "sents": [{"es": "El primero estaba habitado por un rey.", "zh": "第1颗星上住着一位国王。", "t": [100, 3025]}, {"es": "El rey, vestido de púrpura y armiño, estaba sentado sobre un trono muy sencillo y, sin embargo, majestuoso.", "zh": "国王身着紫红袍，坐在一张既简单又威严的宝座上。", "t": [3025, 9113]}]}, {"id": "ch10p02", "audio": true, "sents": [{"es": "-¡Ah, -exclamó el rey al divisar al principito-, aquí tenemos un súbdito!", "zh": "啊，国王一见到小王子就喊道：“这里有个臣民！”", "t": [100, 3963]}]}, {"id": "ch10p03", "audio": true, "sents": [{"es": "El principito se preguntó:", "zh": "小王子心想：这是怎么回事？", "t": [100, 1500]}]}, {"id": "ch10p04", "audio": true, "sents": [{"es": "\"¿Cómo es posible que me reconozca si nunca me ha visto?\"", "zh": "他怎么认出我，他从未见过我呢？", "t": [100, 2813]}]}, {"id": "ch10p05", "audio": true, "sents": [{"es": "Ignoraba que para los reyes el mundo está muy simplificado.", "zh": "国王不知，对于国王们来说，世界太过简单了。", "t": [100, 4025]}, {"es": "Todos los hombres son súbditos.", "zh": "世人皆为臣民。", "t": [4025, 5738]}]}, {"id": "ch10p06", "audio": true, "sents": [{"es": "-Aproxímate para que te vea mejor -le dijo el rey, que estaba orgulloso de ser por fin el rey de alguien.", "zh": "国王自豪地说：“走近点，让我更好地看看你。”", "t": [100, 6588]}, {"es": "El principito buscó donde sentarse, pero el planeta estaba ocupado totalmente por el magnífico manto de armiño.", "zh": "小王子寻找可坐之处，却发现整个星球已被那华丽的貂皮大衣占据。", "t": [6588, 12425]}]}, {"id": "ch10p07", "audio": true, "sents": [{"es": "Se quedó, pues, de pie, pero como estaba cansado, bostezó.", "zh": "于是，他站着，但既然疲惫不堪，便打了个哈欠。", "t": [100, 3237]}]}, {"id": "ch10p08", "audio": true, "sents": [{"es": "-La etiqueta no permite bostezar en presencia del rey -le dijo el monarca-.", "zh": "礼节不容在国王面前打哈欠。", "t": [100, 5000]}, {"es": "Te lo prohíbo.", "zh": "我禁止你。", "t": [5000, 5674]}]}, {"id": "ch10p09", "audio": true, "sents": [{"es": "-No he podido evitarlo -respondió el principito muy confuso-, he hecho un viaje muy largo y apenas he dormido…", "zh": "我忍不住了——小王子非常困惑地回答道——我走了很长的路，几乎没睡过觉…", "t": [100, 6025]}]}, {"id": "ch10p10", "audio": true, "sents": [{"es": "-Entonces -le dijo el rey- te ordeno que bosteces.", "zh": "于是——国王说——我命令你打哈欠。", "t": [100, 4088]}, {"es": "Hace años que no veo bostezar a nadie.", "zh": "多年未见有人打哈欠了。", "t": [4088, 7150]}, {"es": "Los bostezos son para mí algo curioso.", "zh": "打哈欠对我来说颇为稀奇。", "t": [7150, 10288]}, {"es": "¡Vamos, bosteza otra vez, te lo ordeno!", "zh": "快，再打一个哈欠，我命令你！", "t": [10288, 12413]}]}, {"id": "ch10p11", "audio": true, "sents": [{"es": "-Me da vergüenza…", "zh": "我感到羞愧…", "t": [100, 1138]}, {"es": "ya no tengo ganas…", "zh": "我已无兴致…", "t": [1138, 2400]}, {"es": "-dijo el principito enrojeciendo.", "zh": "小王子涨红了脸。", "t": [2400, 5025]}, {"es": "-¡Hum, hum!", "zh": "嗯，嗯！", "t": [5025, 6662]}, {"es": "-respondió el rey-.", "zh": "国王答道。", "t": [6662, 8688]}, {"es": "¡Bueno!", "zh": "好极了！", "t": [8688, 10088]}, {"es": "Te ordeno tan pronto que bosteces y que no bosteces…", "zh": "我命令你，时而打哈欠，时而别打。", "t": [10088, 12725]}]}, {"id": "ch10p12", "audio": true, "sents": [{"es": "Tartamudeaba un poco y parecía vejado, pues el rey daba gran importancia a que su autoridad fuese respetada.", "zh": "国王有些结巴，显得有些尴尬，因为他非常看重自己的权威得到尊重。", "t": [100, 5850]}]}, {"id": "ch10p13", "audio": true, "sents": [{"es": "Era un monarca absoluto, pero como era muy bueno, daba siempre órdenes razonables.", "zh": "这位国王是绝对的君主，然而由于他十分仁慈，总是发布合理的命令。", "t": [100, 4638]}]}, {"id": "ch10p14", "audio": true, "sents": [{"es": "Si yo ordenara -decía frecuentemente-, si yo ordenara a un general que se transformara en ave marina y el general no me obedeciese, la culpa no sería del general, sino mía\".", "zh": "若我下令——他经常这么说——若我命令一位将军变成海鸟，而将军不服从，那责任不在将军，而在我。", "t": [100, 10375]}, {"es": "-¿Puedo sentarme?", "zh": "我可以坐下吗？", "t": [10375, 12212]}, {"es": "-preguntó tímidamente el principito.", "zh": "小王子怯怯地问。", "t": [12212, 14124]}]}, {"id": "ch10p15", "audio": true, "sents": [{"es": "-Te ordeno sentarte -le respondió el rey-, recogiendo majestuosamente un faldón de su manto de armiño.", "zh": "国王威严地一挥貂皮披风的下摆，答道：“我命令你坐下。”", "t": [100, 5475]}]}, {"id": "ch10p16", "audio": true, "sents": [{"es": "El principito estaba sorprendido.", "zh": "小王子感到惊讶。", "t": [100, 2862]}, {"es": "Aquel planeta era tan pequeño que no se explicaba sobre quién podría reinar aquel rey.", "zh": "那颗星球如此之小，难以解释那位国王统治何方。", "t": [2862, 7275]}]}, {"id": "ch10p17", "audio": true, "sents": [{"es": "-Señor -le dijo-, perdóneme si le pregunto…", "zh": "先生——他对小王子说——请原谅我向您提问……", "t": [100, 2476]}]}, {"id": "ch10p18", "audio": true, "sents": [{"es": "-Te ordeno que me preguntes -se apresuró a decir el rey.", "zh": "我命令你提问。", "t": [100, 3050]}]}, {"id": "ch10p19", "audio": true, "sents": [{"es": "-Señor…", "zh": "先生…", "t": [100, 775]}, {"es": "¿sobre qué ejerce su poder?", "zh": "他统治的是什么？", "t": [775, 2188]}]}, {"id": "ch10p20", "audio": true, "sents": [{"es": "-Sobre todo -contestó el rey con gran ingenuidad.", "zh": "国王天真地回答道：“尤其是……”", "t": [100, 3588]}, {"es": "-¿Sobre todo?", "zh": "尤其是……", "t": [3588, 4250]}]}, {"id": "ch10p21", "audio": true, "sents": [{"es": "El rey, con un gesto sencillo, señaló su planeta, los otros planetas y las estrellas.", "zh": "国王轻挥一指，指向了他的星球、其他行星和星星。", "t": [100, 6088]}, {"es": "-¿Sobre todo eso?", "zh": "尤其是这一切？", "t": [6088, 8050]}, {"es": "-volvió a preguntar el principito.", "zh": "小王子又问了一次。", "t": [8050, 9713]}]}, {"id": "ch10p22", "audio": true, "sents": [{"es": "-Sobre todo eso…", "zh": "尤其是这一切…", "t": [100, 1300]}, {"es": "-respondió el rey.", "zh": "国王答道。", "t": [1300, 2338]}]}, {"id": "ch10p23", "audio": true, "sents": [{"es": "No era sólo un monarca absoluto, era, además, un monarca universal.", "zh": "既是绝对君主，亦是宇宙之王。", "t": [100, 4888]}, {"es": "-¿Y las estrellas le obedecen?", "zh": "星星都听命于您吗？", "t": [4888, 7450]}, {"es": "-¡Naturalmente!", "zh": "当然啦", "t": [7450, 9362]}, {"es": "-le dijo el rey-.", "zh": "国王说道。", "t": [9362, 11212]}, {"es": "Y obedecen en seguida, pues yo no tolero la indisciplina.", "zh": "他们立刻遵从，因为我不能容忍无纪律的行为。", "t": [11212, 14362]}]}, {"id": "ch10p24", "audio": true, "sents": [{"es": "Un poder semejante dejó maravillado al principito.", "zh": "这股力量令小王子感到惊奇。", "t": [100, 3750]}, {"es": "Si él disfrutara de un poder de tal naturaleza, hubiese podido asistir en el mismo día, no a cuarenta y tres, sino a setenta y dos, a cien, o incluso a doscientas puestas de sol, sin tener necesidad de arrastrar su silla.", "zh": "若他拥有如此巨大的权力，便能同日观赏七十二次、一百次，甚至两百次日落，无需挪动椅子。", "t": [3750, 17088]}, {"es": "Y como se sentía un poco triste al recordar su pequeño planeta abandonado, se atrevió a solicitar una gracia al rey:", "zh": "想起那颗被遗弃的小星球，他鼓起勇气向国王请求恩典：", "t": [17088, 23263]}]}, {"id": "ch10p25", "audio": true, "sents": [{"es": "-Me gustaría ver una puesta de sol…", "zh": "我愿看一场日落。", "t": [100, 2862]}, {"es": "Deme ese gusto…", "zh": "让我也尝尝这滋味…", "t": [2862, 4938]}, {"es": "Ordénele al sol que se ponga…", "zh": "命令太阳落山吧…", "t": [4938, 6512]}]}, {"id": "ch10p26", "audio": true, "sents": [{"es": "-Si yo le diera a un general la orden de volar de flor en flor como una mariposa, o de escribir una tragedia, o de transformarse en ave marina y el general no ejecutase la orden recibida ¿de quién sería la culpa, mía o de él?", "zh": "若我命令一位将军像蝴蝶那样在花间飞舞，或写一部悲剧，或变成海鸟，而将军不服从命令，那责任该由我来承担，还是他呢？", "t": [100, 12537]}]}, {"id": "ch10p27", "audio": true, "sents": [{"es": "-La culpa sería de usted -le dijo el principito con firmeza.", "zh": "责任应由您承担。", "t": [100, 3326]}]}, {"id": "ch10p28", "audio": true, "sents": [{"es": "-Exactamente.", "zh": "正是如此。", "t": [100, 1950]}, {"es": "Sólo hay que pedir a cada uno, lo que cada uno puede dar -continuó el rey.", "zh": "只需请求每个人贡献他们所能。", "t": [1950, 6800]}, {"es": "La autoridad se apoya antes que nada en la razón.", "zh": "权威首先建立在理性之上。", "t": [6800, 10300]}, {"es": "Si ordenas a tu pueblo que se tire al mar, el pueblo hará la revolución.", "zh": "若你命令你的百姓跳海，百姓便会起义。", "t": [10300, 14912]}, {"es": "Yo tengo derecho a exigir obediencia, porque mis órdenes son razonables.", "zh": "我有权要求服从，因为我的命令合乎情理。", "t": [14912, 20000]}, {"es": "-¿Entonces mi puesta de sol?", "zh": "那么，日落时分呢？", "t": [20000, 22425]}, {"es": "-recordó el principito, que jamás olvidaba su pregunta una vez que la había formulado.", "zh": "小王子记得，一旦提出问题，他就绝不会忘记。", "t": [22425, 26576]}]}, {"id": "ch10p29", "audio": true, "sents": [{"es": "-Tendrás tu puesta de sol.", "zh": "你将看到日落。", "t": [100, 2412]}, {"es": "La exigiré.", "zh": "我要求它。", "t": [2412, 4138]}, {"es": "Pero, según me dicta mi ciencia gobernante, esperaré que las condiciones sean favorables.", "zh": "然而，根据我的统治科学，我将等待条件有利。", "t": [4138, 9538]}, {"es": "-¿Y cuándo será eso?", "zh": "那会是什么时候呢？", "t": [9538, 11588]}, {"es": "-¡Ejem, ejem!", "zh": "哼，哼！", "t": [11588, 13512]}, {"es": "-le respondió el rey, consultando previamente un enorme calendario-, ¡ejem, ejem!", "zh": "陛下查阅了那本巨大的日历，清了清嗓子，说道：“哼，哼！”", "t": [13512, 18488]}, {"es": "será hacia…", "zh": "将临", "t": [18488, 19538]}, {"es": "hacia…", "zh": "向着…", "t": [19538, 20125]}, {"es": "será hacia las siete cuarenta.", "zh": "大约七点四十。", "t": [20125, 22575]}, {"es": "Ya verás cómo se me obedece.", "zh": "你将看到他们如何服从我。", "t": [22575, 24150]}]}, {"id": "ch10p30", "audio": true, "sents": [{"es": "El principito bostezó.", "zh": "小王子打了个哈欠。", "t": [100, 2288]}, {"es": "Lamentaba su puesta de sol frustrada y además se estaba aburriendo ya un poco.", "zh": "惋惜日落落空，又觉有些许无聊。", "t": [2288, 6400]}]}, {"id": "ch10p31", "audio": true, "sents": [{"es": "-Ya no tengo nada que hacer aquí -le dijo al rey-.", "zh": "“我在这儿已经无事可做了。”他对国王说。", "t": [100, 3588]}, {"es": "Me voy.", "zh": "我走了。", "t": [3588, 4062]}]}, {"id": "ch10p32", "audio": true, "sents": [{"es": "-No partas -le respondió el rey que se sentía muy orgulloso de tener un súbdito-, no te vayas y te hago ministro.", "zh": "陛下答道：“别走，我封你为部长。”", "t": [100, 7075]}, {"es": "-¿Ministro de qué?", "zh": "司法部长。", "t": [7075, 8925]}, {"es": "-¡De…", "zh": "他曾经…", "t": [8925, 9175]}, {"es": "de justicia!", "zh": "司法部", "t": [9175, 10962]}, {"es": "-¡Pero si aquí no hay nadie a quien juzgar!", "zh": "但这里没人可审判啊！", "t": [10962, 12987]}]}, {"id": "ch10p33", "audio": true, "sents": [{"es": "-Eso no se sabe -le dijo el rey-.", "zh": "这无人知晓。", "t": [100, 2925]}, {"es": "Nunca he recorrido todo mi reino.", "zh": "我从未巡视过我的王国。", "t": [2925, 5900]}, {"es": "Estoy muy viejo y el caminar me cansa.", "zh": "我年事已高，行走已感疲惫。", "t": [5900, 8988]}, {"es": "Y como no hay sitio para una carroza…", "zh": "此处无车可停。", "t": [8988, 11250]}, {"es": "-¡Oh!", "zh": "哦！", "t": [11250, 12300]}, {"es": "Pero yo ya he visto…", "zh": "但我已经看过了…", "t": [12300, 13588]}, {"es": "-dijo el principito que se inclinó para echar una ojeada al otro lado del planeta-.", "zh": "小王子弯腰朝星球的另一端瞥了一眼。", "t": [13588, 18688]}, {"es": "Allá abajo no hay nadie tampoco..", "zh": "下面也没有人。", "t": [18688, 20525]}]}, {"id": "ch10p34", "audio": true, "sents": [{"es": "-Te juzgarás a ti mismo -le respondió el rey-.", "zh": "你将自我审判。", "t": [100, 3650]}, {"es": "Es lo más difícil.", "zh": "这最为艰难。", "t": [3650, 5662]}, {"es": "Es mucho más difícil juzgarse a sí mismo, que juzgar a los otros.", "zh": "自我审判比审判他人更为艰难。", "t": [5662, 10288]}, {"es": "Si consigues juzgarte rectamente es que eres un verdadero sabio.", "zh": "若能公正地审判自己，便是真正的智者。", "t": [10288, 13800]}]}, {"id": "ch10p35", "audio": true, "sents": [{"es": "-Yo puedo juzgarme a mí mismo en cualquier parte y no tengo necesidad de vivir aquí.", "zh": "我可以在任何地方自我审判，无需住在这里。", "t": [100, 5062]}, {"es": "-¡Ejem, ejem!", "zh": "哼，哼！", "t": [5062, 6988]}, {"es": "Creo -dijo el rey- que en alguna parte del planeta vive una rata vieja; yo la oigo por la noche.", "zh": "国王说：“我想，在这颗星球某个角落，住着一只老耗子；我夜里能听到它的声音。”", "t": [6988, 13262]}, {"es": "Tu podrás juzgar a esta rata vieja.", "zh": "你将审判这只老耗子。", "t": [13262, 16188]}, {"es": "La condenarás a muerte de vez en cuando.", "zh": "时而将其判处死刑。", "t": [16188, 19162]}, {"es": "Su vida dependería de tu justicia y la indultarás en cada juicio para conservarla, ya que no hay más que una.", "zh": "你的公正将决定它的生死，且在每一次审判中你都将赦免它，因为仅此一个。", "t": [19162, 24637]}]}, {"id": "ch10p36", "audio": true, "sents": [{"es": "-A mí no me gusta condenar a muerte a nadie -dijo el principito-.", "zh": "我不喜欢判处任何人死刑——小王子说。", "t": [100, 4488]}, {"es": "Creo que me voy a marchar.", "zh": "我想我该走了。", "t": [4488, 5800]}]}, {"id": "ch10p37", "audio": true, "sents": [{"es": "-No -dijo el rey.", "zh": "国王说：“不。”", "t": [100, 1362]}]}, {"id": "ch10p38", "audio": true, "sents": [{"es": "Pero el principito, que habiendo terminado ya sus preparativos no quiso disgustar al viejo monarca, dijo:", "zh": "小王子，在完成他的准备后，不想让这位老国王不悦，便说：", "t": [100, 5337]}]}, {"id": "ch10p39", "audio": true, "sents": [{"es": "-Si Vuestra Majestad deseara ser obedecido puntualmente, podría dar una orden razonable.", "zh": "若陛下希望令出即行，可下达合理的命令。", "t": [100, 5925]}, {"es": "Podría ordenarme, por ejemplo, partir antes de un minuto.", "zh": "我可以命令你在一分钟之内离开。", "t": [5925, 9788]}, {"es": "Me parece que las condiciones son favorables…", "zh": "看来条件很适宜…", "t": [9788, 12137]}]}, {"id": "ch10p40", "audio": true, "sents": [{"es": "Como el rey no respondiera nada, el principito vaciló primero y con un suspiro emprendió la marcha.", "zh": "国王沉默不语，小王子犹豫片刻，然后叹了口气，开始行走。", "t": [100, 6150]}, {"es": "-¡Te nombro mi embajador!", "zh": "我封你为大使！", "t": [6150, 8238]}, {"es": "-se apresuró a gritar el rey.", "zh": "国王急忙喊道。", "t": [8238, 10788]}, {"es": "Tenía un aspecto de gran autoridad.", "zh": "威严之态尽显无遗。", "t": [10788, 12738]}]}, {"id": "ch10p41", "audio": true, "sents": [{"es": "\"Las personas mayores son muy extrañas\", se decía el principito para sí mismo durante el viaje.", "zh": "大人们真是奇怪。", "t": [100, 5063]}]}]}, {"id": "ch11", "title_es": "Capítulo 11", "title_zh": "第 11 章", "paras": [{"id": "ch11p00", "audio": true, "sents": [{"es": "El segundo planeta estaba habitado por un vanidoso:", "zh": "第二颗星球住着一个虚荣的人。", "t": [100, 2787]}]}, {"id": "ch11p01", "audio": true, "sents": [{"es": "-¡Ah!", "zh": "啊！", "t": [100, 1362]}, {"es": "¡Ah!", "zh": "啊！", "t": [1362, 2625]}, {"es": "¡Un admirador viene a visitarme!", "zh": "一位崇拜者来拜访我了。", "t": [2625, 5388]}, {"es": "-Gritó el vanidoso al divisar a lo lejos al principito.", "zh": "爱慕虚荣的人远远望见小王子便大声喊道。", "t": [5388, 8100]}]}, {"id": "ch11p02", "audio": true, "sents": [{"es": "Para los vanidosos todos los demás hombres son admiradores.", "zh": "对于虚荣者，所有其他人都是崇拜者。", "t": [100, 4125]}, {"es": "-¡Buenos días!", "zh": "您好！", "t": [4125, 5975]}, {"es": "-dijo el principito-.", "zh": "小王子说。", "t": [5975, 8050]}, {"es": "¡Qué sombrero tan raro tiene!", "zh": "这顶帽子真奇怪！", "t": [8050, 9587]}]}, {"id": "ch11p03", "audio": true, "sents": [{"es": "-Es para saludar a los que me aclaman -respondió el vanidoso.", "zh": "这顶帽子是用来向欢呼我的人致敬的——虚荣的人答道。", "t": [100, 3375]}]}, {"id": "ch11p04", "audio": true, "sents": [{"es": "Desgraciadamente nunca pasa nadie por aquí.", "zh": "遗憾的是，这里从来没有人经过。", "t": [100, 3438]}, {"es": "-¿Ah, sí?", "zh": "啊，是吗？", "t": [3438, 5050]}, {"es": "-preguntó sin comprender el principito.", "zh": "小王子不解地问道。", "t": [5050, 7100]}]}, {"id": "ch11p05", "audio": true, "sents": [{"es": "-Golpea tus manos una contra otra -le aconsejó el vanidoso.", "zh": "请用手掌相击——虚荣的人建议道。", "t": [100, 3438]}]}, {"id": "ch11p06", "audio": true, "sents": [{"es": "El principito aplaudió y el vanidoso le saludó modestamente levantando el sombrero.", "zh": "小王子鼓掌，虚荣的人便谦逊地举起帽子行礼。", "t": [100, 4225]}]}, {"id": "ch11p07", "audio": true, "sents": [{"es": "\"Esto parece más divertido que la visita al rey\", se dijo para sí el principito, que continuó aplaudiendo mientras el vanidoso volvía a saludarle quitándose el sombrero.", "zh": "这比去见国王有趣多了，小王子一边鼓掌，一边看着虚荣的人重新戴上帽子。", "t": [100, 8787]}]}, {"id": "ch11p08", "audio": true, "sents": [{"es": "A los cinco minutos el principito se cansó con la monotonía de aquel juego.", "zh": "五分钟后，小王子对这种单调的游戏感到厌倦。", "t": [100, 4788]}, {"es": "-¿Qué hay que hacer para que el sombrero se caiga?", "zh": "要怎样做才能让这顶帽子掉下来？", "t": [4788, 7938]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [7938, 9137]}]}, {"id": "ch11p09", "audio": true, "sents": [{"es": "Pero el vanidoso no le oyó.", "zh": "虚荣的人没有听见。", "t": [100, 2462]}, {"es": "Los vanidosos sólo oyen las alabanzas.", "zh": "虚荣者只听见赞美声。", "t": [2462, 5712]}, {"es": "-¿Tú me admiras mucho, verdad?", "zh": "你真的很喜欢我，是吗？", "t": [5712, 8175]}, {"es": "-preguntó el vanidoso al principito.", "zh": "虚荣的人问小王子。", "t": [8175, 11012]}, {"es": "-¿Qué significa admirar?", "zh": "“崇拜意味着什么？”", "t": [11012, 12250]}]}, {"id": "ch11p10", "audio": true, "sents": [{"es": "-Admirar significa reconocer que yo soy el hombre más bello, el mejor vestido, el más rico y el más ïnteligente del planeta.", "zh": "崇拜意味着承认我是这个星球上最英俊、最会穿衣打扮、最富有、最聪明的人。", "t": [100, 7688]}, {"es": "-¡Si tú estás solo en tu planeta!", "zh": "你独自一人在你的星球上！", "t": [7688, 10400]}, {"es": "-¡Hazme ese favor, admírame de todas maneras!", "zh": "请无论如何都夸赞我一番！", "t": [10400, 14050]}, {"es": "-¡Bueno!", "zh": "您好！", "t": [14050, 15450]}, {"es": "Te admiro -dijo el principito encogiéndose de hombros-, pero ¿para qué te sirve?", "zh": "我崇拜你——小王子耸了耸肩，但那对你又有什么用呢？", "t": [15450, 19362]}]}, {"id": "ch11p11", "audio": true, "sents": [{"es": "Y el principito se marchó.", "zh": "小王子离开了。", "t": [100, 1475]}]}, {"id": "ch11p12", "audio": true, "sents": [{"es": "\"Decididamente, las personas mayores son muy extrañas\", se decía para sí el principito durante su viaje.", "zh": "大人们确实很古怪，小王子在旅途中自言自语。", "t": [100, 5650]}]}]}, {"id": "ch12", "title_es": "Capítulo 12", "title_zh": "第 12 章", "paras": [{"id": "ch12p00", "audio": true, "sents": [{"es": "El planeta siguiente estaba habitado por un bebedor.", "zh": "下一颗星球住着一位酒徒。", "t": [100, 3612]}, {"es": "Fue una visita muy corta, pues hundió al principito en una gran melancolía.", "zh": "这次拜访虽短，却让小王子陷入深深的忧郁。", "t": [3612, 7387]}]}, {"id": "ch12p01", "audio": true, "sents": [{"es": "-¿Qué haces ahí?", "zh": "你在那里做什么？", "t": [100, 1838]}, {"es": "-preguntó al bebedor que estaba sentado en silencio ante un sinnúmero de botellas vacías y otras tantas botellas llenas.", "zh": "他问那坐在一堆空瓶和满瓶前的酒徒。", "t": [1838, 8775]}, {"es": "-¡Bebo!", "zh": "我在喝酒。", "t": [8775, 10175]}, {"es": "-respondió el bebedor con tono lúgubre.", "zh": "他语气沉郁地回答。", "t": [10175, 13275]}, {"es": "-¿Por qué bebes?", "zh": "你为何饮酒？", "t": [13275, 15000]}, {"es": "-volvió a preguntar el principito.", "zh": "小王子又问。", "t": [15000, 16663]}]}, {"id": "ch12p02", "audio": true, "sents": [{"es": "-Para olvidar.", "zh": "为了忘却。", "t": [100, 1762]}, {"es": "-¿Para olvidar qué?", "zh": "为了忘却何事？", "t": [1762, 3588]}, {"es": "-inquirió el principito ya compadecido.", "zh": "小王子已生怜悯之心，又问。", "t": [3588, 5638]}]}, {"id": "ch12p03", "audio": true, "sents": [{"es": "-Para olvidar que siento vergüenza -confesó el bebedor bajando la cabeza.", "zh": "为了忘却我感到羞愧——酒徒低下头，老实承认。", "t": [100, 4775]}, {"es": "-¿Vergüenza de qué?", "zh": "为羞愧何事？", "t": [4775, 6612]}, {"es": "-se informó el principito deseoso de ayudarle.", "zh": "小王子渴望帮助他，得知了详情。", "t": [6612, 10112]}, {"es": "-¡Vergüenza de beber!", "zh": "饮酒之耻", "t": [10112, 12088]}, {"es": "-concluyó el bebedor, que se encerró nueva y definitivamente en el silencio.", "zh": "酒徒说完，便彻底闭上了嘴，陷入了沉默。", "t": [12088, 15750]}]}, {"id": "ch12p04", "audio": true, "sents": [{"es": "Y el principito, perplejo, se marchó.", "zh": "小王子困惑不已，便离去了。", "t": [100, 2076]}]}, {"id": "ch12p05", "audio": true, "sents": [{"es": "\"No hay la menor duda de que las personas mayores son muy extrañas\", seguía diciéndose para sí el principito durante su viaje.", "zh": "大人真是古怪得不可思议，小王子在旅途中自言自语道。", "t": [100, 6400]}]}]}, {"id": "ch13", "title_es": "Capítulo 13", "title_zh": "第 13 章", "paras": [{"id": "ch13p00", "audio": true, "sents": [{"es": "El cuarto planeta estaba ocupado por un hombre de negocios.", "zh": "第四颗星球住着一位商人。", "t": [100, 4062]}, {"es": "Este hombre estaba tan abstraído que ni siquiera levantó la cabeza a la llegada del principito.", "zh": "这位商人如此全神贯注，以至于小王子到来时他连头都没抬一下。", "t": [4062, 8538]}]}, {"id": "ch13p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "您好！", "t": [100, 1950]}, {"es": "-le dijo éste-.", "zh": "他这么说。", "t": [1950, 3788]}, {"es": "Su cigarro se ha apagado.Tres y dos cinco.", "zh": "您的香烟已经熄灭了。三加二等于五。", "t": [3788, 7475]}, {"es": "Cinco y siete doce.", "zh": "五加七等于十二。", "t": [7475, 9750]}, {"es": "Doce y tres quince.", "zh": "十二加三十五。", "t": [9750, 11962]}, {"es": "¡Buenos días!", "zh": "您好！", "t": [11962, 13812]}, {"es": "Quince y siete veintidós.", "zh": "十五加七等于二十二。", "t": [13812, 16300]}, {"es": "Veintidós y seis veintiocho.", "zh": "二十二加六十八。", "t": [16300, 18950]}, {"es": "No tengo tiempo de encenderlo.", "zh": "没时间点烟。", "t": [18950, 21638]}, {"es": "Veintiocho y tres treinta y uno.", "zh": "二十八加三十三十一。", "t": [21638, 24375]}, {"es": "¡Uf!", "zh": "唉！", "t": [24375, 25738]}, {"es": "Esto suma quinientos un millones seiscientos veintidós mil setecientos treinta y uno.", "zh": "五亿零一百六十二万二千七百三十一。", "t": [25738, 31062]}, {"es": "-¿Quinientos millones de qué?", "zh": "五亿零一百六十二万二千七百三十一是什么？", "t": [31062, 33338]}, {"es": "-¿Eh?", "zh": "咦？", "t": [33338, 34512]}, {"es": "¿Estás ahí todavía?", "zh": "您还在吗？", "t": [34512, 36588]}, {"es": "Quinientos millones de…", "zh": "五亿零…", "t": [36588, 37875]}, {"es": "ya no sé…", "zh": "我已经不知道了…", "t": [37875, 39438]}, {"es": "¡He trabajado tanto!", "zh": "我辛勤工作了！", "t": [39438, 41488]}, {"es": "¡Yo soy un hombre serio y no me entretengo en tonterías!", "zh": "我是个正经人，不闲扯。", "t": [41488, 45375]}, {"es": "Dos y cinco siete…", "zh": "二加五等于七…", "t": [45375, 47612]}, {"es": "¿Quinientos millones de qué?", "zh": "五亿零一百六十二万二千七百三十一是什么？", "t": [47612, 49888]}, {"es": "-volvió a preguntar el principito, que nunca en su vida había renunciado a una pregunta una vez que la había formulado.", "zh": "小王子又问了一遍，他一生从没放弃过自己提出的问题。", "t": [49888, 55438]}]}, {"id": "ch13p02", "audio": true, "sents": [{"es": "El hombre de negocios levantó la cabeza:", "zh": "商人抬起头：", "t": [100, 2162]}]}, {"id": "ch13p03", "audio": true, "sents": [{"es": "-Desde hace cincuenta y cuatro años que habito este planeta, sólo me han molestado tres veces.", "zh": "五十四年来，我住在这颗星球上，只被打扰过三次。", "t": [100, 5888]}, {"es": "La primera, hace veintidós años, fue por un abejorro que había caído aquí de Dios sabe dónde.", "zh": "二十二年前，一只黄蜂不慎坠落在此，不知从何而来。", "t": [5888, 11738]}, {"es": "Hacía un ruido insoportable y me hizo cometer cuatro errores en una suma.", "zh": "那声音震耳欲聋，让我在加法中犯了四个错误。", "t": [11738, 16512]}, {"es": "La segunda vez por una crisis de reumatismo, hace once años.", "zh": "第二次，因风湿病发作，距今已十一年。", "t": [16512, 20038]}]}, {"id": "ch13p04", "audio": true, "sents": [{"es": "Yo no hago ningún ejercicio, pues no tengo tiempo de callejear.", "zh": "我从不锻炼，因为我没有时间闲逛。", "t": [100, 4362]}, {"es": "Soy un hombre serio.", "zh": "我是个严肃的人。", "t": [4362, 6512]}, {"es": "Y la tercera vez…", "zh": "那第三次……", "t": [6512, 7662]}, {"es": "¡la tercera vez es ésta!", "zh": "这是第三次了！", "t": [7662, 9938]}, {"es": "Decía, pues, quinientos un millones…", "zh": "五百一千万…", "t": [9938, 12212]}, {"es": "-¿Millones de qué?", "zh": "五亿零一百六十二万二千七百三十一是什么？", "t": [12212, 13000]}]}, {"id": "ch13p05", "audio": true, "sents": [{"es": "El hombre de negocios comprendió que no tenía ninguna esperanza de que lo dejaran en paz.", "zh": "商人明白，他休想再得到安宁了。", "t": [100, 4300]}]}, {"id": "ch13p06", "audio": true, "sents": [{"es": "-Millones de esas pequeñas cosas que algunas veces se ven en el cielo.", "zh": "亿万种那些偶尔在天空中可见的小东西。", "t": [100, 4625]}, {"es": "-¿Moscas?", "zh": "苍蝇吗？", "t": [4625, 6212]}, {"es": "-¡No, cositas que brillan!", "zh": "不是，那些闪耀的小东西。", "t": [6212, 8500]}, {"es": "-¿Abejas?", "zh": "蜜蜂吗？", "t": [8500, 9000]}]}, {"id": "ch13p07", "audio": true, "sents": [{"es": "-No.", "zh": "不。", "t": [100, 1450]}, {"es": "Unas cositas doradas que hacen desvariar a los holgazanes.", "zh": "金色的微粒，令懒散者神魂颠倒。", "t": [1450, 5550]}, {"es": "¡Yo soy un hombre serio y no tengo tiempo de desvariar!", "zh": "我是个严肃的人，没时间胡思乱想。", "t": [5550, 9288]}, {"es": "-¡Ah!", "zh": "啊！", "t": [9288, 10550]}, {"es": "¿Estrellas?", "zh": "星星？", "t": [10550, 11212]}]}, {"id": "ch13p08", "audio": true, "sents": [{"es": "-Eso es.", "zh": "这便是了。", "t": [100, 1662]}, {"es": "Estrellas.", "zh": "繁星", "t": [1662, 3400]}, {"es": "-¿Y qué haces tú con quinientos millones de estrellas?", "zh": "你用五亿颗星星做什么？", "t": [3400, 5875]}]}, {"id": "ch13p09", "audio": true, "sents": [{"es": "-Quinientos un millones seiscientos veintidós mil setecientos treinta y uno.", "zh": "五亿零一百六十二万二千七百三十一", "t": [100, 5075]}, {"es": "Yo soy un hombre serio y exacto.", "zh": "我是个严肃而精确的人。", "t": [5075, 7938]}, {"es": "-¿Y qué haces con esas estrellas?", "zh": "你用这些星星做什么？", "t": [7938, 10675]}, {"es": "-¿Que qué hago con ellas?", "zh": "我拿它们有何用？", "t": [10675, 11800]}]}, {"id": "ch13p10", "audio": true, "sents": [{"es": "-Sí.", "zh": "是的。", "t": [100, 338]}]}, {"id": "ch13p11", "audio": true, "sents": [{"es": "-Nada.", "zh": "没什么。", "t": [100, 1525]}, {"es": "Las poseo.", "zh": "我拥有它们。", "t": [1525, 3275]}, {"es": "-¿Que las estrellas son tuyas?", "zh": "这星星是你的吗？", "t": [3275, 4838]}]}, {"id": "ch13p12", "audio": true, "sents": [{"es": "-Sí.", "zh": "是的。", "t": [100, 338]}]}, {"id": "ch13p13", "audio": true, "sents": [{"es": "-Yo he visto un rey que…", "zh": "我曾见过一个国王……", "t": [100, 1450]}]}, {"id": "ch13p14", "audio": true, "sents": [{"es": "-Los reyes no poseen nada…", "zh": "国王们一无所有。", "t": [100, 2688]}, {"es": "Reinan.", "zh": "他笑了。", "t": [2688, 4238]}, {"es": "Es muy diferente.", "zh": "大不相同。", "t": [4238, 6200]}, {"es": "-¿Y de qué te sirve poseer las estrellas?", "zh": "这星星对你有何用？", "t": [6200, 8338]}]}, {"id": "ch13p15", "audio": true, "sents": [{"es": "-Me sirve para ser rico.", "zh": "这使我变得富有。", "t": [100, 2488]}, {"es": "-¿Y de qué te sirve ser rico?", "zh": "那财富对你又有什么用呢？", "t": [2488, 3937]}]}, {"id": "ch13p16", "audio": true, "sents": [{"es": "-Me sirve para comprar más estrellas si alguien las descubre.", "zh": "若有人发现新的星星，我便可以用它们来购买更多。", "t": [100, 3137]}]}, {"id": "ch13p17", "audio": true, "sents": [{"es": "\"Este, se dijo a sí mismo el principito, razona poco más o menos como mi borracho\".", "zh": "这，小王子自言自语道，他的推理方法跟我见过的那个酒鬼差不多。", "t": [100, 4400]}]}, {"id": "ch13p18", "audio": true, "sents": [{"es": "No obstante le siguió preguntando: -¿Y cómo es posible poseer estrellas?", "zh": "然而他继续追问：“那么，如何才能拥有星星呢？”", "t": [100, 5062]}, {"es": "-¿De quién son las estrellas?", "zh": "这星星是谁的？", "t": [5062, 7600]}, {"es": "-contestó punzante el hombre de negocios.", "zh": "商人尖锐地回应。", "t": [7600, 9688]}]}, {"id": "ch13p19", "audio": true, "sents": [{"es": "-No sé…", "zh": "我不知道…", "t": [100, 1650]}, {"es": "De nadie.", "zh": "无人所有。", "t": [1650, 2237]}]}, {"id": "ch13p20", "audio": true, "sents": [{"es": "-Entonces son mías, puesto que he sido el primero a quien se le ha ocurrido la idea.", "zh": "那它们便属于我了，因为我是第一个想到要拥有它们的人。", "t": [100, 5075]}, {"es": "-¿Y eso basta?", "zh": "这还不够吗？", "t": [5075, 5862]}]}, {"id": "ch13p21", "audio": true, "sents": [{"es": "-Naturalmente.", "zh": "当然。", "t": [100, 2012]}, {"es": "Si te encuentras un diamante que nadie reclama, el diamante es tuyo.", "zh": "若你发现一颗无人认领的钻石，那钻石便归你了。", "t": [2012, 6638]}, {"es": "Si encontraras una isla que a nadie pertenece, la isla es tuya.", "zh": "若你发现一座无人之岛，那岛便属于你。", "t": [6638, 11200]}, {"es": "Si eres el primero en tener una idea y la haces patentar, nadie puede aprovecharla: es tuya.", "zh": "若你是第一个提出想法并将其申请专利的人，无人能从中获利：那想法属于你。", "t": [11200, 17250]}, {"es": "Las estrellas son mías, puesto que nadie, antes que yo, ha pensado en poseerlas.", "zh": "星星是我的，因为在我之前，没有人想过要拥有它们。", "t": [17250, 21450]}]}, {"id": "ch13p22", "audio": true, "sents": [{"es": "-Eso es verdad -dijo el principito- ¿y qué haces con ellas?", "zh": "这倒是真的——小王子说——你拿它们有何用？", "t": [100, 3263]}]}, {"id": "ch13p23", "audio": true, "sents": [{"es": "-Las administro.", "zh": "我管理着。", "t": [100, 2012]}, {"es": "Las cuento y las recuento una y otra vez -contestó el hombre de negocios-.", "zh": "我数它们，一次又一次地数它们。", "t": [2012, 6775]}, {"es": "Es algo difícil.", "zh": "这颇为不易。", "t": [6775, 8688]}, {"es": "¡Pero yo soy un hombre serio!", "zh": "但我是个严肃的人！", "t": [8688, 10188]}]}, {"id": "ch13p24", "audio": true, "sents": [{"es": "El principito no quedó del todo satisfecho.", "zh": "小王子并不完全满意。", "t": [100, 2412]}]}, {"id": "ch13p25", "audio": true, "sents": [{"es": "-Si yo tengo una bufanda, puedo ponérmela al cuello y llevármela.", "zh": "若我拥有一条围巾，我可以围在脖子上带走。", "t": [100, 4612]}, {"es": "Si soy dueño de una flor, puedo cortarla y llevármela también.", "zh": "若我拥有这朵花，便能摘下它带走。", "t": [4612, 9088]}, {"es": "¡Pero tú no puedes llevarte las estrellas!", "zh": "但你无法带走星星。", "t": [9088, 11113]}]}, {"id": "ch13p26", "audio": true, "sents": [{"es": "-Pero puedo colocarlas en un banco.", "zh": "但我可以把它们存入银行。", "t": [100, 2825]}, {"es": "-¿Qué quiere decir eso?", "zh": "这究竟是什么意思？", "t": [2825, 3938]}]}, {"id": "ch13p27", "audio": true, "sents": [{"es": "-Quiere decir que escribo en un papel el número de estrellas que tengo y guardo bajo llave en un cajón ese papel.", "zh": "我在一张纸上写下我拥有的星星数目，然后把那张纸锁进抽屉里。", "t": [100, 6338]}, {"es": "-¿Y eso es todo?", "zh": "这便是全部了。", "t": [6338, 8162]}, {"es": "-¡Es suficiente!", "zh": "这便足够了。", "t": [8162, 9024]}]}, {"id": "ch13p28", "audio": true, "sents": [{"es": "\"Es divertido\", pensó el principito.", "zh": "觉得挺有趣的，小王子心想。", "t": [100, 3025]}, {"es": "\"Es incluso bastante poético.", "zh": "这倒挺有诗意的。", "t": [3025, 5775]}, {"es": "Pero no es muy serio\".", "zh": "但他并不十分认真。", "t": [5775, 6913]}]}, {"id": "ch13p29", "audio": true, "sents": [{"es": "El principito tenía sobre las cosas serias ideas muy diferentes de las ideas de las personas mayores.", "zh": "小王子对严肃事物的看法与大人截然不同。", "t": [100, 5162]}]}, {"id": "ch13p30", "audio": true, "sents": [{"es": "-Yo -dijo aún- tengo una flor a la que riego todos los días; poseo tres volcanes a los que deshollino todas las semanas, pues también me ocupo del que está extinguido; nunca se sabe lo que puede ocurrir.", "zh": "我每天都给那朵花浇水；我拥有三座火山，每周都要清理，连那座熄灭的火山也不例外，因为世事难料。", "t": [100, 12038]}, {"es": "Es útil, pues, para mis volcanes y para mi flor que yo las posea.", "zh": "对我火山和我的花来说，拥有它们是有益的。", "t": [12038, 16500]}, {"es": "Pero tú, tú no eres nada útil para las estrellas…", "zh": "但你，你对于星星毫无用处……", "t": [16500, 19363]}]}, {"id": "ch13p31", "audio": true, "sents": [{"es": "El hombre de negocios abrió la boca, pero no encontró respuesta.", "zh": "商人张口结舌，无言以对。", "t": [100, 3575]}]}, {"id": "ch13p32", "audio": true, "sents": [{"es": "El principito abandonó aquel planeta.", "zh": "小王子离开了那颗星球。", "t": [100, 2076]}]}, {"id": "ch13p33", "audio": true, "sents": [{"es": "\"Las personas mayores, decididamente, son extraordinarias\", se decía a sí mismo con sencillez durante el viaje.", "zh": "大人们，无疑，是有些古怪，他简单地在旅途中自言自语。", "t": [100, 6112]}]}]}, {"id": "ch14", "title_es": "Capítulo 14", "title_zh": "第 14 章", "paras": [{"id": "ch14p00", "audio": true, "sents": [{"es": "El quinto planeta era muy curioso.", "zh": "第五颗星球颇为奇特。", "t": [100, 3075]}, {"es": "Era el más pequeño de todos, pues apenas cabían en él un farol y el farolero que lo habitaba.", "zh": "那是最小的一颗，里面仅能容纳一盏路灯和住着它的点灯人。", "t": [3075, 8700]}, {"es": "El principito no lograba explicarse para qué servirían allí, en el cielo, en un planeta sin casas y sin población un farol y un farolero.", "zh": "小王子无法解释，在那片无屋无人的星球上，那盏路灯和点灯人究竟有何用。", "t": [8700, 16800]}, {"es": "Sin embargo, se dijo a sí mismo:", "zh": "然而，他对自己说：", "t": [16800, 18525]}]}, {"id": "ch14p01", "audio": true, "sents": [{"es": "\"Este hombre, quizás, es absurdo.", "zh": "这个人或许有些荒谬。", "t": [100, 3025]}, {"es": "Sin embargo, es menos absurdo que el rey, el vanidoso, el hombre de negocios y el bebedor.", "zh": "然而，他并不像国王、虚荣的人、商人、酒鬼那样荒谬。", "t": [3025, 8700]}, {"es": "Su trabajo, al menos, tiene sentido.", "zh": "他的工作，至少，是有意义的。", "t": [8700, 11700]}, {"es": "Cuando enciende su farol, es igual que si hiciera nacer una estrella más o una flor y cuando lo apaga hace dormir a la flor o a la estrella.", "zh": "当他点亮路灯，仿佛是让一颗新星或一朵鲜花诞生；而他熄灭它，则是让花朵和星星进入梦乡。", "t": [11700, 19538]}, {"es": "Es una ocupación muy bonita y por ser bonita es verdaderamente útil\".", "zh": "这是一份美好的差事，因其美好，实属有益。", "t": [19538, 23224]}]}, {"id": "ch14p02", "audio": true, "sents": [{"es": "Cuando llegó al planeta saludó respetuosamente al farolero: -¡Buenos días!", "zh": "他抵达星球时，恭敬地向点灯人行礼：“早上好！”", "t": [100, 4962]}, {"es": "¿Por qué acabas de apagar tu farol?", "zh": "你为何刚刚熄灭了你的路灯？", "t": [4962, 6738]}]}, {"id": "ch14p03", "audio": true, "sents": [{"es": "-Es la consigna -respondió el farolero-.", "zh": "这是规定——点灯人答道。", "t": [100, 3450]}, {"es": "¡Buenos días!", "zh": "早上好！", "t": [3450, 5300]}, {"es": "-¿Y qué es la consigna?", "zh": "这是规定。", "t": [5300, 6462]}]}, {"id": "ch14p04", "audio": true, "sents": [{"es": "-Apagar mi farol.", "zh": "熄灭我的路灯。", "t": [100, 2012]}, {"es": "¡Buenas noches!", "zh": "晚安！", "t": [2012, 3962]}, {"es": "Y encendió el farol.", "zh": "他点亮了路灯。", "t": [3962, 6075]}, {"es": "-¿Y por qué acabas de volver a encenderlo?", "zh": "你为何又把它点亮了？", "t": [6075, 8000]}]}, {"id": "ch14p05", "audio": true, "sents": [{"es": "-Es la consigna.", "zh": "这是规定。", "t": [100, 1012]}]}, {"id": "ch14p06", "audio": true, "sents": [{"es": "-No lo comprendo -dijo el principito.", "zh": "我不懂——小王子说。", "t": [100, 2050]}]}, {"id": "ch14p07", "audio": true, "sents": [{"es": "-No hay nada que comprender -dijo el farolero-.", "zh": "“没什么好理解的。”点灯人说。", "t": [100, 3388]}, {"es": "La consigna es la consigna.", "zh": "规定就是规定。", "t": [3388, 5938]}, {"es": "¡Buenos días!", "zh": "早上好！", "t": [5938, 6762]}]}, {"id": "ch14p08", "audio": true, "sents": [{"es": "Y apagó su farol.", "zh": "他熄灭了路灯。", "t": [100, 1163]}]}, {"id": "ch14p09", "audio": true, "sents": [{"es": "Luego se enjugó la frente con un pañuelo de cuadros rojos.", "zh": "然后，他用手帕擦拭着额头。", "t": [100, 3263]}]}, {"id": "ch14p10", "audio": true, "sents": [{"es": "-Mi trabajo es algo terrible.", "zh": "我的工作实在可怕。", "t": [100, 2662]}, {"es": "En otros tiempos era razonable; apagaba el farol por la mañana y lo encendía por la tarde.", "zh": "那时，熄灯和点灯的规定还合乎情理。", "t": [2662, 8550]}, {"es": "Tenía el resto del día para reposar y el resto de la noche para dormir.", "zh": "白天我得以休息，夜晚我得以安眠。", "t": [8550, 13138]}, {"es": "-¿Y luego cambiaron la consigna?", "zh": "然后，规定又改了？", "t": [13138, 14750]}]}, {"id": "ch14p11", "audio": true, "sents": [{"es": "-Ese es el drama, que la consigna no ha cambiado -dijo el farolero-.", "zh": "这是悲剧，规定并未改变——点灯人说。", "t": [100, 4925]}, {"es": "El planeta gira cada vez más de prisa de año en año y la consigna sigue siendo la misma.", "zh": "星球逐年转得越来越快，而规定依旧如故。", "t": [4925, 10412]}, {"es": "-¿Y entonces?", "zh": "那么，接下来呢？", "t": [10412, 12162]}, {"es": "-dijo el principito.", "zh": "小王子说。", "t": [12162, 13250]}]}, {"id": "ch14p12", "audio": true, "sents": [{"es": "-Como el planeta da ahora una vuelta completa cada minuto, yo no tengo un segundo de reposo.", "zh": "如今这颗星球转一圈只需一分钟，我连一秒钟的休息时间都没有。", "t": [100, 5762]}, {"es": "Enciendo y apago una vez por minuto.", "zh": "每分钟点亮一次，熄灭一次。", "t": [5762, 8825]}, {"es": "-¡Eso es raro!", "zh": "这真奇怪！", "t": [8825, 10650]}, {"es": "¡Los días sólo duran en tu tierra un minuto!", "zh": "在你们那片土地上，一天只持续一分钟。", "t": [10650, 12976]}]}, {"id": "ch14p13", "audio": true, "sents": [{"es": "-Esto no tiene nada de divertido -dijo el farolero-.", "zh": "这毫无乐趣可言——点灯人说道。", "t": [100, 3925]}, {"es": "Hace ya un mes que tú y yo estamos hablando.", "zh": "我们已交谈了一个月。", "t": [3925, 7150]}, {"es": "-¿Un mes?", "zh": "一个月了吗？", "t": [7150, 7638]}]}, {"id": "ch14p14", "audio": true, "sents": [{"es": "-Sí, treinta minutos.", "zh": "是的，三十分钟。", "t": [100, 2425]}, {"es": "¡Treinta días!", "zh": "三十天", "t": [2425, 4250]}, {"es": "¡Buenas noches!", "zh": "晚安！", "t": [4250, 5200]}]}, {"id": "ch14p15", "audio": true, "sents": [{"es": "Y volvió a encender su farol.", "zh": "他又点亮了路灯。", "t": [100, 1663]}]}, {"id": "ch14p16", "audio": true, "sents": [{"es": "El principito lo miró y le gustó este farolero que tan fielmente cumplía la consigna.", "zh": "小王子看着他，喜欢这个一丝不苟、恪守职责的点灯人。", "t": [100, 5225]}, {"es": "Recordó las puestas de sol que en otro tiempo iba a buscar arrastrando su silla.", "zh": "那时，他总是拖着椅子寻找日落。", "t": [5225, 10300]}, {"es": "Quiso ayudarle a su amigo.", "zh": "他想帮助他的朋友。", "t": [10300, 12825]}, {"es": "-¿Sabes?", "zh": "你知道吗？", "t": [12825, 14375]}, {"es": "Yo conozco un medio para que descanses cuando quieras…", "zh": "我知道一个让你想休息就能休息的办法……", "t": [14375, 17150]}]}, {"id": "ch14p17", "audio": true, "sents": [{"es": "-Yo quiero descansar siempre -dijo el farolero.", "zh": "我总想休息——点灯人说。", "t": [100, 2663]}]}, {"id": "ch14p18", "audio": true, "sents": [{"es": "Se puede ser a la vez fiel y perezoso.", "zh": "既忠诚又懒惰。", "t": [100, 2162]}]}, {"id": "ch14p19", "audio": true, "sents": [{"es": "El principito prosiguió:", "zh": "小王子继续说道：", "t": [100, 1388]}]}, {"id": "ch14p20", "audio": true, "sents": [{"es": "-Tu planeta es tan pequeño que puedes darle la vuelta en tres zancadas.", "zh": "你的星球如此之小，只需几步便可绕行一周。", "t": [100, 4475]}, {"es": "No tienes que hacer más que caminar muy lentamente para quedar siempre al sol.", "zh": "只需缓缓行走，便能始终沐浴在阳光下。", "t": [4475, 9238]}, {"es": "Cuando quieras descansar, caminarás…", "zh": "当你想休息时，就去散步吧……", "t": [9238, 11400]}, {"es": "y el día durará tanto tiempo cuanto quieras.", "zh": "你愿它持续多久，它就持续多久。", "t": [11400, 13562]}]}, {"id": "ch14p21", "audio": true, "sents": [{"es": "-Con eso no adelanto gran cosa -dijo el farolero-, lo que a mí me gusta en la vida es dormir.", "zh": "那对我而言并无大益——点灯人说，“生活中我最喜欢的是睡觉。”", "t": [100, 5062]}]}, {"id": "ch14p22", "audio": true, "sents": [{"es": "-No es una suerte -dijo el principito.", "zh": "这不是运气。", "t": [100, 2137]}]}, {"id": "ch14p23", "audio": true, "sents": [{"es": "-No, no es una suerte -replicó el farolero-.", "zh": "这不是运气。", "t": [100, 3475]}, {"es": "¡Buenos días!", "zh": "早上好！", "t": [3475, 4300]}]}, {"id": "ch14p24", "audio": true, "sents": [{"es": "Y apagó su farol.", "zh": "他熄灭了路灯。", "t": [100, 1163]}]}, {"id": "ch14p25", "audio": true, "sents": [{"es": "Mientras el principito proseguía su viaje, se iba diciendo para sí: \"Este sería despreciado por los otros, por el rey, por el vanidoso, por el bebedor, por el hombre de negocios.", "zh": "小王子继续他的旅程，自言自语道：“这个人会被其他人轻视，会被国王、虚荣的人、酒鬼、商人轻视。”", "t": [100, 10500]}, {"es": "Y, sin embargo, es el único que no me parece ridículo, quizás porque se ocupa de otra cosa y no de sí mismo.", "zh": "然而，他却是我唯一不觉得可笑的人，也许因为他关心的是别的事，而非自身。", "t": [10500, 17075]}, {"es": "Lanzó un suspiro de pena y continuó diciéndose:", "zh": "他叹了口气，继续自言自语。", "t": [17075, 19825]}]}, {"id": "ch14p26", "audio": true, "sents": [{"es": "\"Es el único de quien pude haberme hecho amigo.", "zh": "他是唯一我能成为朋友的人。", "t": [100, 3350]}, {"es": "Pero su planeta es demasiado pequeño y no hay lugar para dos…", "zh": "但他的星球太小，容不下两个人…", "t": [3350, 6587]}, {"es": "\"", "zh": "规定就是规定。", "t": [6587, 7087]}]}, {"id": "ch14p27", "audio": true, "sents": [{"es": "Lo que el principito no se atrevía a confesarse, era que la causa por la cual lamentaba no quedarse en este bendito planeta se debía a las mil cuatrocientas cuarenta puestas de sol que podría disfrutar cada veinticuatro horas.", "zh": "小王子不敢承认，他之所以不愿留在这个幸运的星球，是因为他每二十四小时就能欣赏到一千四百四十次日落。", "t": [100, 11263]}]}]}, {"id": "ch15", "title_es": "Capítulo 15", "title_zh": "第 15 章", "paras": [{"id": "ch15p00", "audio": true, "sents": [{"es": "El sexto planeta era diez veces más grande.", "zh": "第六颗星球大了十倍。", "t": [100, 3588]}, {"es": "Estaba habitado por un anciano que escribía grandes libros.", "zh": "住着一位老人，正撰写着巨著。", "t": [3588, 7625]}, {"es": "-¡Anda, un explorador!", "zh": "来了一位探险家！", "t": [7625, 10012]}, {"es": "-exclamó cuando divisó al principito.", "zh": "他惊呼，当瞥见小王子时。", "t": [10012, 12038]}]}, {"id": "ch15p01", "audio": true, "sents": [{"es": "Este se sentó sobre la mesa y reposó un poco.", "zh": "他坐在桌旁，稍作休息。", "t": [100, 3575]}, {"es": "¡Había viajado ya tanto!", "zh": "他已旅行了如此遥远！", "t": [3575, 5938]}, {"es": "-¿De dónde vienes tú?", "zh": "你从哪里来？", "t": [5938, 8062]}, {"es": "-le preguntó el anciano.", "zh": "老先生问他。", "t": [8062, 10288]}, {"es": "-¿Qué libro es ese tan grande?", "zh": "这是一本如此巨大的书？", "t": [10288, 12700]}, {"es": "-preguntó a su vez el principito-.", "zh": "小王子问道。", "t": [12700, 15400]}, {"es": "¿Qué hace usted aquí?", "zh": "您在此做什么？", "t": [15400, 16375]}]}, {"id": "ch15p02", "audio": true, "sents": [{"es": "-Soy geógrafo -dijo el anciano.", "zh": "我是地理学家——老人说道。", "t": [100, 2912]}, {"es": "-¿Y qué es un geógrafo?", "zh": "地理学家是做什么的？", "t": [2912, 4137]}]}, {"id": "ch15p03", "audio": true, "sents": [{"es": "-Es un sabio que sabe donde están los mares, los ríos, las ciudades, las montañas y los desiertos.", "zh": "这是一位通晓大海、江河、城市、山脉和沙漠所在地的智者。", "t": [100, 5513]}]}, {"id": "ch15p04", "audio": true, "sents": [{"es": "-Eso es muy interesante -dijo el principito-.", "zh": "这很有趣——小王子说。", "t": [100, 3525]}, {"es": "¡Y es un verdadero oficio!", "zh": "这是一份真正的职业！", "t": [3525, 5000]}]}, {"id": "ch15p05", "audio": true, "sents": [{"es": "Dirigió una mirada a su alrededor sobre el planeta del geógrafo; nunca había visto un planeta tan majestuoso.", "zh": "他环顾地理学家的星球，从未见过如此庄严的星球。", "t": [100, 6000]}]}, {"id": "ch15p06", "audio": true, "sents": [{"es": "-Es muy hermoso su planeta.", "zh": "他的星球非常美丽。", "t": [100, 2588]}, {"es": "¿Hay océanos aquí?", "zh": "这里有大洋吗？", "t": [2588, 3612]}]}, {"id": "ch15p07", "audio": true, "sents": [{"es": "-No puedo saberlo -dijo el geógrafo.", "zh": "我无法知道——地理学家说。", "t": [100, 3288]}, {"es": "-¡Ah!", "zh": "啊！", "t": [3288, 3462]}, {"es": "(El principito se sintió decepcionado).", "zh": "小王子感到失望。", "t": [3462, 6400]}, {"es": "¿Y montañas?", "zh": "有山脉吗？", "t": [6400, 7137]}]}, {"id": "ch15p08", "audio": true, "sents": [{"es": "-No puedo saberlo -repitió el geógrafo.", "zh": "我无法知道——地理学家重复道。", "t": [100, 3462]}, {"es": "-¿Y ciudades, ríos y desiertos?", "zh": "有城市、河流、沙漠吗？", "t": [3462, 5362]}]}, {"id": "ch15p09", "audio": true, "sents": [{"es": "-Tampoco puedo saberlo.", "zh": "我也无法知道。", "t": [100, 2338]}, {"es": "-¡Pero usted es geógrafo!", "zh": "但您是地理学家啊！", "t": [2338, 3676]}]}, {"id": "ch15p10", "audio": true, "sents": [{"es": "-Exactamente -dijo el geógrafo-, pero no soy explorador, ni tengo exploradores que me informen.", "zh": "地理学家说：“确切地说——他道——但我既非探险家，也没有探险家来向我汇报。”", "t": [100, 6075]}, {"es": "El geógrafo no puede estar de acá para allá contando las ciudades, los ríos, las montañas, los océanos y los desiertos; es demasiado importante para deambnlar por ahí.", "zh": "地理学家无法四处奔波去数点城市、河流、山脉、海洋和沙漠；他太过重要，不能随意闲逛。", "t": [6075, 15800]}, {"es": "Se queda en su despacho y allí recibe a los exploradores.", "zh": "他留在办公室，在那里接待探险家。", "t": [15800, 19850]}, {"es": "Les interroga y toma nota de sus informes.", "zh": "他询问并记录他们的报告。", "t": [19850, 23212]}, {"es": "Si los informes de alguno de ellos le parecen interesantes, manda hacer una investigación sobre la moralidad del explorador.", "zh": "若其中某份报告令他感兴趣，便下令对探险者的品德进行调查。", "t": [23212, 30538]}, {"es": "-¿Para qué?", "zh": "这究竟是为了什么？", "t": [30538, 30950]}]}, {"id": "ch15p11", "audio": true, "sents": [{"es": "-Un explorador que mintiera sería una catástrofe para los libros de geografía.", "zh": "一个撒谎的探险家会对地理学书籍造成灾难。", "t": [100, 5138]}, {"es": "Y también lo sería un explorador que bebiera demasiado.", "zh": "一个饮酒过度的探险家也会如此。", "t": [5138, 8975]}, {"es": "-¿Por qué?", "zh": "为什么？", "t": [8975, 10338]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [10338, 11537]}]}, {"id": "ch15p12", "audio": true, "sents": [{"es": "-Porque los borrachos ven doble y el geógrafo pondría dos montañas donde sólo habría una.", "zh": "酒鬼看东西总是重影，地理学家就会在只有一座山的地方记下两座。", "t": [100, 4600]}]}, {"id": "ch15p13", "audio": true, "sents": [{"es": "-Conozco a alguien -dijo el principito-, que sería un mal explorador.", "zh": "我认识一个人——小王子说——他会是个糟糕的探险家。", "t": [100, 3512]}]}, {"id": "ch15p14", "audio": true, "sents": [{"es": "-Es posible.", "zh": "这是可能的。", "t": [100, 1838]}, {"es": "Cuando se está convencído de que la moralidad del explorador es buena, se hace una investigación sobre su descubrimiento.", "zh": "当确信探险者的品德良好时，便对其发现进行调查研究。", "t": [1838, 7800]}, {"es": "-¿", "zh": "您怎么了？", "t": [7800, 8775]}, {"es": "Se va a ver?", "zh": "您会见到吗？", "t": [8775, 9474]}]}, {"id": "ch15p15", "audio": true, "sents": [{"es": "-No, eso sería demasiado complicado.", "zh": "这未免太复杂了。", "t": [100, 3125]}, {"es": "Se exige al explorador que suministre pruebas.", "zh": "探险家需提供证据。", "t": [3125, 6738]}, {"es": "Por ejemplo, si se trata del descubrimiento de una gran montaña, se le pide que traiga grandes piedras.", "zh": "例如，若是他发现了大山，便要求他带来大石头。", "t": [6738, 11988]}]}, {"id": "ch15p16", "audio": true, "sents": [{"es": "Súbitamente el geógrafo se sintió emocionado:", "zh": "地理学家突然激动起来：", "t": [100, 2626]}]}, {"id": "ch15p17", "audio": true, "sents": [{"es": "-Pero…", "zh": "然而…", "t": [100, 450]}, {"es": "¡tú vienes de muy lejos!", "zh": "你来自遥远之地。", "t": [450, 2688]}, {"es": "¡Tú eres un explorador!", "zh": "你是一位探险家！", "t": [2688, 4938]}, {"es": "Vas a describirme tu planeta.", "zh": "你将向我描述你的星球。", "t": [4938, 6550]}]}, {"id": "ch15p18", "audio": true, "sents": [{"es": "Y el geógrafo abriendo su regístro afiló su lápiz.", "zh": "地理学家打开登记册，削尖了铅笔。", "t": [100, 3875]}, {"es": "Los relatos de los exploradores se escriben primero con lápiz.", "zh": "探险家的故事先是用铅笔写下来的。", "t": [3875, 7063]}]}, {"id": "ch15p19", "audio": true, "sents": [{"es": "Se espera que el explorador presente sus pruebas para pasarlos a tinta.", "zh": "探险家需出示其证据，方可转为墨水记录。", "t": [100, 4825]}, {"es": "-¿Y bien?", "zh": "那么呢？", "t": [4825, 6250]}, {"es": "-interrogó el geógrafo.", "zh": "地理学家询问。", "t": [6250, 8575]}, {"es": "-¡Oh!", "zh": "啊！", "t": [8575, 9788]}, {"es": "Mi tierra -dijo el principito- no es interesante, todo es muy pequeño.", "zh": "我的星球——小王子说——实在无趣，一切都太小了。", "t": [9788, 14638]}, {"es": "Tengo tres volcanes, dos en actividad y uno extinguido; pero nunca se sabe…", "zh": "我有三座火山，两座活火山，一座熄灭了；但谁知道呢……", "t": [14638, 18888]}]}, {"id": "ch15p20", "audio": true, "sents": [{"es": "-No, nunca se sabe -dijo el geógrafo.", "zh": "是啊，世事难料——地理学家说。", "t": [100, 2188]}]}, {"id": "ch15p21", "audio": true, "sents": [{"es": "-Tengo también una flor.", "zh": "我也有朵花。", "t": [100, 1312]}]}, {"id": "ch15p22", "audio": true, "sents": [{"es": "-De las flores no tomamos nota.", "zh": "花卉不予记录。", "t": [100, 2812]}, {"es": "-¿Por qué?", "zh": "为什么？", "t": [2812, 4175]}, {"es": "¡Son lo más bonito!", "zh": "这是最美的东西！", "t": [4175, 5250]}]}, {"id": "ch15p23", "audio": true, "sents": [{"es": "-Porque las flores son efímeras.", "zh": "因为花儿是短暂的。", "t": [100, 2812]}, {"es": "-¿Qué significa \"efímera\"?", "zh": "“‘昙花一现’是什么意思？”", "t": [2812, 4100]}]}, {"id": "ch15p24", "audio": true, "sents": [{"es": "-Las geografías -dijo el geógrafo- son los libros más preciados e interesantes; nunca pasan de moda.", "zh": "地理书——地理学家说——“是所有书籍中最珍贵、最引人入胜的；它们永远不会过时。", "t": [100, 6900]}, {"es": "Es muy raro que una montaña cambie de sitio o que un océano quede sin agua.", "zh": "山移位或海洋干涸实属罕见。", "t": [6900, 11825]}, {"es": "Los geógrafos escribimos sobre cosas eternas.", "zh": "地理学家书写永恒之物。", "t": [11825, 14425]}]}, {"id": "ch15p25", "audio": true, "sents": [{"es": "-Pero los volcanes extinguidos pueden despertarse -interrumpió el principito-.", "zh": "但熄灭的火山也可能苏醒——小王子打断道。", "t": [100, 5012]}, {"es": "¿Qué significa \"efímera\"?", "zh": "“昙花一现”是什么意思？", "t": [5012, 6300]}]}, {"id": "ch15p26", "audio": true, "sents": [{"es": "-Que los volcanes estén o no en actividad es igual para nosotros.", "zh": "火山是否活跃，对我们来说并无二致。", "t": [100, 4325]}, {"es": "Lo interesante es la montaña que nunca cambia.", "zh": "那有趣的是永远不变的群山。", "t": [4325, 6725]}]}, {"id": "ch15p27", "audio": true, "sents": [{"es": "-Pero, ¿qué significa \"efímera\"?", "zh": "但“昙花一现”究竟是什么意思？", "t": [100, 2700]}, {"es": "-repitió el principito que en su vida había renunciado a una pregunta una vez formulada.", "zh": "小王子重复道，他一生中曾有一次放弃过一个问题。", "t": [2700, 7074]}]}, {"id": "ch15p28", "audio": true, "sents": [{"es": "-Significa que está amenazado de próxima desaparición.", "zh": "意味着它面临即将消失的威胁。", "t": [100, 3975]}, {"es": "-¿Mi flor está amenazada de desaparecer próximamente?", "zh": "我的花儿很快就要消失了。", "t": [3975, 6975]}]}, {"id": "ch15p29", "audio": true, "sents": [{"es": "-Indudablemente.", "zh": "毫无疑问。", "t": [100, 1050]}]}, {"id": "ch15p30", "audio": true, "sents": [{"es": "\"Mi flor as efímera -se dijo el principito- y no tiene más que cuatro espinas para defenderse contra el mundo.", "zh": "我的玫瑰是短暂的——小王子心想——而她只有四根刺来保护自己，对抗这个世界。", "t": [100, 6625]}, {"es": "¡Y la he dejado allá sola en mi casa!\" Por primera vez se arrepintió de haber dejado su planeta, pero bien pronto recobró su valor.", "zh": "我第一次为离开我的星球而感到后悔，但很快又振作起来。", "t": [6625, 15125]}, {"es": "-¿Qué me aconseja usted que visite ahora?", "zh": "您建议我接下来去哪里访问？", "t": [15125, 18150]}, {"es": "-preguntó.", "zh": "他问。", "t": [18150, 18688]}]}, {"id": "ch15p31", "audio": true, "sents": [{"es": "-La Tierra -le contestó el geógrafo-.", "zh": "地球——地理学家回答道。", "t": [100, 3162]}, {"es": "Tiene muy buena reputación…", "zh": "享有极高的声誉…", "t": [3162, 4713]}]}, {"id": "ch15p32", "audio": true, "sents": [{"es": "Y el principito partió pensando en su flor.", "zh": "小王子心中想着他的玫瑰，踏上了旅程。", "t": [100, 2313]}]}]}, {"id": "ch16", "title_es": "Capítulo 16", "title_zh": "第 16 章", "paras": [{"id": "ch16p00", "audio": true, "sents": [{"es": "El séptimo planeta fue, por consiguiente, la Tierra.", "zh": "第七颗星球便是地球。", "t": [100, 3788]}, {"es": "¡La Tierra no es un planeta cualquiera!", "zh": "地球并非普通行星。", "t": [3788, 6712]}, {"es": "Se cuentan en él ciento once reyes (sin olvidar, naturalmente, los reyes negros), siete mil geógrafos, novecientos mil hombres de negocios, siete millones y medio de borrachos, trescientos once millones de vanidosos, es decir, alrededor de dos mil millones de personas mayores.", "zh": "在这颗星球上，有一百一十一位国王（自然也包括黑人国王）、七千位地理学家、九百万商人、七百五十万酒徒、三亿一千一百万自恋者，也就是说，大约有二十亿个大人。", "t": [6712, 22012]}]}, {"id": "ch16p01", "audio": true, "sents": [{"es": "Para darles una idea de las dimensiones de la Tierra yo les diría que antes de la invención de la electricidad había que mantener sobre el conjunto de los seis continentes un verdadero ejército de cuatrocientos sesenta y dos mil quinientos once faroleros.", "zh": "为了让他们对地球的规模有个直观印象，我得告诉你们，在电发明之前，六大洲上得维持一支由四十六万二千五百一十一个提灯人组成的庞大军队。", "t": [100, 12000]}]}, {"id": "ch16p02", "audio": true, "sents": [{"es": "Vistos desde lejos, hacían un espléndido efecto.", "zh": "从远处望去，场面壮观。", "t": [100, 3862]}, {"es": "Los movimientos de este ejército estaban regulados como los de un ballet de ópera.", "zh": "这支军队的动作如同歌剧芭蕾般整齐。", "t": [3862, 8800]}, {"es": "Primero venía el turno de los faroleros de Nueva Zelandia y de Australia.", "zh": "新西兰和澳大利亚的提灯人率先登场。", "t": [8800, 13438]}, {"es": "Encendían sus faroles y se iban a dormir.", "zh": "点亮了路灯便去安睡。", "t": [13438, 16812]}, {"es": "Después tocaba el turno en la danza a los faroleros de China y Siberia, que a su vez se perdían entre bastidores.", "zh": "中国和西伯利亚的提灯人接着加入舞步，也隐没于幕后。", "t": [16812, 23662]}, {"es": "Luego seguían los faroleros de Rusia y la India, después los de Africa y Europa y finalmente, los de América del Sur y América del Norte.", "zh": "随后是俄罗斯和印度的提灯人，接着是非洲和欧洲的，最后是南美洲和北美洲的。", "t": [23662, 32200]}, {"es": "Nunca se equivocaban en su orden de entrada en escena.", "zh": "他们的进场顺序从未出错。", "t": [32200, 36000]}, {"es": "Era grandioso.", "zh": "宏伟壮观。", "t": [36000, 36863]}]}, {"id": "ch16p03", "audio": true, "sents": [{"es": "Solamente el farolero del único farol del polo norte y su colega del único farol del polo sur, llevaban una vida de ociosidad y descanso.", "zh": "北极那盏孤灯的守灯人和他南极的同伴，过着悠闲自在的生活。", "t": [100, 8225]}, {"es": "No trabajaban más que dos veces al año.", "zh": "他们一年只工作两次。", "t": [8225, 10425]}]}]}, {"id": "ch17", "title_es": "Capítulo 17", "title_zh": "第 17 章", "paras": [{"id": "ch17p00", "audio": true, "sents": [{"es": "Cuando se quiere ser ingenioso, sucede que se miente un poco.", "zh": "想卖弄聪明，不免会撒些小谎。", "t": [100, 4138]}, {"es": "No he sido muy honesto al hablar de los faroleros y corro el riesgo de dar una falsa idea de nuestro planeta a los que no lo conocen.", "zh": "我讲述点灯人的故事时，或许并未完全坦诚，险些给那些未曾踏足我们星球的人留下错误的印象。", "t": [4138, 11425]}, {"es": "Los hombres ocupan muy poco lugar sobre la Tierra.", "zh": "人在地球上所占之地甚微。", "t": [11425, 15000]}, {"es": "Si los dos mil millones de habitantes que la pueblan se pusieran de pie y un poco apretados, como en un mitin, cabrían fácilmente en una plaza de veinte millas de largo por veinte de ancho.", "zh": "二十亿居民若并肩站立，挤挤挨挨地如同集会一般，便能轻松地填满二十英里长、二十英里宽的广场。", "t": [15000, 25350]}, {"es": "La humanidad podría amontonarse sobre el más pequeño islote del Pacífico.", "zh": "人类可以挤满太平洋上最小的岛屿。", "t": [25350, 29100]}]}, {"id": "ch17p01", "audio": true, "sents": [{"es": "Las personas mayores no les creerán, seguramente, pues siempre se imaginan que ocupan mucho sitio.", "zh": "大人们肯定不会相信，因为他们总是想象自己占据了很大的地方。", "t": [100, 6350]}, {"es": "Se creen importantes como los baobabs.", "zh": "他们自以为重要，如同猴面包树那般。", "t": [6350, 9475]}, {"es": "Les dirán, pues, que hagan el cálculo; eso les gustará ya que adoran las cifras.", "zh": "他们便会说，让他们去计算吧；他们喜欢数字，这会让他们高兴。", "t": [9475, 14912]}, {"es": "Pero no es necesario que pierdan el tiempo inútïlmente, puesto que tienen confianza en mí.", "zh": "但无需他们徒劳无益地浪费时间，因为他们对我充满信心。", "t": [14912, 19187]}]}, {"id": "ch17p02", "audio": true, "sents": [{"es": "El principito, una vez que llegó a la Tierra, quedó sorprendido de no ver a nadie.", "zh": "小王子一到地球，惊讶地发现无人踪影。", "t": [100, 5200]}, {"es": "Tenía miedo de haberse equivocado de planeta, cuando un anillo de color de luna se revolvió en la arena.", "zh": "他害怕自己误闯了别的星球，当一轮月白色的圆环在沙地上蠕动时。", "t": [5200, 10600]}]}, {"id": "ch17p03", "audio": true, "sents": [{"es": "-¡Buenas noches!", "zh": "晚安！", "t": [100, 2050]}, {"es": "-dijo el principito.", "zh": "小王子说。", "t": [2050, 4125]}, {"es": "-¡Buenas noches!", "zh": "晚安。", "t": [4125, 6075]}, {"es": "-dijo la serpiente.", "zh": "蛇说。", "t": [6075, 8100]}, {"es": "-¿Sobre qué planeta he caído?", "zh": "我降落在了哪个星球上？", "t": [8100, 10550]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [10550, 11750]}]}, {"id": "ch17p04", "audio": true, "sents": [{"es": "-Sobre la Tierra, en Africa -respondió la serpiente.", "zh": "在非洲，蛇回答说。", "t": [100, 3888]}, {"es": "-¡Ah!", "zh": "哦！", "t": [3888, 5150]}, {"es": "¿Y no hay nadie sobre la Tierra?", "zh": "地球上难道无人迹？", "t": [5150, 6700]}]}, {"id": "ch17p05", "audio": true, "sents": [{"es": "-Esto es el desierto.", "zh": "这是沙漠。", "t": [100, 2338]}, {"es": "En los desiertos no hay nadie.", "zh": "沙漠中无人迹。", "t": [2338, 4925]}, {"es": "La Tierra es muy grande -dijo la serpiente.", "zh": "地球太广大了——蛇说。", "t": [4925, 7275]}]}, {"id": "ch17p06", "audio": true, "sents": [{"es": "El principito se sentó en una piedra y elevó los ojos al cielo.", "zh": "小王子坐在一块石头上，仰望天空。", "t": [100, 3363]}]}, {"id": "ch17p07", "audio": true, "sents": [{"es": "-Yo me pregunto -dijo- si las estrellas están encendidas para que cada cual pueda un día encontrar la suya.", "zh": "我暗自思忖——他说道——星星是否是为了让每个人有一天都能找到属于自己的那颗。", "t": [100, 6275]}, {"es": "Mira mi planeta; está precisamente encima de nosotros…", "zh": "看我的星球；它正悬在我们头顶上方……", "t": [6275, 10500]}, {"es": "Pero…", "zh": "然而…", "t": [10500, 10788]}, {"es": "¡qué lejos está!", "zh": "多么遥远啊！", "t": [10788, 11600]}]}, {"id": "ch17p08", "audio": true, "sents": [{"es": "-Es muy bella -dijo la serpiente-.", "zh": "它说：“真美。”", "t": [100, 3038]}, {"es": "¿Y qué vienes tú a hacer aquí?", "zh": "你为何来到这里？", "t": [3038, 4500]}]}, {"id": "ch17p09", "audio": true, "sents": [{"es": "-Tengo problemas con una flor -dijo el principito.", "zh": "我与一朵花儿闹了别扭——小王子说。", "t": [100, 3688]}, {"es": "-¡Ah!", "zh": "哦！", "t": [3688, 3813]}]}, {"id": "ch17p10", "audio": true, "sents": [{"es": "Y se callaron.", "zh": "他们沉默了。", "t": [100, 1862]}, {"es": "-¿Dónde están los hombres?", "zh": "人类在何方？", "t": [1862, 4188]}, {"es": "-prosiguió por fin el principito.", "zh": "小王子终于继续前行。", "t": [4188, 6850]}, {"es": "Se está un poco solo en el desierto…", "zh": "在沙漠中，有点孤单。", "t": [6850, 8824]}]}, {"id": "ch17p11", "audio": true, "sents": [{"es": "-También se está solo donde los hombres -afirmó la serpiente.", "zh": "蛇说：“即便在人群中，也依然孤独。”", "t": [100, 3213]}]}, {"id": "ch17p12", "audio": true, "sents": [{"es": "El principito la miró largo rato y le dijo: -Eres un bicho raro, delgado como un dedo…", "zh": "小王子凝视了她很久，说道：“你真是个奇怪的动物，瘦得像根手指……”", "t": [100, 4913]}]}, {"id": "ch17p13", "audio": true, "sents": [{"es": "-Pero soy más poderoso que el dedo de un rey -le interrumpió la serpiente.", "zh": "但我比国王的指头更有力量——蛇打断了他的话。", "t": [100, 3950]}]}, {"id": "ch17p14", "audio": true, "sents": [{"es": "El principito sonrió:", "zh": "小王子微笑了。", "t": [100, 1363]}]}, {"id": "ch17p15", "audio": true, "sents": [{"es": "-No me pareces muy poderoso…", "zh": "你似乎并不强大。", "t": [100, 1612]}, {"es": "ni siquiera tienes patas…", "zh": "连腿都没有…", "t": [1612, 3225]}, {"es": "ni tan siquiera puedes viajar…", "zh": "你甚至无法旅行…", "t": [3225, 4688]}]}, {"id": "ch17p16", "audio": true, "sents": [{"es": "-Puedo llevarte más lejos que un navío -dijo la serpiente.", "zh": "我能带你走得更远，比船还要遥远——蛇说。", "t": [100, 3274]}]}, {"id": "ch17p17", "audio": true, "sents": [{"es": "Se enroscó alrededor del tobillo del principito como un brazalete de oro.", "zh": "它绕着小王子的脚踝盘旋，宛如一枚金镯。", "t": [100, 3837]}]}, {"id": "ch17p18", "audio": true, "sents": [{"es": "-Al que yo toco, le hago volver a la tierra de donde salió.", "zh": "我所触及者，便使其重返故乡。", "t": [100, 4112]}, {"es": "Pero tú eres puro y vienes de una estrella…", "zh": "但你纯净，来自一颗星星…", "t": [4112, 6324]}]}, {"id": "ch17p19", "audio": true, "sents": [{"es": "El principito no respondió.", "zh": "小王子并未作答。", "t": [100, 1625]}]}, {"id": "ch17p20", "audio": true, "sents": [{"es": "-Me das lástima, tan débil sobre esta tierra de granito.", "zh": "在这花岗岩构成的地球上，你如此弱小，令人怜悯。", "t": [100, 4225]}, {"es": "Si algún día echas mucho de menos tu planeta, puedo ayudarte.", "zh": "若你某日深切思念你的星球，我能助你一臂之力。", "t": [4225, 8425]}, {"es": "Puedo…", "zh": "我能…", "t": [8425, 9012]}, {"es": "-¡Oh!", "zh": "哦！", "t": [9012, 10138]}, {"es": "-dijo el principito-.", "zh": "小王子说。", "t": [10138, 12212]}, {"es": "Te he comprendido.", "zh": "你懂我了。", "t": [12212, 14150]}, {"es": "Pero ¿por qué hablas con enigmas?", "zh": "但你为何总是言辞如谜？", "t": [14150, 15812]}]}, {"id": "ch17p21", "audio": true, "sents": [{"es": "-Yo los resuelvo todos -dijo la serpiente.", "zh": "我解开所有的谜——蛇说。", "t": [100, 2450]}]}, {"id": "ch17p22", "audio": true, "sents": [{"es": "Y se callaron.", "zh": "他们沉默了。", "t": [100, 875]}]}]}, {"id": "ch18", "title_es": "Capítulo 18", "title_zh": "第 18 章", "paras": [{"id": "ch18p00", "audio": true, "sents": [{"es": "El principito atravesó el desierto en el que sólo encontró una flor de tres pétalos, una flor de nada.", "zh": "小王子穿越沙漠，只发现一朵三瓣的花，一朵无足轻重的花。", "t": [100, 5350]}]}, {"id": "ch18p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "早上好！", "t": [100, 1950]}, {"es": "-dijo el principito.", "zh": "小王子说道。", "t": [1950, 4025]}, {"es": "-¡Buenos días!", "zh": "早上好！", "t": [4025, 5875]}, {"es": "-dijo la flor.", "zh": "花儿轻声说道。", "t": [5875, 7588]}, {"es": "-¿Dónde están los hombres?", "zh": "他们在何处？", "t": [7588, 9912]}, {"es": "-preguntó cortésmente el principito.", "zh": "小王子彬彬有礼地问道。", "t": [9912, 11825]}]}, {"id": "ch18p02", "audio": true, "sents": [{"es": "La flor, un día, había visto pasar una caravana.", "zh": "那朵花有一天见过一支商队经过。", "t": [100, 3988]}, {"es": "-¿Los hombres?", "zh": "人在哪儿？", "t": [3988, 5712]}, {"es": "No existen más que seis o siete, me parece.", "zh": "似乎只有六七个。", "t": [5712, 8175]}]}, {"id": "ch18p03", "audio": true, "sents": [{"es": "Los he visto hace ya años y nunca se sabe dónde encontrarlos.", "zh": "多年前我曾见过他们，却不知他们在何方。", "t": [100, 4400]}, {"es": "El viento los pasea.", "zh": "风儿带他们游玩。", "t": [4400, 6488]}, {"es": "Les faltan las raíces.", "zh": "它们缺少根茎。", "t": [6488, 8875]}, {"es": "Esto les molesta.", "zh": "这让他们感到烦恼。", "t": [8875, 9874]}]}, {"id": "ch18p04", "audio": true, "sents": [{"es": "-Adiós -dijo el principito.", "zh": "再见——小王子说。", "t": [100, 1650]}]}, {"id": "ch18p05", "audio": true, "sents": [{"es": "-Adiós -dijo la flor.", "zh": "再见——花儿说道。", "t": [100, 1350]}]}]}, {"id": "ch19", "title_es": "Capítulo 19", "title_zh": "第 19 章", "paras": [{"id": "ch19p00", "audio": true, "sents": [{"es": "El principito escaló hasta la cima de una alta montaña.", "zh": "小王子攀登至高山之巅。", "t": [100, 3950]}, {"es": "Las únicas montañas que él había conocido eran los tres volcanes que le llegaban a la rodilla.", "zh": "他只认识那些仅至膝盖的三座火山。", "t": [3950, 9512]}, {"es": "El volcán extinguido lo utilizaba como taburete.", "zh": "死火山成了他的小凳子。", "t": [9512, 13000]}, {"es": "\"Desde una montaña tan alta como ésta, se había dicho, podré ver todo el planeta y a todos los hombres…\" Pero no alcanzó a ver más que algunas puntas de rocas.", "zh": "从如此高的山峰，人们曾说，我能望见整个星球和所有人……然而他只能瞥见几块岩石的尖角。", "t": [13000, 22088]}]}, {"id": "ch19p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "您好。", "t": [100, 1950]}, {"es": "-exclamó el principito al acaso.", "zh": "小王子惊呼。", "t": [1950, 4725]}, {"es": "-¡Buenos días!", "zh": "您好。", "t": [4725, 6575]}, {"es": "¡Buenos días!", "zh": "您好。", "t": [6575, 8425]}, {"es": "¡Buenos días!", "zh": "您好！", "t": [8425, 10275]}, {"es": "-respondió el eco -¿Quién eres tú?", "zh": "回声答道：“你是谁？”", "t": [10275, 13125]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [13125, 15312]}, {"es": "-¿Quién eres tú?…", "zh": "你是谁呀？", "t": [15312, 17075]}, {"es": "¿Quién eres tú?…", "zh": "你是谁呀？", "t": [17075, 18838]}, {"es": "¿Quién eres tú?…", "zh": "你是谁呀？", "t": [18838, 19612]}, {"es": "-contestó el eco.", "zh": "回声应道。", "t": [19612, 20562]}]}, {"id": "ch19p02", "audio": true, "sents": [{"es": "-Sed mis amigos, estoy solo -dijo el principito.", "zh": "我的朋友们，我孤单一人——小王子说。", "t": [100, 2950]}]}, {"id": "ch19p03", "audio": true, "sents": [{"es": "-Estoy solo…", "zh": "我孤身一人…", "t": [100, 962]}, {"es": "estoy solo…", "zh": "我孤身一人…", "t": [962, 1950]}, {"es": "estoy solo…", "zh": "我孤身一人…", "t": [1950, 2912]}, {"es": "-repitió el eco.", "zh": "回声复述。", "t": [2912, 3900]}]}, {"id": "ch19p04", "audio": true, "sents": [{"es": "\"¡Qué planeta más raro!", "zh": "多么奇特的星球！", "t": [100, 2250]}, {"es": "-pensó entonces el principito-, es seco, puntiagudo y salado.", "zh": "干燥、尖利、带咸。", "t": [2250, 6500]}, {"es": "Y los hombres carecen de imaginación; no hacen más que repetir lo que se les dice…", "zh": "人们缺乏想象力；他们只是重复别人告诉他们的。", "t": [6500, 11725]}, {"es": "En mi tierra tenía una flor: hablaba siempre la primera…", "zh": "在我星球上，我有一朵花：她总是抢先开口……", "t": [11725, 14837]}, {"es": "\"", "zh": "这颗星球荒凉又孤单。", "t": [14837, 15337]}]}]}, {"id": "ch20", "title_es": "Capítulo 20", "title_zh": "第 20 章", "paras": [{"id": "ch20p00", "audio": true, "sents": [{"es": "Pero sucedió que el principito, habiendo atravesado arenas, rocas y nieves, descubrió finalmente un camino.", "zh": "小王子穿越沙海、岩石与冰雪，终于找到了一条道路。", "t": [100, 7138]}, {"es": "Y los caminos llevan siempre a la morada de los hombres.", "zh": "道路始终通向人类的住所。", "t": [7138, 9838]}]}, {"id": "ch20p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "你好吗？", "t": [100, 1950]}, {"es": "-dijo.", "zh": "他说道。", "t": [1950, 2338]}]}, {"id": "ch20p02", "audio": true, "sents": [{"es": "Era un jardín cuajado de rosas.", "zh": "这是一个满是玫瑰的花园。", "t": [100, 2925]}, {"es": "-¡Buenos días!", "zh": "早安。", "t": [2925, 4775]}, {"es": "-dijeran las rosas.", "zh": "玫瑰花们说。", "t": [4775, 5887]}]}, {"id": "ch20p03", "audio": true, "sents": [{"es": "El principito las miró.", "zh": "小王子凝视着她们。", "t": [100, 2338]}, {"es": "¡Todas se parecían tanto a su flor!", "zh": "她们都如此像他的那朵花。", "t": [2338, 5100]}, {"es": "-¿Quiénes son ustedes?", "zh": "你们是何人？", "t": [5100, 7288]}, {"es": "-les preguntó estupefacto.", "zh": "他惊愕地问道。", "t": [7288, 8788]}]}, {"id": "ch20p04", "audio": true, "sents": [{"es": "-Somos las rosas -respondieron éstas.", "zh": "我们是玫瑰花——她们答道。", "t": [100, 3462]}, {"es": "-¡Ah!", "zh": "啊！", "t": [3462, 4725]}, {"es": "-exclamó el principito.", "zh": "小王子惊呼。", "t": [4725, 6024]}]}, {"id": "ch20p05", "audio": true, "sents": [{"es": "Y se sintió muy desgraciado.", "zh": "他感到非常不幸。", "t": [100, 2650]}, {"es": "Su flor le había dicho que era la única de su especie en todo el universo.", "zh": "他的花儿曾告诉他，她是宇宙间独一无二的存在。", "t": [2650, 7312]}, {"es": "¡Y ahora t.enía ante sus ojos más de cinco mil.todas semejantes, en un solo jardín!", "zh": "在这座花园里，他眼前有五千朵玫瑰，个个相像。", "t": [7312, 12175]}]}, {"id": "ch20p06", "audio": true, "sents": [{"es": "Si ella viese todo esto, se decía el principito, se sentiría vejada, tosería muchísimo y simularía morir para escapar al ridículo.", "zh": "若她看到这一切，小王子心想，她会感到羞辱，会剧烈地咳嗽，装作要死去，以逃避尴尬。", "t": [100, 8138]}, {"es": "Y yo tendría que fingirle cuidados, pues sería capaz de dejarse morir verdaderamente para humillarme a mí también…", "zh": "我便得假装呵护她，因为她甚至能真的死去，以羞辱我。", "t": [8138, 14037]}, {"es": "\"", "zh": "那朵花，她什么也不懂。", "t": [14037, 14537]}]}, {"id": "ch20p07", "audio": true, "sents": [{"es": "Y luego continuó diciéndose: \"Me creía rico con una flor única y resulta que no tengo más que una rosa ordinaria.", "zh": "我原以为拥有一朵独一无二的花，便觉得富足，谁知她只是一朵普通的玫瑰。", "t": [100, 7338]}, {"es": "Eso y mis tres volcanes que apenas me llegan a la rodilla y uno de Ios cuales acaso esté extinguido para siempre.", "zh": "那三座仅至膝盖的火山，其中一座或许永远熄灭。", "t": [7338, 14450]}, {"es": "Realmente no soy un gran príncipe…", "zh": "我其实并非一位伟大的王子…", "t": [14450, 17388]}, {"es": "\" Y echándose sobre la hierba, el principito lloró.", "zh": "小王子扑倒在草地上，失声痛哭。", "t": [17388, 19950]}]}]}, {"id": "ch21", "title_es": "Capítulo 21", "title_zh": "第 21 章", "paras": [{"id": "ch21p00", "audio": true, "sents": [{"es": "Entonces apareció el zorro:", "zh": "于是，出现了狐狸。", "t": [100, 1713]}]}, {"id": "ch21p01", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "你好。", "t": [100, 1950]}, {"es": "-dijo el zorro.", "zh": "狐狸说。", "t": [1950, 3788]}, {"es": "-¡Buenos días!", "zh": "你好。", "t": [3788, 5638]}, {"es": "-respondió cortésmente el principito que se volvió pero no vío nada.", "zh": "小王子彬彬有礼地回答，他转过身，却看不见有什么东西。", "t": [5638, 9038]}]}, {"id": "ch21p02", "audio": true, "sents": [{"es": "-Estoy aquí, bajo el manzano -díjo la voz.", "zh": "我在苹果树下，那声音说。", "t": [100, 3525]}, {"es": "-¿Quién eres tú?", "zh": "你是谁？", "t": [3525, 5288]}, {"es": "-preguntó el principito-.", "zh": "小王子问道。", "t": [5288, 7475]}, {"es": "¡Qué bonito eres!", "zh": "你真美。", "t": [7475, 8425]}]}, {"id": "ch21p03", "audio": true, "sents": [{"es": "-Soy un zorro -dijo el zorro.", "zh": "我是狐狸——狐狸说。", "t": [100, 1725]}]}, {"id": "ch21p04", "audio": true, "sents": [{"es": "-Ven a jugar conmigo -le propuso el principito-, ¡estoy tan triste!", "zh": "小王子提议道：“来和我一起玩吧，我如此难过！”", "t": [100, 3537]}]}, {"id": "ch21p05", "audio": true, "sents": [{"es": "-No puedo jugar contigo -dijo el zorro-, no estoy domesticado.", "zh": "我不能和你玩——狐狸说，我还没有被驯养。", "t": [100, 4375]}, {"es": "-¡Ah, perdón!", "zh": "哦，对不起！", "t": [4375, 6075]}, {"es": "-dijo el principito.", "zh": "小王子说。", "t": [6075, 7163]}]}, {"id": "ch21p06", "audio": true, "sents": [{"es": "Pero después de una breve reflexión, añadió: -¿Qué significa \"domesticar\"?", "zh": "但稍作沉思后，他又补充道：“驯养究竟意味着什么？”", "t": [100, 4200]}]}, {"id": "ch21p07", "audio": true, "sents": [{"es": "-Tú no eres de aquí -dijo el zorro- ¿qué buscas?", "zh": "你不是这里的人——狐狸说，你在寻找什么？", "t": [100, 2650]}]}, {"id": "ch21p08", "audio": true, "sents": [{"es": "-Busco a los hombres -le respondió el principito-.", "zh": "我在寻找人类。", "t": [100, 3700]}, {"es": "¿Qué significa \"domesticar\"?", "zh": "驯养究竟是什么意思？", "t": [3700, 5113]}]}, {"id": "ch21p09", "audio": true, "sents": [{"es": "-Los hombres -dijo el zorro- tienen escopetas y cazan.", "zh": "人们——狐狸说——“有枪，他们打猎。”", "t": [100, 4112]}, {"es": "¡Es muy molesto!", "zh": "实在讨厌！", "t": [4112, 5988]}, {"es": "Pero también crían gallinas.", "zh": "可他们也养鸡。", "t": [5988, 8525]}, {"es": "Es lo único que les interesa.", "zh": "这便是他们唯一感兴趣的事。", "t": [8525, 11125]}, {"es": "¿Tú buscas gallinas?", "zh": "你寻找母鸡吗？", "t": [11125, 12250]}]}, {"id": "ch21p10", "audio": true, "sents": [{"es": "-No -díjo el principito-.", "zh": "小王子说：“不——”", "t": [100, 2500]}, {"es": "Busco amigos.", "zh": "我在寻找朋友。", "t": [2500, 4412]}, {"es": "¿Qué significa \"domesticar\"?", "zh": "驯养究竟是什么意思？", "t": [4412, 6800]}, {"es": "-volvió a preguntar el principito.", "zh": "小王子又问。", "t": [6800, 8463]}]}, {"id": "ch21p11", "audio": true, "sents": [{"es": "-Es una cosa ya olvidada -dijo el zorro-, significa \"crear vínculos…", "zh": "这是一件被人遗忘的事——狐狸说——“意味着建立联系……”", "t": [100, 5100]}, {"es": "\" -¿Crear vínculos?", "zh": "建立联系？", "t": [5100, 6062]}]}, {"id": "ch21p12", "audio": true, "sents": [{"es": "-Efectivamente, verás -dijo el zorro-.", "zh": "的确如此——狐狸说。", "t": [100, 3175]}, {"es": "Tú no eres para mí todavía más que un muchachito igual a otros cien mil muchachitos y no te necesito para nada.", "zh": "你对我而言，不过是一个和其他成千上万男孩无异的孩童，我对你并无任何需要。", "t": [3175, 9675]}, {"es": "Tampoco tú tienes necesidad de mí y no soy para ti más que un zorro entre otros cien mil zorros semejantes.", "zh": "你也不需要我，对我而言，我不过是一只和其他成千上万只狐狸相似的狐狸。", "t": [9675, 16012]}, {"es": "Pero si tú me domesticas, entonces tendremos necesidad el uno del otro.", "zh": "但如果你驯养了我，我们便彼此需要了。", "t": [16012, 20700]}, {"es": "Tú serás para mí único en el mundo, yo seré para ti único en el mundo…", "zh": "你将是我世界上独一无二的人，而我将是你世上唯一的狐狸。", "t": [20700, 24512]}]}, {"id": "ch21p13", "audio": true, "sents": [{"es": "-Comienzo a comprender -dijo el principito-.", "zh": "我开始明白了——小王子说。", "t": [100, 3300]}, {"es": "Hay una flor…", "zh": "有一朵花……", "t": [3300, 4225]}, {"es": "creo que ella me ha domesticado…", "zh": "我觉得她驯养了我。", "t": [4225, 5776]}]}, {"id": "ch21p14", "audio": true, "sents": [{"es": "-Es posible -concedió el zorro-, en la Tierra se ven todo tipo de cosas.", "zh": "在地球上，可见万物纷呈。", "t": [100, 4900]}, {"es": "-¡Oh, no es en la Tierra!", "zh": "哦，那不是在地球上！", "t": [4900, 7075]}, {"es": "-exclamó el principito.", "zh": "小王子惊呼。", "t": [7075, 8374]}]}, {"id": "ch21p15", "audio": true, "sents": [{"es": "El zorro pareció intrigado: -¿En otro planeta?", "zh": "狐狸似乎很感兴趣：“在另一个星球上？”", "t": [100, 2500]}]}, {"id": "ch21p16", "audio": true, "sents": [{"es": "-Sí.", "zh": "是的。", "t": [100, 1438]}, {"es": "-¿Hay cazadores en ese planeta?", "zh": "那颗星球上有猎人吗？", "t": [1438, 3062]}]}, {"id": "ch21p17", "audio": true, "sents": [{"es": "-No.", "zh": "不。", "t": [100, 1450]}, {"es": "-¡Qué interesante!", "zh": "多么有趣啊！", "t": [1450, 3312]}, {"es": "¿Y gallinas?", "zh": "你找鸡吗？", "t": [3312, 3962]}]}, {"id": "ch21p18", "audio": true, "sents": [{"es": "-No.", "zh": "不。", "t": [100, 338]}]}, {"id": "ch21p19", "audio": true, "sents": [{"es": "-Nada es perfecto -suspiró el zorro.", "zh": "世间无完美——狐狸叹了口气。", "t": [100, 2288]}]}, {"id": "ch21p20", "audio": true, "sents": [{"es": "Y después volviendo a su idea:", "zh": "然后，他又回到了自己的想法。", "t": [100, 1774]}]}, {"id": "ch21p21", "audio": true, "sents": [{"es": "-Mi vida es muy monótona.", "zh": "我的生活非常单调。", "t": [100, 2462]}, {"es": "Cazo gallinas y los hombres me cazan a mí.", "zh": "猎人捕鸡，人猎捕我。", "t": [2462, 5562]}, {"es": "Todas las gallinas se parecen y todos los hombres son iguales; por consiguiente me aburro un poco.", "zh": "所有的鸡都长得一样，所有的人也都一样；因此我有点儿厌烦了。", "t": [5562, 11375]}, {"es": "Si tú me domesticas, mi vida estará llena de sól.", "zh": "若你驯养了我，我的生命将充满阳光。", "t": [11375, 13950]}]}, {"id": "ch21p22", "audio": true, "sents": [{"es": "Conoceré el rumor de unos pasos diferentes a todos los demás.", "zh": "我会分辨出与众不同的脚步声。", "t": [100, 4375]}, {"es": "Los otros pasos me hacen esconder bajo la tierra; los tuyos me llamarán fuera de la madriguera como una música.", "zh": "那些脚步声让我躲进地洞；而你的脚步声，如同美妙的音乐，将召唤我走出洞穴。", "t": [4375, 11150]}, {"es": "Y además, ¡mira!", "zh": "还有，瞧！", "t": [11150, 13112]}, {"es": "¿Ves allá abajo los campos de trigo?", "zh": "你瞧，那不是麦田吗？", "t": [13112, 15962]}, {"es": "Yo no como pan y por lo tanto el trigo es para mí algo inútil.", "zh": "面包我不吃，因此小麦对我来说毫无用处。", "t": [15962, 19962]}, {"es": "Los campos de trigo no me recuerdan nada y eso me pone triste.", "zh": "麦田不能唤起我的任何回忆，这让我感到忧伤。", "t": [19962, 24188]}, {"es": "¡Pero tú tienes los cabellos dorados y será algo maravilloso cuando me domestiques!", "zh": "但你的头发是金色的，等你驯养了我，那将是一件美妙的事。", "t": [24188, 29275]}, {"es": "El trigo, que es dorado también, será un recuerdo de ti.", "zh": "麦田的金色，将是你记忆中的风景。", "t": [29275, 33238]}, {"es": "Y amaré el ruido del viento en el trigo.", "zh": "我将爱麦田里风吹过的声音。", "t": [33238, 35212]}]}, {"id": "ch21p23", "audio": true, "sents": [{"es": "El zorro se calló y miró un buen rato al principito:", "zh": "狐狸沉默了，久久地凝视着小王子。", "t": [100, 2850]}]}, {"id": "ch21p24", "audio": true, "sents": [{"es": "-Por favor…", "zh": "请。", "t": [100, 762]}, {"es": "domestícame -le dijo.", "zh": "驯养了我吧。", "t": [762, 2038]}]}, {"id": "ch21p25", "audio": true, "sents": [{"es": "-Bien quisiera -le respondió el principito pero no tengo mucho tiempo.", "zh": "小王子答道：“我非常愿意，只是时间不多。”", "t": [100, 4738]}, {"es": "He de buscar amigos y conocer muchas cosas.", "zh": "他要去寻找朋友，去了解许多事物。", "t": [4738, 7138]}]}, {"id": "ch21p26", "audio": true, "sents": [{"es": "-Sólo se conocen bien las cosas que se domestican -dijo el zorro-.", "zh": "人只认识自己驯养的东西——狐狸说。", "t": [100, 4475]}, {"es": "Los hombres ya no fienen tiempo de conocer nada.", "zh": "人们不再有时间去了解任何事物。", "t": [4475, 7888]}, {"es": "Lo compran todo hecho en las tiendas.", "zh": "他们在商店里买来现成的一切。", "t": [7888, 10838]}, {"es": "Y como no hay tiendas donde vendan amigos, Ios hombres no tienen ya amigos.", "zh": "人们不再有地方购买朋友，因此他们已不再拥有朋友。", "t": [10838, 16075]}, {"es": "¡Si quieres un amigo, domestícame!", "zh": "若你愿有朋友，就驯养我吧！", "t": [16075, 18888]}, {"es": "-¿Qué debo hacer?", "zh": "我应该做什么？", "t": [18888, 20662]}, {"es": "-preguntó el príncipito.", "zh": "小王子问道。", "t": [20662, 21937]}]}, {"id": "ch21p27", "audio": true, "sents": [{"es": "-Debes tener mucha paciencia -respondió el zorro-.", "zh": "你需要有极大的耐心。", "t": [100, 3962]}, {"es": "Te sentarás al principio ún poco lejos de mí, así, en el suelo; yo te miraré con el rabillo del ojo y tú no me dirás nada.", "zh": "你起初要离我远些，坐在地上，这样；我会斜眼看你，你却不要对我说话。", "t": [3962, 11538]}, {"es": "El lenguaje es fuente de malos entendidos.", "zh": "语言是误会的根源。", "t": [11538, 14762]}, {"es": "Pero cada día podrás sentarte un poco más cerca…", "zh": "但每天你都可以坐得离我更近些……", "t": [14762, 17288]}]}, {"id": "ch21p28", "audio": true, "sents": [{"es": "El principito volvió al día siguiente.", "zh": "小王子第二天又来了。", "t": [100, 2075]}]}, {"id": "ch21p29", "audio": true, "sents": [{"es": "-Hubiera sido mejor -dijo el zorro- que vinieras a la misma hora.", "zh": "你若能每天按时来，那就好了——狐狸说。", "t": [100, 4500]}, {"es": "Si vienes, por ejempló, a las cuatro de la tarde; desde las tres yo empezaría a ser dichoso.", "zh": "若你下午四点钟来，那么从三点钟起，我便开始感到幸福了。", "t": [4500, 10262]}, {"es": "Cuanto más avance la hora, más feliz me sentiré.", "zh": "随着时刻的推移，我愈发感到幸福。", "t": [10262, 13950]}, {"es": "A las cuatro me sentiré agitado e inquieto, descubriré así lo que vale la feliçidad.", "zh": "四点钟时，我会感到心神不宁，坐立不安，从而领悟到幸福的真谛。", "t": [13950, 19275]}, {"es": "Pero si tú vienes a cualquier hora, nunça sabré cuándo preparar mi corazón…", "zh": "但如果你随时来，我就永远不知道何时准备我的心。", "t": [19275, 24038]}, {"es": "Los ritos son necesarios.", "zh": "仪式是必要的。", "t": [24038, 26638]}, {"es": "-¿Qué es un rito?", "zh": "仪式是什么？", "t": [26638, 28500]}, {"es": "-inquirió el principito.", "zh": "小王子询问。", "t": [28500, 29787]}]}, {"id": "ch21p30", "audio": true, "sents": [{"es": "-Es también algo demasiado olvidado -dijo el zorro-.", "zh": "这也是一件被人遗忘的事——狐狸说。", "t": [100, 3888]}, {"es": "Es lo que hace que un día no se parezca a otro día y que una hora sea diferente a otra.", "zh": "这使一天不同于另一天，一小时不同于另一小时。", "t": [3888, 8362]}]}, {"id": "ch21p31", "audio": true, "sents": [{"es": "Entre los cazadores, por ejemplo, hay un rito.", "zh": "猎人们，例如，有仪式。", "t": [100, 3675]}, {"es": "Los jueves bailan con las muchachas del pueblo.", "zh": "星期四，村民们与姑娘们共舞。", "t": [3675, 6975]}, {"es": "Los jueves entonces son días maravillosos en los que puedo ir de paseo hasta la viña.", "zh": "于是，星期四成了我得以漫步至葡萄园的奇妙日子。", "t": [6975, 12162]}, {"es": "Si los cazadores no bailaran en día fijo, todos los días se parecerían y yo no tendría vacaciones.", "zh": "若猎人不是在固定日子跳舞，那么每一天都将是相同的，我就没有假期了。", "t": [12162, 17738]}]}, {"id": "ch21p32", "audio": true, "sents": [{"es": "De esta manera el principito domesticó al zorro.", "zh": "小王子驯服了狐狸。", "t": [100, 3575]}, {"es": "Y cuando se fue acercando eI día de la partida: -¡Ah!", "zh": "啊！离别之日临近。", "t": [3575, 7212]}, {"es": "-dijo el zorro-, lloraré.", "zh": "狐狸说，我会哭的。", "t": [7212, 8637]}]}, {"id": "ch21p33", "audio": true, "sents": [{"es": "-Tuya es la culpa -le dijo el principito-, yo no quería hacerte daño, pero tú has querido que te domestique…", "zh": "你才是错，小王子说，我不想伤害你，但你却要我做你的朋友…", "t": [100, 5600]}]}, {"id": "ch21p34", "audio": true, "sents": [{"es": "-Ciertamente -dijo el zorro.", "zh": "当然——狐狸说。", "t": [100, 1575]}]}, {"id": "ch21p35", "audio": true, "sents": [{"es": "-Y vas a llorar!, -dijo él principito.", "zh": "你将要哭泣了，——小王子说道。", "t": [100, 3050]}, {"es": "-¡Seguro!", "zh": "当然！", "t": [3050, 3562]}]}, {"id": "ch21p36", "audio": true, "sents": [{"es": "-No ganas nada.", "zh": "我什么都不想要。", "t": [100, 1038]}]}, {"id": "ch21p37", "audio": true, "sents": [{"es": "-Gano -dijo el zoro- he ganado a causa del color del trigo.", "zh": "狐狸说：“我赢了——是因为麦田的颜色。”", "t": [100, 3362]}]}, {"id": "ch21p38", "audio": true, "sents": [{"es": "Y luego añadió:", "zh": "然后他又说：", "t": [100, 1000]}]}, {"id": "ch21p39", "audio": true, "sents": [{"es": "-Vete a ver las rosas; comprenderás que la tuya es única en el mundo.", "zh": "你的玫瑰是世界上独一无二的花儿。", "t": [100, 4762]}, {"es": "Volverás a decirme adiós y yo te regalaré un secreto.", "zh": "你将再次对我说再见，我将送你一个秘密。", "t": [4762, 7650]}]}, {"id": "ch21p40", "audio": true, "sents": [{"es": "El principito se fue a ver las rosas a las que dijo:", "zh": "小王子去看那些玫瑰，并对她们说：", "t": [100, 2724]}]}, {"id": "ch21p41", "audio": true, "sents": [{"es": "-No son nada, ni en nada se parecen a mi rosa.", "zh": "它们什么都不是，与我的玫瑰毫不相似。", "t": [100, 3775]}, {"es": "Nadie las ha domesticado ni ustedes han domesticado a nadie.", "zh": "没有人驯养过你们，你们也没有驯养过任何人。", "t": [3775, 6863]}]}, {"id": "ch21p42", "audio": true, "sents": [{"es": "Son como el zorro era antes, que en nada se diferenciaba de otros cien mil zorros.", "zh": "它依旧像曾经的狐狸，与其他成千上万只狐狸毫无区别。", "t": [100, 5412]}, {"es": "Pero yo le hice mi amigo y ahora es único en el mundo.", "zh": "但我使他成为我的朋友，如今他是这个世界上独一无二的。", "t": [5412, 8012]}]}, {"id": "ch21p43", "audio": true, "sents": [{"es": "Las rosas se sentían molestas oyendo al principito, que continuó diciéndoles:", "zh": "玫瑰们听着，小王子继续对她们说：", "t": [100, 4188]}]}, {"id": "ch21p44", "audio": true, "sents": [{"es": "-Son muy bellas, pero están vacías y nadie daría la vida por ustedes.", "zh": "她们很美，但内心空空如也，无人愿意为你们献出生命。", "t": [100, 4688]}, {"es": "Cualquiera que las vea podrá creer indudablemente que mí rosa es igual que cualquiera de ustedes.", "zh": "任何看到它们的人都会毫无疑问地认为我的玫瑰和你们的任何一朵一样。", "t": [4688, 10400]}, {"es": "Pero ella se sabe más importante que todas, porque yo la he regado, porque ha sido a ella a la que abrigué con el fanal, porque yo le maté los gusanos (salvo dos o tres que se hicieron mariposas) y es a ella a la que yo he oído quejarse, alabarse y algunas veces hasta callarse.", "zh": "因为她知道，她在我心中比任何一朵花都重要，因为我为她浇水，因为我曾为她遮挡风雨，因为我为她除虫（除了两三条变成蝴蝶的），因为我曾倾听她的抱怨、她的夸耀，有时甚至看她默默不语的样子。", "t": [10400, 26062]}, {"es": "Porque es mi rosa, en fin.", "zh": "因为她是我的玫瑰。", "t": [26062, 27712]}]}, {"id": "ch21p45", "audio": true, "sents": [{"es": "Y volvió con el zorro.", "zh": "狐狸又回来了。", "t": [100, 1274]}]}, {"id": "ch21p46", "audio": true, "sents": [{"es": "-Adiós -le dijo.", "zh": "再见——他对她说。", "t": [100, 1163]}]}, {"id": "ch21p47", "audio": true, "sents": [{"es": "-Adiós -dijo el zorro-.", "zh": "再见——狐狸说。", "t": [100, 2450]}, {"es": "He aquí mi secreto, que no puede ser más simple: sólo con el corazón se puede ver bien; lo esencial es invisible para los ojos.", "zh": "用心去看，才能看得真切；本质的东西，肉眼是看不见的。", "t": [2450, 9500]}]}, {"id": "ch21p48", "audio": true, "sents": [{"es": "-Lo esencial es invisible para los ojos -repitió el principito para acordarse.", "zh": "本质的东西，肉眼是看不见的——小王子反复念诵，以便牢记。", "t": [100, 4325]}]}, {"id": "ch21p49", "audio": true, "sents": [{"es": "-Lo que hace más importante a tu rosa, es el tiempo que tú has perdido con ella.", "zh": "那使你的玫瑰变得重要的，是你为她所浪费的时间。", "t": [100, 4112]}]}, {"id": "ch21p50", "audio": true, "sents": [{"es": "-Es el tiempo que yo he perdido con ella…", "zh": "那是我与她共度的时光……", "t": [100, 2350]}, {"es": "-repitió el principito para recordarlo.", "zh": "小王子反复念诵，以便牢记。", "t": [2350, 4387]}]}, {"id": "ch21p51", "audio": true, "sents": [{"es": "-Los hombres han olvidado esta verdad -dijo el zorro-, pero tú no debes olvidarla.", "zh": "人们忘记了这条真理——狐狸说，但你却不该忘。", "t": [100, 5025]}, {"es": "Eres responsable para siempre de lo que has domesticado.", "zh": "你将永远对你驯养的东西负责。", "t": [5025, 8775]}, {"es": "Tú eres responsable de tu rosa…", "zh": "你对你那朵玫瑰负有责任。", "t": [8775, 10550]}]}, {"id": "ch21p52", "audio": true, "sents": [{"es": "-Yo soy responsable de mi rosa…", "zh": "我对我那朵玫瑰负有责任。", "t": [100, 2188]}, {"es": "-repitió el principito a fin de recordarlo", "zh": "小王子反复念诵，以便牢记", "t": [2188, 4337]}]}]}, {"id": "ch22", "title_es": "Capítulo 22", "title_zh": "第 22 章", "paras": [{"id": "ch22p00", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "您好。", "t": [100, 1950]}, {"es": "-dijo el principito.", "zh": "小王子说。", "t": [1950, 4025]}, {"es": "-¡Buenos días!", "zh": "您好。", "t": [4025, 5875]}, {"es": "-respondió el guardavías.", "zh": "扳道工答道。", "t": [5875, 8338]}, {"es": "-¿Qué haces aquí?", "zh": "您在此做什么？", "t": [8338, 10075]}, {"es": "-le preguntó el principito.", "zh": "小王子问道。", "t": [10075, 11474]}]}, {"id": "ch22p01", "audio": true, "sents": [{"es": "-Formo con los viajeros paquetes de mil y despacho los trenes que los llevan, ya a la derecha, ya a la izquierda.", "zh": "我给旅客们编组，派发前往左右两侧的列车。", "t": [100, 5926]}]}, {"id": "ch22p02", "audio": true, "sents": [{"es": "Y un tren rápido iluminado, rugiendo como el trueno, hizo temblar la caseta del guardavías.", "zh": "一列快速行驶的火车，如同雷鸣般轰鸣，震得扳道房摇曳不定。", "t": [100, 5312]}]}, {"id": "ch22p03", "audio": true, "sents": [{"es": "-Tienen mucha prisa -dijo el principito-.", "zh": "他们匆匆忙忙。", "t": [100, 3425]}, {"es": "¿Qué buscan?", "zh": "他们在寻找什么？", "t": [3425, 4062]}]}, {"id": "ch22p04", "audio": true, "sents": [{"es": "-Ni siquiera el conductor de la locomotora lo sabe -dijo el guardavías.", "zh": "连火车头上的司机也弄不清楚——扳道工说。", "t": [100, 3788]}]}, {"id": "ch22p05", "audio": true, "sents": [{"es": "Un segundo rápido iluminado rugió en sentido inverso.", "zh": "第二列灯火通明的火车反向轰鸣而过。", "t": [100, 4088]}, {"es": "-¿Ya vuelve?", "zh": "他们已经回来了吗？", "t": [4088, 5650]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [5650, 6850]}]}, {"id": "ch22p06", "audio": true, "sents": [{"es": "-No son los mismos -contestó el guardvías-.", "zh": "这不是同一批人——扳道工答道。", "t": [100, 3438]}, {"es": "Es un cambio.", "zh": "这又是一个变化。", "t": [3438, 5212]}, {"es": "-¿No se sentían contentos donde estaban?", "zh": "他们不觉得在原地就快乐吗？", "t": [5212, 7437]}]}, {"id": "ch22p07", "audio": true, "sents": [{"es": "-Nunca se siente uno contento donde está -respondió el guardavías.", "zh": "他答道：“人们永远无法在原地感到满足。”", "t": [100, 3975]}]}, {"id": "ch22p08", "audio": true, "sents": [{"es": "Y rugió el trueno de un tercer rápido iluminado.", "zh": "第三列灯火通明的火车，雷鸣般轰鸣而过。", "t": [100, 3675]}, {"es": "-¿Van persiguiendo a los primeros viajeros?", "zh": "他们在追赶第一批旅客吗？", "t": [3675, 6800]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [6800, 8000]}]}, {"id": "ch22p09", "audio": true, "sents": [{"es": "-No persiguen absolutamente nada -le dijo el guardavías-; duermen o bostezan allí dentro.", "zh": "他们根本不追逐任何东西——扳道工说；他们在里面睡觉或打哈欠。", "t": [100, 5812]}, {"es": "Unicamente los niños aplastan su nariz contra los vidrios.", "zh": "孩子们将鼻子紧紧贴在玻璃上。", "t": [5812, 9050]}]}, {"id": "ch22p10", "audio": true, "sents": [{"es": "-Unicamente los niños saben lo que buscan -dijo el principito.", "zh": "唯有孩子知晓他们所寻何物——小王子说。", "t": [100, 4288]}, {"es": "Pierden el tiempo con una muñeca de trapo que viene a ser lo más importante para ellos y si se la quitan, lloran…", "zh": "他们与一块布偶玩具消磨时光，那玩具渐渐变得对他们至关重要，若有人夺走，他们便泪流满面……", "t": [4288, 10038]}, {"es": "-¡Qué suerte tienen!", "zh": "他们真是有福气！", "t": [10038, 11875]}, {"es": "-dijo el guardavías.", "zh": "扳道工说。", "t": [11875, 13000]}]}]}, {"id": "ch23", "title_es": "Capítulo 23", "title_zh": "第 23 章", "paras": [{"id": "ch23p00", "audio": true, "sents": [{"es": "-¡Buenos días!", "zh": "您好。", "t": [100, 1950]}, {"es": "-dijo el principito.", "zh": "小王子说。", "t": [1950, 4025]}, {"es": "-¡Buenos días!", "zh": "您好。", "t": [4025, 5875]}, {"es": "-respondió el comerciante.", "zh": "商人答道。", "t": [5875, 7287]}]}, {"id": "ch23p01", "audio": true, "sents": [{"es": "Era un comerciante de píldoras perfeccionadas que quitan la sed.", "zh": "这是一位贩卖完美药丸以解渴的商人。", "t": [100, 4200]}, {"es": "Se toma una por semana y ya no se sienten ganas de beber.", "zh": "每周服用一颗，便不再渴望饮水。", "t": [4200, 8112]}, {"es": "-¿Por qué vendes eso?", "zh": "你为何卖这东西？", "t": [8112, 10138]}, {"es": "-preguntó el principito.", "zh": "小王子问道。", "t": [10138, 11337]}]}, {"id": "ch23p02", "audio": true, "sents": [{"es": "-Porque con esto se economiza mucho tiempo.", "zh": "这便能节省许多时间。", "t": [100, 3275]}, {"es": "Según el cálculo hecho por los expertos, se ahorran cincuenta y tres minutos por semana.", "zh": "专家们计算，每周可节省五十三分钟。", "t": [3275, 8850]}, {"es": "-¿Y qué se hace con esos cincuenta y tres minutos?", "zh": "这五十三分钟，又当如何使用？", "t": [8850, 11250]}]}, {"id": "ch23p03", "audio": true, "sents": [{"es": "-Lo que cada uno quiere…", "zh": "各人所愿…", "t": [100, 1313]}, {"es": "\"", "zh": "这便能节省许多时间。", "t": [1313, 1813]}]}, {"id": "ch23p04", "audio": true, "sents": [{"es": "\"Si yo dispusiera de cincuenta y tres minutos -pensó el principito- caminaría suavemente hacia una fuente…\"", "zh": "若我有五十三分钟——小王子心想——便可以缓缓走向那泉边……", "t": [100, 5637]}]}]}, {"id": "ch24", "title_es": "Capítulo 24", "title_zh": "第 24 章", "paras": [{"id": "ch24p00", "audio": true, "sents": [{"es": "Era el octavo día de mi avería en el desierto y había escuchado la historia del comerciante bebiendo la última gota de mi provisión de agua.", "zh": "沙漠中飞机故障的第八天，我听到了商人的故事，喝完了最后一滴水。", "t": [100, 7900]}, {"es": "-¡Ah -le dije al principito-, son muy bonitos tus cuentos, pero yo no he reparado mi avión, no tengo nada para beber y sería muy feliz si pudiera irme muy tranquilo en busca de una fuente!", "zh": "“啊——我对小王子说——你的这些故事很美，可我还没修好我的飞机，又渴得要命，若能悠然地走向一汪清泉，那该多幸福啊！”", "t": [7900, 17250]}]}, {"id": "ch24p01", "audio": true, "sents": [{"es": "-Mi amigo el zorro…, me dijo…", "zh": "我的朋友狐狸对我说……", "t": [100, 1675]}]}, {"id": "ch24p02", "audio": true, "sents": [{"es": "-No se trata ahora del zorro, muchachito…", "zh": "这不关狐狸的事，孩子。", "t": [100, 2475]}, {"es": "-¿Por qué?", "zh": "为什么？", "t": [2475, 2812]}]}, {"id": "ch24p03", "audio": true, "sents": [{"es": "-Porque nos vamos a morir de sed…", "zh": "因为我们快要渴死了……", "t": [100, 1663]}]}, {"id": "ch24p04", "audio": true, "sents": [{"es": "No comprendió mi razonamiento y replicó:", "zh": "他不懂我说的理由，便简单地回答道：", "t": [100, 2337]}]}, {"id": "ch24p05", "audio": true, "sents": [{"es": "-Es bueno haber tenido un amigo, aún si vamos a morir.", "zh": "有了一位朋友，纵使命悬一线，亦是幸事。", "t": [100, 4062]}, {"es": "Yo estoy muy contento de haber tenido un amigo zorro.", "zh": "我很高兴曾有一位狐狸朋友。", "t": [4062, 6850]}]}, {"id": "ch24p06", "audio": true, "sents": [{"es": "\"Es incapaz de medir el peligro -me dije - Nunca tiene hambre ni sed y un poco de sol le basta…\"", "zh": "他无法衡量危险——我对自己说——他从不感到饥饿和口渴，一点阳光就足以让他满足……", "t": [100, 5000]}]}, {"id": "ch24p07", "audio": true, "sents": [{"es": "El principito me miró y respondió a mi pensamiento:", "zh": "小王子望着我，回应了我的思绪：", "t": [100, 2788]}]}, {"id": "ch24p08", "audio": true, "sents": [{"es": "-Tengo sed también…", "zh": "我也渴……", "t": [100, 1300]}, {"es": "vamos a buscar un pozo…", "zh": "我们去找一口井吧……", "t": [1300, 2588]}]}, {"id": "ch24p09", "audio": true, "sents": [{"es": "Tuve un gesto de cansancio; es absurdo buscar un pozo, al azar, en la inmensidad del desierto.", "zh": "疲惫地一挥手，在这沙漠的浩瀚中随意寻找一口井，岂非荒谬至极？", "t": [100, 6100]}, {"es": "Sin embargo, nos pusimos en marcha.", "zh": "然而，我们还是出发了。", "t": [6100, 7987]}]}, {"id": "ch24p10", "audio": true, "sents": [{"es": "Después de dos horas de caminar en silencio, cayó la noche y las estrellas comenzaron a brillar.", "zh": "夜幕降临，星辰开始闪烁。", "t": [100, 5875]}, {"es": "Yo las veía como en sueño, pues a causa de la sed tenía un poco de fiebre.", "zh": "我仿佛置身梦境，因干渴而微微发烧。", "t": [5875, 10550]}, {"es": "Las palabras del principito danzaban en mi mente.", "zh": "小王子的言语在我脑海中翩翩起舞。", "t": [10550, 14038]}, {"es": "-¿Tienes sed, tú también?", "zh": "你也渴了吗？", "t": [14038, 16275]}, {"es": "-le pregunté.", "zh": "我问他。", "t": [16275, 18038]}, {"es": "Pero no respondió a mi pregunta, diciéndome simplemente:", "zh": "但他没有回答我的问题，只是简单地说：", "t": [18038, 21175]}]}, {"id": "ch24p11", "audio": true, "sents": [{"es": "-El agua puede ser buena también para el corazón…", "zh": "水对心也有益……", "t": [100, 2412]}]}, {"id": "ch24p12", "audio": true, "sents": [{"es": "No comprendí sus palabras, pero me callé; sabía muy bien que no había que interrogarlo.", "zh": "我不懂他的话，但我知道不该问他。", "t": [100, 4687]}]}, {"id": "ch24p13", "audio": true, "sents": [{"es": "El principito estaba cansado y se sentó; yo me senté a su lado y después de un silencio me dijo:", "zh": "小王子累了，便坐了下来；我坐在他身边，沉默片刻后，他开口说道：", "t": [100, 5075]}]}, {"id": "ch24p14", "audio": true, "sents": [{"es": "-Las estrellas son hermosas, por una flor que no se ve…", "zh": "星星之所以美丽，是因为其中藏着一朵看不见的花。", "t": [100, 2975]}]}, {"id": "ch24p15", "audio": true, "sents": [{"es": "Respondí \"seguramente\" y miré sin hablar los pliegues que la arena formaba bajo la luna.", "zh": "我默默地看着月光下沙地上形成的纹路。", "t": [100, 4512]}]}, {"id": "ch24p16", "audio": true, "sents": [{"es": "-El desierto es bello -añadió el principito.", "zh": "沙漠真美——小王子补充道。", "t": [100, 2575]}]}, {"id": "ch24p17", "audio": true, "sents": [{"es": "Era verdad; siempre me ha gustado el desierto.", "zh": "沙漠确实如此，我始终喜爱这片荒漠。", "t": [100, 3575]}, {"es": "Puede uno sentarse en una duna, nada se ve, nada se oye y sin embargo, algo resplandece en el silencio…", "zh": "坐在沙丘之上，四顾茫茫，耳不闻声，目不见物，而寂静之中，却有一星微光闪烁。", "t": [3575, 9450]}]}, {"id": "ch24p18", "audio": true, "sents": [{"es": "-Lo que más embellece al desierto -dijo el principito- es el pozo que oculta en algún sitio…", "zh": "沙漠之美，在于它隐藏在某个角落的井。", "t": [100, 5012]}]}, {"id": "ch24p19", "audio": true, "sents": [{"es": "Me quedé sorprendido al comprender súbitamente ese misterioso resplandor de la arena.", "zh": "我猛然惊觉，那片沙丘上的神秘闪光令我惊讶不已。", "t": [100, 5500]}, {"es": "Cuando yo era niño vivía en una casa antigua en la que, según la leyenda, había un tesoro escondido.", "zh": "我儿时住在一座古老房子里，传说那里藏有一件宝物。", "t": [5500, 11525]}, {"es": "Sin duda que nadie supo jamás descubrirlo y quizás nadie lo buscó, pero parecía toda encantada por ese tesoro.", "zh": "那宝藏似乎始终无人知晓，也许根本无人寻觅，却宛如被施了魔法，充满了魅力。", "t": [11525, 18488]}, {"es": "Mi casa ocultaba un secreto en el fondo de su corazón…", "zh": "我的家在心底深处藏着一个秘密……", "t": [18488, 21350]}]}, {"id": "ch24p20", "audio": true, "sents": [{"es": "-Sí -le dije al principito- ya se trate de la casa, de las estrellas o del desierto, lo que les embellece es invisible.", "zh": "是的——我对小王子说——“无论是房子、星星还是沙漠，赋予它们美丽的是那些肉眼无法看见的东西。”", "t": [100, 6576]}]}, {"id": "ch24p21", "audio": true, "sents": [{"es": "-Me gusta -dijo el principito- que estés de acuerdo con mi zorro.", "zh": "小王子说：“我喜欢你同意我的狐狸。”", "t": [100, 3162]}]}, {"id": "ch24p22", "audio": true, "sents": [{"es": "Como el principito se dormía, lo tomé en mis brazos y me puse nuevamente en camino.", "zh": "小王子入睡，我把他抱在怀里，再次踏上旅程。", "t": [100, 5475]}, {"es": "Me sentía emocionado llevando aquel frágil tesoro, y me parecía que nada más frágil había sobre la Tierra.", "zh": "怀抱着这脆弱的珍宝，我感到无比激动，仿佛在地球上再无更脆弱之物。", "t": [5475, 11962]}, {"es": "Miraba a la luz de la luna aquella frente pálida, aquellos ojos cerrados, los cabellos agitados por el viento y me decía: \"lo que veo es sólo la corteza; lo más importante es invisible…", "zh": "凝视着月光下他苍白的脸庞、紧闭的双眼、随风飘扬的秀发，他轻声对我说：“我所看见的只是表象；最重要的东西是看不见的……”", "t": [11962, 22212]}, {"es": "\"", "zh": "沙漠之美，在于它隐藏在某个角落的井。", "t": [22212, 22712]}]}, {"id": "ch24p23", "audio": true, "sents": [{"es": "Como sus labios entreabiertos esbozaron una sonrisa, me dije: \"Lo que más me emociona de este principito dormido es su fidelidad a una flor, es la imagen de la rosa que resplandece en él como la llama de una lámpara, incluso cuando duerme…", "zh": "他的嘴唇微微张开，露出一丝微笑，我心想：“这个小王子熟睡时最令我感动的，是他对于一朵花的忠诚，是玫瑰的倩影在他心中如灯焰般闪耀，即使是在梦乡……”", "t": [100, 13400]}, {"es": "\" Y lo sentí más frágil aún.", "zh": "我感到他更加脆弱了。", "t": [13400, 15875]}, {"es": "Pensaba que a las lámparas hay que protegerlas: una racha de viento puede apagarlas…", "zh": "认为灯需要小心呵护，一阵狂风就能将其吹灭。", "t": [15875, 20362]}]}, {"id": "ch24p24", "audio": true, "sents": [{"es": "Continué caminando y al rayar el alba descubrí el pozo.", "zh": "继续前行，曙光微露时，我发现了那口井。", "t": [100, 2975]}]}]}, {"id": "ch25", "title_es": "Capítulo 25", "title_zh": "第 25 章", "paras": [{"id": "ch25p00", "audio": true, "sents": [{"es": "-Los hombres -dijo el principito- se meten en los rápidos pero no saben dónde van ni lo que quieren…", "zh": "人们——小王子说——“他们挤进快车，却不知何去何从，亦不知所求为何。”", "t": [100, 5975]}, {"es": "Entonces se agitan y dan vueltas…", "zh": "于是他们慌乱地团团打转……", "t": [5975, 7850]}]}, {"id": "ch25p01", "audio": true, "sents": [{"es": "Y añadió: -¡No vale la pena!…", "zh": "何苦如此！…", "t": [100, 1588]}]}, {"id": "ch25p02", "audio": true, "sents": [{"es": "El pozo que habíamos encontrado no se parecía en nada a los pozos saharianos.", "zh": "这口井与撒哈拉沙漠的井截然不同。", "t": [100, 5088]}, {"es": "Estos pozos son simples agujeros que se abren en la arena.", "zh": "这些井只是沙地上挖出的简单洞孔。", "t": [5088, 9188]}, {"es": "El que teníamos ante nosotros parecía el pozo de un pueblo; pero por allí no había ningún pueblo y me parecía estar soñando.", "zh": "这口井宛若村中井泉；然而四周并无村落，我仿佛置身梦境。", "t": [9188, 15388]}]}, {"id": "ch25p03", "audio": true, "sents": [{"es": "-¡Es extraño!", "zh": "这真奇怪！", "t": [100, 1862]}, {"es": "-le dije al principito-.", "zh": "我对小王子说。", "t": [1862, 4062]}, {"es": "Todo está a punto: la roldana, el balde y la cuerda…", "zh": "一切井然有序：辘轳、水桶和绳子……", "t": [4062, 7062]}]}, {"id": "ch25p04", "audio": true, "sents": [{"es": "Se rió y tocó la cuerda; hizo mover la roldana.", "zh": "他笑着，拨动了绳子；让辘轳转动起来。", "t": [100, 3800]}, {"es": "Y la roldana gimió como una vieja veleta cuando el viento ha dormido mucho.", "zh": "辘轳如同沉睡已久的古风信鸡，发出低吟。", "t": [3800, 8425]}, {"es": "-¿Oyes?", "zh": "你听见了吗？", "t": [8425, 9888]}, {"es": "-dijo el principito-.", "zh": "小王子说。", "t": [9888, 11962]}, {"es": "Hemos despertado al pozo y canta.", "zh": "我们唤醒了这口井，它唱起了歌。", "t": [11962, 13800]}]}, {"id": "ch25p05", "audio": true, "sents": [{"es": "No quería que el principito hiciera el menor esfuerzo y le dije:", "zh": "我不愿小王子付出丝毫劳力，便对他说：", "t": [100, 3163]}]}, {"id": "ch25p06", "audio": true, "sents": [{"es": "-Déjame a mí, es demasiado pesado para ti.", "zh": "让我来吧，这对你来说太沉重了。", "t": [100, 2500]}]}, {"id": "ch25p07", "audio": true, "sents": [{"es": "Lentamente subí el cubo hasta el brocal donde lo dejé bien seguro.", "zh": "缓缓将水桶提到井沿，稳妥地放置。", "t": [100, 3475]}]}, {"id": "ch25p08", "audio": true, "sents": [{"es": "En mis oídos sonaba aún el canto de la roldana y veía temblar al sol en el agua agitada.", "zh": "辘轳之歌仍在耳畔回响，我看见太阳在波动的井水中微微颤动。", "t": [100, 4775]}]}, {"id": "ch25p09", "audio": true, "sents": [{"es": "-Tengo sed de esta agua -dijo el principito-, dame de beber…", "zh": "我渴望的就是这样的水——小王子说——给我喝一点……", "t": [100, 4288]}, {"es": "¡Comprendí entonces lo que él había buscado!", "zh": "我那时才明白他一直在寻找什么。", "t": [4288, 6563]}]}, {"id": "ch25p10", "audio": true, "sents": [{"es": "Levanté el balde hasta sus labios y el principito bebió con los ojos cerrados.", "zh": "我举桶至他唇边，小王子闭目啜饮。", "t": [100, 5038]}, {"es": "Todo era bello como una fiesta.", "zh": "一切宛如庆典般美好。", "t": [5038, 6750]}]}, {"id": "ch25p11", "audio": true, "sents": [{"es": "Aquella agua era algo más que un alimento.", "zh": "那水不仅仅是食物。", "t": [100, 3362]}, {"es": "Había nacido del caminar bajo las estrellas, del canto de la roldana, del esfuerzo de mis brazos.", "zh": "它诞生于星光下的跋涉，辘轳的歌声中，我双臂的努力之下。", "t": [3362, 9462]}, {"es": "Era como un regalo para el corazón.", "zh": "宛如一份心灵的馈赠。", "t": [9462, 12312]}, {"es": "Cuando yo era niño, las luces del árbol de Navidad, la música de la misa de medianoche, la dulzura de las sonrisas, daban su resplandor a mi regalo de Navidad.", "zh": "当我还是个孩子时，圣诞树上的灯光、子夜弥撒的乐声，以及甜蜜的微笑，都为我的圣诞礼物增添了光彩。", "t": [12312, 21137]}]}, {"id": "ch25p12", "audio": true, "sents": [{"es": "-Los hombres de tu tierra -dijo el principito- cultivan cinco mil rosas en un jardín y no encuentran lo que buscan.", "zh": "你们地球上的人们——小王子说——“他们在花园里种植五千朵玫瑰，却找不到他们所寻找的东西。”", "t": [100, 6125]}]}, {"id": "ch25p13", "audio": true, "sents": [{"es": "-No lo encuentran nunca -le respondí.", "zh": "他们永远找不到。", "t": [100, 3088]}, {"es": "-Y sin embargo, lo que buscan podrían encontrarlo en una sola rosa o en un poco de agua…", "zh": "然而，他们所寻找的或许只需一朵玫瑰或一点水即可找到。", "t": [3088, 7450]}]}, {"id": "ch25p14", "audio": true, "sents": [{"es": "-Sin duda, respondí.", "zh": "无疑，我答道。", "t": [100, 2400]}, {"es": "Y el principito añadió:", "zh": "小王子接着说：", "t": [2400, 3688]}]}, {"id": "ch25p15", "audio": true, "sents": [{"es": "-Pero los ojos son ciegos.", "zh": "但眼睛是盲的。", "t": [100, 2500]}, {"es": "Hay que buscar con el corazón.", "zh": "用心去寻找。", "t": [2500, 4050]}]}, {"id": "ch25p16", "audio": true, "sents": [{"es": "Yo había bebido y me encontraba bien.", "zh": "我饮过，感觉甚佳。", "t": [100, 2988]}, {"es": "La arena, al alba, era color de miel, del que gozaba hasta sentirme dichoso.", "zh": "沙子在黎明时泛着蜜色，我沉浸其中，心满意足。", "t": [2988, 8012]}, {"es": "¿Por qué había de sentirme triste?", "zh": "我为何要感到忧伤？", "t": [8012, 9737]}]}, {"id": "ch25p17", "audio": true, "sents": [{"es": "-Es necesario que cumplas tu promesa -dijo dulcemente el principito que nuevamente se había sentado junto a mi.", "zh": "小王子温柔地说：“你必须履行你的诺言。”", "t": [100, 6712]}, {"es": "-¿Qué promesa?", "zh": "什么诺言？", "t": [6712, 7362]}]}, {"id": "ch25p18", "audio": true, "sents": [{"es": "-Ya sabes…", "zh": "你知道…", "t": [100, 788]}, {"es": "el bozal para mi cordero…", "zh": "为我的小羊画个口罩…", "t": [788, 2350]}, {"es": "soy responsable de mi flor.", "zh": "我对我那朵花负责。", "t": [2350, 3800]}]}, {"id": "ch25p19", "audio": true, "sents": [{"es": "Saqué del bolsillo mis esbozos de dibujo.", "zh": "我从口袋里掏出我的草图。", "t": [100, 3288]}, {"es": "El principito los miró y dijo riendo:", "zh": "小王子看着他们，笑着说道：", "t": [3288, 5374]}]}, {"id": "ch25p20", "audio": true, "sents": [{"es": "-Tus baobabs parecen repollos…", "zh": "你的猴面包树看起来像卷心菜…", "t": [100, 2038]}, {"es": "-¡Oh!", "zh": "哦！", "t": [2038, 3100]}, {"es": "¡Y yo que estaba tan orgulloso de mis baobabs!", "zh": "我原以为我的猴面包树画得挺不错！", "t": [3100, 5362]}]}, {"id": "ch25p21", "audio": true, "sents": [{"es": "-Tu zorro tíene orejas que parecen cuernos; son demasiado largas.", "zh": "你的狐狸耳朵像角一样；太长了。", "t": [100, 3775]}]}, {"id": "ch25p22", "audio": true, "sents": [{"es": "Y volvió a reír.", "zh": "他又笑了。", "t": [100, 1075]}]}, {"id": "ch25p23", "audio": true, "sents": [{"es": "-Eres injusto, muchachito; yo no sabía dibujar más que boas cerradas y boas abiertas.", "zh": "你太不公平了，小家伙；我只会画闭着的蛇和开着的蛇。", "t": [100, 6062]}, {"es": "-¡Oh, todo se arreglará!", "zh": "一切都会好起来的。", "t": [6062, 8312]}, {"es": "-dijo el principito-.", "zh": "小王子说。", "t": [8312, 10388]}, {"es": "Los niños entienden.", "zh": "孩子们懂得。", "t": [10388, 11650]}]}, {"id": "ch25p24", "audio": true, "sents": [{"es": "Bosquejé, pues, un bozal y se lo alargué con el corazón oprimido:", "zh": "我于是草草地画了一个口罩，带着沉重的心情递给他。", "t": [100, 3474]}]}, {"id": "ch25p25", "audio": true, "sents": [{"es": "-Tú tienes proyectos que yo ignoro…", "zh": "你有着我不知道的计划……", "t": [100, 1962]}]}, {"id": "ch25p26", "audio": true, "sents": [{"es": "Pero no me respondió.", "zh": "但他没有回答。", "t": [100, 2188]}, {"es": "-¿Sabes?", "zh": "你知道吗？", "t": [2188, 3738]}, {"es": "-me dijo-.", "zh": "他轻声说道：", "t": [3738, 5262]}, {"es": "Mañana hace un año de mi caída en la Tierra…", "zh": "明天是我坠落到地球上的周年。", "t": [5262, 7612]}]}, {"id": "ch25p27", "audio": true, "sents": [{"es": "Y después de un silencio, añadió:", "zh": "沉默片刻，他又说：", "t": [100, 2050]}]}, {"id": "ch25p28", "audio": true, "sents": [{"es": "-Caí muy cerca de aquí…", "zh": "我坠落得离这里很近…", "t": [100, 1313]}]}, {"id": "ch25p29", "audio": true, "sents": [{"es": "El principito se sonrojó y nuevamente, sin comprender por qué, experimenté una extraña tristeza.", "zh": "小王子脸红了，我又一次，不知为何，感到一种奇怪的悲伤。", "t": [100, 5012]}]}, {"id": "ch25p30", "audio": true, "sents": [{"es": "Sin embargo, se me ocurrió preguntar:", "zh": "然而，我忽然想到该问一问：", "t": [100, 2063]}]}, {"id": "ch25p31", "audio": true, "sents": [{"es": "-Entonces no te encontré por azar hace ocho días, cuando paseabas por estos lugares, a mil millas de distancia del lugar habitado más próximo.", "zh": "那么，八天前，你并不是偶然在这荒野千里之外的地方遇见我。", "t": [100, 8588]}, {"es": "¿Es que volvías al punto de tu caída?", "zh": "你是在回到坠落的地点吗？", "t": [8588, 10500]}]}, {"id": "ch25p32", "audio": true, "sents": [{"es": "El principito enrojeció nuevamente.", "zh": "小王子再次脸红。", "t": [100, 2025]}]}, {"id": "ch25p33", "audio": true, "sents": [{"es": "Y añadí vacilante.", "zh": "我加上了一些犹豫。", "t": [100, 2162]}, {"es": "-¿Quizás por el aniversario?", "zh": "或许是为了纪念周年。", "t": [2162, 3563]}]}, {"id": "ch25p34", "audio": true, "sents": [{"es": "El principito se ruborizó una vez más.", "zh": "小王子又红了脸。", "t": [100, 3250]}, {"es": "Aunque nunca respondía a las preguntas, su rubor signifícaba una respuesta afirmativa.", "zh": "尽管他从不回答问题，他的脸红却意味着肯定的回答。", "t": [3250, 8962]}, {"es": "-¡Ah!", "zh": "啊！", "t": [8962, 10225]}, {"es": "-le dije- tengo miedo.", "zh": "我说，我怕了。", "t": [10225, 11476]}]}, {"id": "ch25p35", "audio": true, "sents": [{"es": "Pero él me respondió:", "zh": "但他回答我说：", "t": [100, 1137]}]}, {"id": "ch25p36", "audio": true, "sents": [{"es": "-Tú debes trabajar ahora; vuelve, pues, junto a tu máquina, que yo te espero aquí.", "zh": "你该去工作了；所以，就回到你的机器旁去，我在这里等你。", "t": [100, 5762]}, {"es": "Vuelve mañana por la tarde.", "zh": "明天下午再来。", "t": [5762, 7188]}]}, {"id": "ch25p37", "audio": true, "sents": [{"es": "Pero yo no estaba tranquilo y me acordaba del zorro.", "zh": "但我心中不安，想起了狐狸。", "t": [100, 3638]}, {"es": "Si se deja uno domesticar, se expone a llorar un poco…", "zh": "若被驯养，难免会流几滴泪…", "t": [3638, 6813]}]}]}, {"id": "ch26", "title_es": "Capítulo 26", "title_zh": "第 26 章", "paras": [{"id": "ch26p00", "audio": true, "sents": [{"es": "A1 lado del pozo había una ruina de un viejo muro de piedras.", "zh": "井边有一段古老的石墙残垣。", "t": [100, 3524]}]}, {"id": "ch26p01", "audio": true, "sents": [{"es": "Cuando volví de mi trabajo al día siguiente por la tarde, vi desde lejos al principito sentado en lo alto con las piernas colgando.", "zh": "第二天傍晚，我从工作归来，远远望见小王子坐在残垣之上，双腿悬空。", "t": [100, 7512]}, {"es": "Lo oí que hablaba.", "zh": "我听见他在说话。", "t": [7512, 8488]}]}, {"id": "ch26p02", "audio": true, "sents": [{"es": "-¿No te acuerdas?", "zh": "你不记得了吗？", "t": [100, 2012]}, {"es": "¡No es aquí con exactitud!", "zh": "这里并不完全准确。", "t": [2012, 3462]}]}, {"id": "ch26p03", "audio": true, "sents": [{"es": "Alguien le respondió sín duda, porque él replicó: -¡Sí, sí; es el día, pero no es este el lugar!", "zh": "有人无疑回应了他，因为他反驳道：“没错，没错；是这一天，但不是这个地方……”", "t": [100, 5487]}]}, {"id": "ch26p04", "audio": true, "sents": [{"es": "Proseguí mi marcha hacia el muro, pero no veía ni oía a nadie.", "zh": "我继续朝墙走去，却既不见也不闻任何人。", "t": [100, 4550]}, {"es": "Y sin embargo, el principito replicó de nuevo.", "zh": "然而，小王子又反驳道。", "t": [4550, 7812]}, {"es": "-¡Claro!", "zh": "当然！", "t": [7812, 9175]}, {"es": "Ya verás dónde comienza mi huella en la arena.", "zh": "你将看到我的足迹在沙地上起始之处。", "t": [9175, 12400]}, {"es": "No tienes más que esperarme, que allí estaré yo esta noche.", "zh": "你只需在此等候，今夜我必至。", "t": [12400, 15562]}, {"es": "¿", "zh": "你弄错了。", "t": [15562, 16538]}, {"es": "Yo estaba a veinte metros y continuaba sin distinguir nada.", "zh": "我站在二十米外，依旧辨不出任何东西。", "t": [16538, 19663]}]}, {"id": "ch26p05", "audio": true, "sents": [{"es": "El principito, después de un silencio, dijo aún:", "zh": "小王子沉默片刻，然后说道：", "t": [100, 2776]}]}, {"id": "ch26p06", "audio": true, "sents": [{"es": "Tienes un buen veneno?", "zh": "你有好毒药吗？", "t": [100, 2188]}, {"es": "¿Estás segura de no hacerme sufrir mucho?", "zh": "你确定不会让我遭受太多痛苦吗？", "t": [2188, 4363]}]}, {"id": "ch26p07", "audio": true, "sents": [{"es": "Me detuve con el corazón oprimido, siempre sin comprender.", "zh": "心被紧紧压住，始终无法理解。", "t": [100, 4288]}, {"es": "-¡Ahora vete -dijo el principito-, quiero volver a bajarme!", "zh": "“现在你走吧——小王子说，我想再下去一次。”", "t": [4288, 7087]}]}, {"id": "ch26p08", "audio": true, "sents": [{"es": "Dirigí la mirada hacia el pie del muro e instintivamente di un brinco.", "zh": "我目光投向墙脚，本能地一跃而起。", "t": [100, 4612]}, {"es": "Una serpiente de esas amarillas que matan a una persona en menos de treínta segundos, se erguía en dirección al principito.", "zh": "一条黄蛇，三十秒内就能夺人性命，昂首朝向小王子。", "t": [4612, 11825]}, {"es": "Echando mano al bolsillo para sacar mi revólver, apreté el paso, pero, al ruido que hice, la serpiente se dejó deslizar suavemente por la arena como un surtidor que muere, y, sin apresurarse demasiado, se escurrió entre las piedras con un lígero ruido metálico.", "zh": "伸手掏出我的手枪，我加快了脚步，但我的脚步声却让那条蛇像枯竭的喷泉一样，缓缓地滑过沙地，然后不慌不忙地钻进石缝，发出轻微的金属声响。", "t": [11825, 26074]}]}, {"id": "ch26p09", "audio": true, "sents": [{"es": "Llegué junto al muro a tiempo de recibir en mis brazos a mi principito, que estaba blanco como la nieve.", "zh": "及时赶到墙边，将我的小王子抱在怀里，他脸色苍白如雪。", "t": [100, 6288]}, {"es": "-¿Pero qué historia es ésta?", "zh": "这究竟是个什么故事？", "t": [6288, 8638]}, {"es": "¿De charla también con las serpientes?", "zh": "蛇也会交谈吗？", "t": [8638, 10563]}]}, {"id": "ch26p10", "audio": true, "sents": [{"es": "Le quité su eterna bufanda de oro, le humedecí las sienes y le di de beber, sin atreverme a hacerle pregunta alguna.", "zh": "我取下他身上永恒的金围巾，湿润了他的太阳穴，给他喝水，不敢问他任何问题。", "t": [100, 7212]}, {"es": "Me miró gravemente rodeándome el cuello con sus brazos.", "zh": "他严肃地用双臂搂住我的脖子。", "t": [7212, 11250]}, {"es": "Sentí latir su corazón, como el de un pajarillo que muere a tiros de carabina.", "zh": "他的心狂跳，如同被猎枪射中濒死的小鸟。", "t": [11250, 15300]}]}, {"id": "ch26p11", "audio": true, "sents": [{"es": "-Me alegra -dijo el principito- que hayas encontrado lo que faltaba a tu máquina.", "zh": "小王子说：“很高兴你找到了你机器缺少的东西。”", "t": [100, 5250]}, {"es": "Así podrás volver a tu tierra…", "zh": "这样你才能回到你的星球。", "t": [5250, 7250]}, {"es": "-¿Cómo lo sabes?", "zh": "你怎会知道？", "t": [7250, 8063]}]}, {"id": "ch26p12", "audio": true, "sents": [{"es": "Precisamente venía a comunicarle que, a pesar de que no lo esperaba, había logrado terminar mi trabajo.", "zh": "我正要告诉他，尽管我没想到，但我已经完成了我的工作。", "t": [100, 5537]}]}, {"id": "ch26p13", "audio": true, "sents": [{"es": "No respondió a mi pregunta, sino que añadió:", "zh": "他没有回答我的问题，反而又补充道：", "t": [100, 2400]}]}, {"id": "ch26p14", "audio": true, "sents": [{"es": "-También yo vuelvo hoy a mi planeta…", "zh": "我也将今天回到我的星球上……", "t": [100, 1862]}]}, {"id": "ch26p15", "audio": true, "sents": [{"es": "Luego, con melancolía:", "zh": "随后，带着忧郁：", "t": [100, 1400]}]}, {"id": "ch26p16", "audio": true, "sents": [{"es": "-Es mucho más lejos…", "zh": "这远得多……", "t": [100, 1400]}, {"es": "y más difícil…", "zh": "更难……", "t": [1400, 2200]}]}, {"id": "ch26p17", "audio": true, "sents": [{"es": "Me daba cuenta de que algo extraordinario pasaba en aquellos momentos.", "zh": "我意识到那时正发生着非同寻常的事情。", "t": [100, 4662]}, {"es": "Estreché al principito entre mis brazos como sí fuera un niño pequeño, y no obstante, me pareció que descendía en picada hacia un abismo sin que fuera posible hacer nada para retenerlo.", "zh": "将他紧紧搂在怀里，如同他是小孩子，然而我感觉他正急速坠入深渊，而我却无力挽留。", "t": [4662, 13862]}]}, {"id": "ch26p18", "audio": true, "sents": [{"es": "Su mirada, seria, estaba perdída en la lejanía.", "zh": "他的目光，深邃，迷失在遥远的天际。", "t": [100, 2725]}]}, {"id": "ch26p19", "audio": true, "sents": [{"es": "Tengo tu cordero y la caja para el cordero.", "zh": "我有你的绵羊和绵羊的箱子。", "t": [100, 3088]}, {"es": "Y tengo tambíén el bozal.", "zh": "我也有她的口罩。", "t": [3088, 4550]}]}, {"id": "ch26p20", "audio": true, "sents": [{"es": "Y sonreía melancólicamente.", "zh": "他凄凉地笑了笑。", "t": [100, 1850]}]}, {"id": "ch26p21", "audio": true, "sents": [{"es": "Esperé un buen rato.", "zh": "等待了许久。", "t": [100, 2325]}, {"es": "Sentía que volvía a entrar en calor poco a poco:", "zh": "他感觉身体逐渐恢复了温暖。", "t": [2325, 4900]}]}, {"id": "ch26p22", "audio": true, "sents": [{"es": "-Has tenido miedo, muchachito…", "zh": "小家伙，你害怕了……", "t": [100, 1775]}]}, {"id": "ch26p23", "audio": true, "sents": [{"es": "Lo había tenido, sin duda, pero sonrió con dulzura:", "zh": "他曾经拥有过，但微笑中带着甜蜜：", "t": [100, 2862]}]}, {"id": "ch26p24", "audio": true, "sents": [{"es": "-Esta noche voy a tener más miedo…", "zh": "今夜我会更加害怕……", "t": [100, 1937]}]}, {"id": "ch26p25", "audio": true, "sents": [{"es": "Me quedé de nuevo helado por un sentimiento de algo irreparable.", "zh": "我再次被一种无法弥补的感觉冻僵。", "t": [100, 4300]}, {"es": "Comprendí que no podía soportar la idea de no volver a oír nunca más su risa.", "zh": "我明白，我无法忍受永远听不到他笑声的想法。", "t": [4300, 9212]}, {"es": "Era para mí como una fuente en el desierto.", "zh": "如同沙漠中的一口井。", "t": [9212, 11387]}]}, {"id": "ch26p26", "audio": true, "sents": [{"es": "-Muchachito, quiero oír otra vez tu risa…", "zh": "小家伙，我想再听一次你的笑声……", "t": [100, 2438]}]}, {"id": "ch26p27", "audio": true, "sents": [{"es": "Pero él me dijo:", "zh": "但他对我说：", "t": [100, 850]}]}, {"id": "ch26p28", "audio": true, "sents": [{"es": "-Esta noche hará un año.", "zh": "今夜是一周年。", "t": [100, 2438]}, {"es": "Mi estrella se encontrará precisamente encima del lugar donde caí el año pasado…", "zh": "我的星星将正好落在去年我坠落的地方上方……", "t": [2438, 6775]}]}, {"id": "ch26p29", "audio": true, "sents": [{"es": "-¿No es cierto -le interrumpí- que toda esta historia de serpientes, de citas y de estrellas es tan sólo una pesadilla?", "zh": "这蛇、约会、星星的故事，莫非只是一场噩梦？", "t": [100, 6575]}]}, {"id": "ch26p30", "audio": true, "sents": [{"es": "Pero el principito no respondió a mi pregunta y dijo:", "zh": "小王子没有回答我的问题，他说：", "t": [100, 2700]}]}, {"id": "ch26p31", "audio": true, "sents": [{"es": "-Lo más importante nunca se ve…", "zh": "最重要的东西永远看不见。", "t": [100, 1700]}]}, {"id": "ch26p32", "audio": true, "sents": [{"es": "-Indudablemente…", "zh": "毫无疑问…", "t": [100, 1062]}]}, {"id": "ch26p33", "audio": true, "sents": [{"es": "-Es lo mismo que la flor.", "zh": "这朵花也是一样。", "t": [100, 2300]}, {"es": "Si te gusta una flor que habita en una estrella, es muy dulce mirar al cielo por la noche.", "zh": "若你爱上了一朵长在星星上的花，夜晚仰望星空便格外甜蜜。", "t": [2300, 6938]}]}, {"id": "ch26p34", "audio": true, "sents": [{"es": "Todas las estrellas han florecido.", "zh": "所有的星星都绽放了。", "t": [100, 1900]}]}, {"id": "ch26p35", "audio": true, "sents": [{"es": "-Es indudable…", "zh": "毫无疑问…", "t": [100, 962]}]}, {"id": "ch26p36", "audio": true, "sents": [{"es": "-Es como el agua.", "zh": "宛如流水。", "t": [100, 2012]}, {"es": "La que me diste a beber, gracias a la roldana y la cuerda, era como una música ¿te acuerdas?", "zh": "你喝的水，因了辘轳和绳索，宛如音乐……你记得……它是甘甜的。", "t": [2012, 7962]}, {"es": "¡Qué buena era!", "zh": "多么美好啊！", "t": [7962, 8700]}]}, {"id": "ch26p37", "audio": true, "sents": [{"es": "-Sí, cierto…", "zh": "是的，当然。", "t": [100, 963]}]}, {"id": "ch26p38", "audio": true, "sents": [{"es": "-Por la noche mirarás las estrellas; mi casa es demasiado pequeña para que yo pueda señalarte dónde se encuentra.", "zh": "你夜里会仰望星空；我的家太小，无法指给你它在何方。", "t": [100, 6688]}, {"es": "Así es mejor; mi estrella será para ti una cualquiera de ellas.", "zh": "这样更好；我的星星将是你众多星星中的一颗。", "t": [6688, 11338]}, {"es": "Te gustará entonces mirar todas las estrellas.", "zh": "你将喜欢凝视所有的星星。", "t": [11338, 14850]}, {"es": "Todas ellas serán tus amigas.", "zh": "它们都将成为你的朋友。", "t": [14850, 17538]}, {"es": "Y además, te haré un regalo…", "zh": "此外，我还将送你一份礼物……", "t": [17538, 19050]}]}, {"id": "ch26p39", "audio": true, "sents": [{"es": "Y rió una vez más.", "zh": "他又笑了。", "t": [100, 2238]}, {"es": "-¡Ah, muchachito, muchachito, cómo me gusta oír tu risa!", "zh": "啊，小家伙，小家伙，我喜欢听你的笑声！", "t": [2238, 5276]}]}, {"id": "ch26p40", "audio": true, "sents": [{"es": "-Mi regalo será ése precisamente, será como el agua…", "zh": "我的礼物将正是那样，就像水一样……", "t": [100, 3112]}, {"es": "-¿Qué quieres decir?", "zh": "你想说什么？", "t": [3112, 4038]}]}, {"id": "ch26p41", "audio": true, "sents": [{"es": "La gente tiene estrellas que no son las mismas.", "zh": "人们各有各的星星。", "t": [100, 3575]}, {"es": "Para los que viajan, las estrellas son guías; para otros sólo son pequeñas lucecítas.", "zh": "对旅行者而言，星星是向导；对其他人而言，它们只是小小的灯火。", "t": [3575, 9188]}, {"es": "Para los sabios las estrellas son problemas.", "zh": "对智者而言，星星是难题。", "t": [9188, 12400]}, {"es": "Para mi hombre de negocios, eran oro.", "zh": "对商人来说，它们是金子。", "t": [12400, 15338]}, {"es": "Pero todas esas estrellas se callan.", "zh": "但所有的星星都沉默着。", "t": [15338, 18262]}, {"es": "Tú tendrás estrellas como nadie ha tenido…", "zh": "你将拥有别人未曾拥有的星星。", "t": [18262, 20662]}, {"es": "-¿Qué quieres decir?", "zh": "你想说什么？", "t": [20662, 22525]}, {"es": "-Cuando por las noches mires al cielo, al pensar que en una de aquellas estrellas estoy yo riendo, será para ti como si todas las estrellas riesen.", "zh": "当你在夜晚仰望星空，想到我在其中一颗星星上微笑，那对你来说，就如同所有的星星都在欢笑。", "t": [22525, 31012]}, {"es": "¡Tú sólo tendrás estrellas que saben reír!", "zh": "你将拥有会笑的星星。", "t": [31012, 33262]}]}, {"id": "ch26p42", "audio": true, "sents": [{"es": "Y rió nuevamente.", "zh": "他又笑了。", "t": [100, 1150]}]}, {"id": "ch26p43", "audio": true, "sents": [{"es": "-Cuando te hayas consolado (siempre se consuela uno) estarás contento de haberme conocido.", "zh": "当你在安慰自己（人总是自我安慰）后，你会为认识我而感到高兴。", "t": [100, 6025]}, {"es": "Serás mi amigo y tendrás ganas de reír conmigo.", "zh": "你将成为我的朋友，愿意与我一同欢笑。", "t": [6025, 9575]}, {"es": "Algunas veces abrirás tu ventana sólo por placer y tus amigos quedarán asombrados de verte reír mirando al cielo.", "zh": "有时，你只为了开心而打开窗户，你的朋友们会惊讶地看到你仰望天空而笑。", "t": [9575, 16450]}, {"es": "Tú les explicarás: \"Las estrellas me hacen reír siempre\".", "zh": "你将告诉他们：“星星总是让我发笑。”", "t": [16450, 20575]}, {"es": "Ellos te creerán loco.", "zh": "他们定会认为你疯了。", "t": [20575, 22925]}, {"es": "Y yo te habré jugado una mala pasada…", "zh": "我可能曾捉弄了你一番…", "t": [22925, 24950]}]}, {"id": "ch26p44", "audio": true, "sents": [{"es": "Y se rió otra vez.", "zh": "他又笑了。", "t": [100, 1187]}]}, {"id": "ch26p45", "audio": true, "sents": [{"es": "-Será como si en vez de estrellas, te hubiese dado multitud de cascabelitos que saben reír…", "zh": "仿佛我给了你无数会笑的铃铛……", "t": [100, 4726]}]}, {"id": "ch26p46", "audio": true, "sents": [{"es": "Una vez más dejó oír su risa y luego se puso serio.", "zh": "他又笑了，然后变得严肃起来。", "t": [100, 3075]}]}, {"id": "ch26p47", "audio": true, "sents": [{"es": "-Esta noche ¿sabes?", "zh": "今夜，你知道吗？", "t": [100, 1375]}, {"es": "no vengas…", "zh": "别来了。", "t": [1375, 1988]}]}, {"id": "ch26p48", "audio": true, "sents": [{"es": "-No te dejaré.", "zh": "我不会让你离开。", "t": [100, 875]}]}, {"id": "ch26p49", "audio": true, "sents": [{"es": "-Pareceré enfermo…", "zh": "我看起来会病得很重……", "t": [100, 2038]}, {"es": "Parecerá un poco que me muero…", "zh": "似乎我快要死了……", "t": [2038, 3700]}, {"es": "es así.", "zh": "如此而已。", "t": [3700, 5150]}, {"es": "¡No vale la pena que vengas a ver eso…!", "zh": "那不值得你来看……", "t": [5150, 7076]}]}, {"id": "ch26p50", "audio": true, "sents": [{"es": "-No te dejaré.", "zh": "我不会让你离开。", "t": [100, 875]}]}, {"id": "ch26p51", "audio": true, "sents": [{"es": "Pero estaba preocupado.", "zh": "但他忧心忡忡。", "t": [100, 1363]}]}, {"id": "ch26p52", "audio": true, "sents": [{"es": "-Te digo esto por la serpiente; no debe morderte.", "zh": "我这么说是因为蛇；它不应该咬你。", "t": [100, 3812]}, {"es": "Las serpientes son malas.", "zh": "蛇是恶毒的。", "t": [3812, 6288]}, {"es": "A veces muerden por gusto…", "zh": "有时，它们是出于乐趣而咬人。", "t": [6288, 7737]}]}, {"id": "ch26p53", "audio": true, "sents": [{"es": "-He dicho que no te dejaré.", "zh": "他说，我不会让你离开。", "t": [100, 1325]}]}, {"id": "ch26p54", "audio": true, "sents": [{"es": "Pero algo lo tranquilizó.", "zh": "但某种东西让他平静下来。", "t": [100, 1338]}]}, {"id": "ch26p55", "audio": true, "sents": [{"es": "-Bien es verdad que no tienen veneno para la segunda mordedura…", "zh": "确实，它们第二次咬人时没有毒液了。", "t": [100, 3176]}]}, {"id": "ch26p56", "audio": true, "sents": [{"es": "Aquella noche no lo vi ponerse en camino.", "zh": "那晚我没有看到他踏上归途。", "t": [100, 3212]}, {"es": "Cuando le alcancé marchaba con paso rápido y decidido y me dijo solamente: -¡Ah, estás ahí!", "zh": "他快步走来，只说了句：“啊，你在这儿！”", "t": [3212, 8025]}]}, {"id": "ch26p57", "audio": true, "sents": [{"es": "Me cogió de la mano y todavía se atormentó:", "zh": "他紧紧握住我的手，心中仍受折磨。", "t": [100, 2338]}]}, {"id": "ch26p58", "audio": true, "sents": [{"es": "-Has hecho mal.", "zh": "你做错了。", "t": [100, 1812]}, {"es": "Tendrás pena.", "zh": "你会感到难过。", "t": [1812, 3612]}, {"es": "Parecerá que estoy muerto, pero no es verdad.", "zh": "似乎我已死去，实则不然。", "t": [3612, 5924]}]}, {"id": "ch26p59", "audio": true, "sents": [{"es": "Yo me callaba.", "zh": "我自称。", "t": [100, 1912]}, {"es": "-¿Comprendes?", "zh": "你懂了吗？", "t": [1912, 3612]}, {"es": "Es demasiado lejos y no puedo llevar este cuerpo que pesa demasiado.", "zh": "这太过遥远，我拖不动这副沉重的皮囊。", "t": [3612, 7063]}]}, {"id": "ch26p60", "audio": true, "sents": [{"es": "-Seguí callado.", "zh": "他默默跟随。", "t": [100, 900]}]}, {"id": "ch26p61", "audio": true, "sents": [{"es": "-Será como una corteza vieja que se abandona.", "zh": "如同褪去的旧皮。", "t": [100, 3425]}, {"es": "No son nada tristes las viejas cortezas…", "zh": "旧树皮并不悲伤…", "t": [3425, 5825]}]}, {"id": "ch26p62", "audio": true, "sents": [{"es": "Yo me callaba.", "zh": "我自称。", "t": [100, 1912]}, {"es": "El principito perdió un poco de ánimo.", "zh": "小王子有些泄气了。", "t": [1912, 4875]}, {"es": "Pero hizo un esfuerzo y dijo:", "zh": "但他努力说道：", "t": [4875, 6463]}]}, {"id": "ch26p63", "audio": true, "sents": [{"es": "Será agradable ¿sabes?", "zh": "你知道，这会令人愉快。", "t": [100, 2638]}, {"es": "Yo miraré también las estrellas.", "zh": "我也会仰望星空。", "t": [2638, 5375]}, {"es": "Todas serán pozos con roldana herrumbrosa.", "zh": "所有的井都将带着生锈的辘轳。", "t": [5375, 8662]}, {"es": "Todas las estrellas me darán de beber.", "zh": "所有的星星都将让我解渴。", "t": [8662, 10650]}]}, {"id": "ch26p64", "audio": true, "sents": [{"es": "Yo me callaba.", "zh": "我自称。", "t": [100, 1912]}, {"es": "-¡Será tan divertido!", "zh": "那会非常有趣！", "t": [1912, 3988]}, {"es": "Tú tendrás quinientos millones de cascabeles y yo quinientos millones de fuentes…", "zh": "你将拥有五亿个小铃铛，而我将拥有五亿口井……", "t": [3988, 7937]}]}, {"id": "ch26p65", "audio": true, "sents": [{"es": "El principito se calló también; estaba llorando.", "zh": "小王子也沉默了，他在哭泣。", "t": [100, 2700]}]}, {"id": "ch26p66", "audio": true, "sents": [{"es": "-Es allí; déjame ir solo.", "zh": "那里；让我独自去吧。", "t": [100, 1888]}]}, {"id": "ch26p67", "audio": true, "sents": [{"es": "Se sentó porque tenía miedo.", "zh": "他坐下是因为害怕。", "t": [100, 2638]}, {"es": "Dijo aún: -¿Sabes?…", "zh": "他还说：“你知道吗？”", "t": [2638, 4888]}, {"es": "mi flor…", "zh": "我的玫瑰…", "t": [4888, 5612]}, {"es": "soy responsable…", "zh": "我负有责任…", "t": [5612, 6800]}, {"es": "¡y ella es tan débil y tan inocente!", "zh": "她如此柔弱，又如此纯真。", "t": [6800, 9750]}, {"es": "Sólo tiene cuatro espinas para defenderse contra todo el mundo…", "zh": "她只有四根刺来抵御整个世界…", "t": [9750, 13013]}]}, {"id": "ch26p68", "audio": true, "sents": [{"es": "Me senté, ya no podía mantenerme en pie.", "zh": "我坐了下来，已无法站立。", "t": [100, 2276]}]}, {"id": "ch26p69", "audio": true, "sents": [{"es": "-Ahí está…", "zh": "那里有…", "t": [100, 1038]}, {"es": "eso es todo…", "zh": "这就是全部……", "t": [1038, 1800]}]}, {"id": "ch26p70", "audio": true, "sents": [{"es": "Vacíló todavía un instante, luego se levantó y dio un paso.", "zh": "他愣了一下，然后站起身，向前迈了一步。", "t": [100, 4325]}, {"es": "Yo no pude moverme.", "zh": "我无法动弹。", "t": [4325, 5413]}]}, {"id": "ch26p71", "audio": true, "sents": [{"es": "Un relámpago amarillo centelleó en su tobillo.", "zh": "一道黄色闪电在他脚踝处闪烁。", "t": [100, 3600]}, {"es": "Quedó un instante inmóvil, sin exhalar un grito.", "zh": "瞬间，他静止不动，未发出一声呼喊。", "t": [3600, 7238]}, {"es": "Luego cayó lentamente camo cae un árbol, sin hacer el menor ruido a causa de la arena.", "zh": "然后，那棵树缓缓倒下，沙地中悄无声息。", "t": [7238, 11863]}]}]}, {"id": "ch27", "title_es": "Capítulo 27", "title_zh": "第 27 章", "paras": [{"id": "ch27p00", "audio": true, "sents": [{"es": "Ahora hace ya seis años de esto.", "zh": "这已是六年前的事了。", "t": [100, 3000]}, {"es": "Jamás he contado esta historia y los compañeros que me vuelven a ver se alegran de encontrarme vivo.", "zh": "我从没讲过这个故事，他们看到我活着回来，都为我感到高兴。", "t": [3000, 8688]}, {"es": "Estaba triste, pero yo les decía: \"Es el cansancio\".", "zh": "我虽心绪沉重，却对他们说：“只是累罢了。”", "t": [8688, 11788]}]}, {"id": "ch27p01", "audio": true, "sents": [{"es": "AI correr del tiempo me he consolado un poco, pero no completamente.", "zh": "时间流逝，我略感慰藉，却未完全释怀。", "t": [100, 4525]}, {"es": "Sé que ha vuelto a su planeta, pues al amanecer no encontré su cuerpo, que no era en realidad tan pesado…", "zh": "我知道他已返回自己的星球，因为天亮时我没有找到他的遗体，而他其实并不沉重。", "t": [4525, 10850]}, {"es": "Y me gusta por la noche escuchar a las estrellas, que suenan como quinientos millones de cascabeles…", "zh": "夜幕降临，我偏爱聆听星星的细语，它们宛如五亿个铃铛在响。", "t": [10850, 15862]}]}, {"id": "ch27p02", "audio": true, "sents": [{"es": "Pero sucede algo extraordinario.", "zh": "然而，发生了非同寻常的事。", "t": [100, 2862]}, {"es": "AI bozal que dibujé para el principito se me olvidó añadirle la correa de cuero; no habrá podido atárselo al cordero.", "zh": "我给小王子画的口罩忘了加上皮带了，他大概没法给羊儿戴上。", "t": [2862, 9762]}, {"es": "Entonces me pregunto:", "zh": "那么，我自问：", "t": [9762, 10975]}]}, {"id": "ch27p03", "audio": true, "sents": [{"es": "\"¿Qué habrá sucedido en su planeta?", "zh": "他星球上出了什么事？", "t": [100, 2688]}, {"es": "Quízás el cordero se ha comido la flor…\"", "zh": "或许绵羊把花儿吃掉了……", "t": [2688, 4676]}]}, {"id": "ch27p04", "audio": true, "sents": [{"es": "A veces me digo: \"¡Seguro que no!", "zh": "或许我对自己说：“肯定不会吧！”", "t": [100, 2762]}, {"es": "El príncipito cubre la flor con su fanal todas las noches y vigila a su cordero\".", "zh": "小王子每晚用灯笼守护着他的玫瑰。", "t": [2762, 6900]}]}, {"id": "ch27p05", "audio": true, "sents": [{"es": "Entonces me siento dichoso y todas las estrellas ríen dulcemente.", "zh": "于是我心怀感激，群星便温柔地笑了起来。", "t": [100, 3675]}]}, {"id": "ch27p06", "audio": true, "sents": [{"es": "Pero otras veces pienso: \"Alguna que otra vez se distrae uno y eso basta.", "zh": "但有时我又想：“人难免会疏忽，这已足够糟糕。”", "t": [100, 5262]}, {"es": "Si una noche ha olvidado poner el fanal o el cordero ha salido sin hacer ruido, durante la noche…\".", "zh": "若是在某个夜晚他忘了点亮灯笼，或者羊儿悄无声息地溜出了门，在夜色中……", "t": [5262, 11175]}, {"es": "Y entonces los cascabeles se convierten en lágrimas…", "zh": "于是，铃铛变成了泪珠……", "t": [11175, 13926]}]}, {"id": "ch27p07", "audio": true, "sents": [{"es": "Y ahí está el gran misterio.", "zh": "那便是个巨大的谜团。", "t": [100, 2600]}, {"es": "Para ustedes que quieren al principito, lo mismo que para mí, nada en el universo habrá cambiado si en cualquier parte, quien sabe dónde, un cordero desconocido se ha comido o no se ha comido una rosa…", "zh": "对你们这些喜爱小王子的人来说，就如同对我一样，无论在宇宙的哪个角落，谁也不知道，一只未知的绵羊是否曾吃过或未曾吃过一朵玫瑰。", "t": [2600, 12426]}]}, {"id": "ch27p08", "audio": true, "sents": [{"es": "Pero miren al cielo y pregúntense: el cordero ¿se ha comido la flor?", "zh": "但请仰望星空，自问：那绵羊，它是否吞食了那朵花？", "t": [100, 4950]}, {"es": "Y veréis cómo todo cambia…", "zh": "你们就会看到，一切都变了……", "t": [4950, 7312]}, {"es": "¡Ninguna persona mayor comprenderá jamás que esto sea verdaderamente importante!", "zh": "没有一个大人能真正明白，这有多么重要。", "t": [7312, 11450]}]}, {"id": "ch27p09", "audio": true, "sents": [{"es": "Este es para mí el paisaje más hermoso y el más triste del mundo.", "zh": "这是世上最美又最凄凉的风光。", "t": [100, 3462]}]}, {"id": "ch27p10", "audio": true, "sents": [{"es": "Es el mismo paisaje de la página anterior que he dibujado una vez más para que lo vean bien.", "zh": "这幅画与上一页的风景相同，我又画了一次，以便你们能看清楚。", "t": [100, 5512]}, {"es": "Fue aquí donde el principito apareció sobre la Tierra, desapareciendo luego.", "zh": "小王子就是在这里降临地球，然后又从这里离去。", "t": [5512, 9487]}]}, {"id": "ch27p11", "audio": true, "sents": [{"es": "Exaxnínenlo atentamente para que sepan reconocerlo, si algún día, viajando por Africa cruzan el desierto.", "zh": "请仔细辨认，若某日你们穿越非洲沙漠旅行时。", "t": [100, 7025]}, {"es": "Si por casualidad pasan por allí, no se apresuren, se los ruego, y deténganse un poco, precisamente bajo la estrella.", "zh": "若偶尔经过此地，切莫急匆匆，我恳请你们，请驻足片刻，就在那颗星星之下。", "t": [7025, 14325]}, {"es": "Si un niño llega hasta ustedes, si este niño ríe y tiene cabellos de oro y nunca responde a sus preguntas, adivinarán en seguida quién es.", "zh": "若有个孩子来到你们身边，他笑得灿烂，金发闪耀，却从不回答你们的问题，你们很快就会猜出他是谁。", "t": [14325, 22800]}, {"es": "¡Sean amables con él!", "zh": "请对他好些。", "t": [22800, 24025]}]}, {"id": "ch27p12", "audio": true, "sents": [{"es": "Y comuníquenme rápidamente que ha regresado.", "zh": "请速速告知我他已归来。", "t": [100, 3438]}, {"es": "¡No me dejen tan triste!", "zh": "让我别如此悲伤！", "t": [3438, 4775]}]}]}]}